function genDaily(g,days=120){
 if(!g.p) return [];
 const r=rng(hash(g.id)), p=g.p, n=Math.min(p.days||days,days), out=[];
 for(let i=n-1;i>=0;i--){
  const dt=new Date(Date.now()-i*864e5), t=(n-1-i)/Math.max(1,n-1), wd=dt.getDay();
  const wk=(wd===5||wd===6)?1.14:(wd===4?1.06:1), grow=1+p.trend*t, nz=()=>1+(r()-.5)*.16;
  const inst=Math.round(p.inst*grow*wk*nz()), paid=Math.round(inst*(.42+r()*.12));
  const dau=Math.round(p.dau*grow*wk*nz()), ses=+(p.ses*nz()).toFixed(2), imp=Math.round(dau*ses*(1.6+r()*.3));
  const ecpm=p.ecpm*(1+(r()-.5)*.16)*(p.ecpmDrop&&i<7?.8:1)*(1+.08*Math.sin(t*6));
  const ad=imp*ecpm/1000, iap=ad*p.iap/(1-p.iap)*nz();
  out.push({g:g.id,d:iso(dt),inst,paid,dau,ses,len:+(p.len*nz()).toFixed(1),imp,ad:+ad.toFixed(2),iap:+iap.toFixed(2),ua:+(p.ua*grow*nz()).toFixed(2),
   d1:+clamp(p.d1+(r()-.5)*.04,0,1).toFixed(3),d7:+clamp(p.d7+(r()-.5)*.03,0,1).toFixed(3),d30:+clamp(p.d30+(r()-.5)*.015,0,1).toFixed(3),
   crash:+clamp(p.crash+(r()-.5)*.3,90,100).toFixed(2),rating:+clamp(p.rating+(r()-.5)*.1,1,5).toFixed(2)});
 }
 return out;
}
function genFunnel(g){
 if(!g.p) return null;
 const r=rng(hash(g.id+'f')), marks=g.levels>=300?[1,5,10,20,30,50,75,100,150,200,250,300]:g.levels>=60?[1,3,5,10,15,20,30,40,50,60]:[1,3,5,10,20,30,40,50];
 let v=100;const out=[];
 marks.forEach((m,i)=>{ if(i>0){const drop=(i===g.p.spike?.34:.10+r()*.10);v=v*(1-drop)} out.push([m,+v.toFixed(1)])});
 return out;
}
