/* ================= persistence ================= */
const KEY='spotlight-game-hq.v1';
function migrateGames(s){
 if((s.gamesV||0)>=REAL_GAMES_V)return s;
 const gone=new Set(['ring','hollow']), real=seedGames(), have=new Map((s.games||[]).map(g=>[g.id,g]));
 const list=real.map(r=>have.get(r.id)?{...have.get(r.id)}:{...r,funnel:null});
 (s.games||[]).forEach(g=>{if(!gone.has(g.id)&&!real.some(r=>r.id===g.id))list.push(g)});
 s.games=list;
 ['daily','campaigns','keywords','tasks','releases','incidents'].forEach(k=>{if(Array.isArray(s[k]))s[k]=s[k].filter(x=>!gone.has(x.g))});
 if(s.cc&&s.cc.items)s.cc.items=s.cc.items.filter(x=>!gone.has(x.g));
 ['checks','audit'].forEach(k=>{if(s[k])gone.forEach(id=>delete s[k][id])});
 if(gone.has(s.gf))s.gf='all';
 if(String(s.view||'').startsWith('game:')&&gone.has(s.view.slice(5)))s.view='games';
 s.gamesV=REAL_GAMES_V;return s;
}
/* On the website, signed-in users start empty: games come from the team workspace and the server's game list, never from the preview templates. */
function cloudFresh(n){Object.assign(n,{games:[],daily:[],campaigns:[],keywords:[],tasks:[],releases:[],incidents:[],costs:[],checks:{},sample:false});n.cc={budget:{},items:[]};return n}
function load(){try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&s.v===1)return window.KN_CLOUD&&s.cloudV?s:migrateGames(s)}catch(e){}const n=seedState();n.gamesV=REAL_GAMES_V;if(window.KN_CLOUD){cloudFresh(n);n.cloudV=1}return n}
let saveT;function save(){if(window.KN_CLOUD&&C.leaving)return;clearTimeout(saveT);saveT=setTimeout(()=>{if(window.KN_CLOUD&&C.leaving)return;try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){}},200);if(window.KN_CLOUD)wsTrack()}
S=load();

