const NF=new Intl.NumberFormat('en-US');
function money(v,dec){const x=S.cur==='SAR'?v*3.75:v;const a=Math.abs(x);const d=dec??(a<10?2:0);let s;
 if(a>=1e6)s=(x/1e6).toFixed(2)+'M';else if(a>=1e4)s=(x/1e3).toFixed(1)+'K';else s=x.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
 return S.cur==='SAR'?(S.lang==='ar'?s+' ر.س':'SAR '+s):'$'+s}
function moneyS(v){const neg=v<0;return (neg?'−':'')+money(Math.abs(v))}
const num=v=>{const a=Math.abs(v);if(a>=1e6)return(v/1e6).toFixed(2)+'M';if(a>=1e4)return(v/1e3).toFixed(1)+'K';return NF.format(Math.round(v))};
const pct=(v,d=1)=>(v*100).toFixed(d)+'%';
