/* ================= analytics ================= */
function rowsFor(gf,days,offset=0){
 const end=new Date(Date.now()-offset*864e5), start=new Date(end-(days-1)*864e5), a=iso(start), b=iso(end);
 return S.daily.filter(r=>(gf==='all'||r.g===gf)&&r.d>=a&&r.d<=b);
}
function agg(rows){
 const o={inst:0,paid:0,dau:0,imp:0,ad:0,iap:0,ua:0,sesW:0,sesN:0,lenW:0,lenN:0,d1W:0,d1N:0,d7W:0,d7N:0,d30W:0,d30N:0,crashW:0,crashN:0,days:new Set()};
 const ok=v=>v!=null&&v!==''&&Number.isFinite(+v);
 rows.forEach(r=>{const inst=+r.inst||0,dau=+r.dau||0;o.inst+=inst;o.paid+=+r.paid||0;o.dau+=dau;o.imp+=+r.imp||0;o.ad+=+r.ad||0;o.iap+=+r.iap||0;o.ua+=+r.ua||0;
  if(ok(r.ses)){o.sesW+=r.ses*dau;o.sesN+=dau}if(ok(r.len)){o.lenW+=r.len*dau;o.lenN+=dau}
  if(ok(r.d1)){o.d1W+=r.d1*inst;o.d1N+=inst}if(ok(r.d7)){o.d7W+=r.d7*inst;o.d7N+=inst}if(ok(r.d30)){o.d30W+=r.d30*inst;o.d30N+=inst}
  if(ok(r.crash)){o.crashW+=r.crash*dau;o.crashN+=dau}o.days.add(r.d)});
 const n=o.days.size||1, fee=S.feeRate;
 const iapNet=o.iap*(1-fee), rev=o.ad+iapNet;
 const ratings=rows.filter(r=>ok(r.rating)&&r.rating>0);const lastByG={};ratings.forEach(r=>{if(!lastByG[r.g]||lastByG[r.g].d<r.d)lastByG[r.g]=r});
 const rl=Object.values(lastByG);
 return {inst:o.inst,paid:o.paid,dauAvg:o.dau/n,dauSum:o.dau,imp:o.imp,ad:o.ad,iap:o.iap,iapNet,fee:o.iap*fee,rev,ua:o.ua,
  arpdau:o.dau?rev/o.dau:0,ecpm:o.imp?o.ad/o.imp*1000:0,roas:o.ua?rev/o.ua:0,cpi:o.paid?o.ua/o.paid:0,
  sess:o.sesN?o.sesW/o.sesN:0,len:o.lenN?o.lenW/o.lenN:0,d1:o.d1N?o.d1W/o.d1N:0,d7:o.d7N?o.d7W/o.d7N:0,d30:o.d30N?o.d30W/o.d30N:0,
  crash:o.crashN?o.crashW/o.crashN:0,rating:rl.length?sum(rl.map(r=>+r.rating))/rl.length:0,n:o.days.size,
  has:{ret:o.d1N>0,crash:o.crashN>0}};
}
const CC_CATS={dev:['Development & freelancers','التطوير والمستقلون','Entwicklung & Freelancer','#27e2ff'],art:['Art, audio & video','الرسوم والصوت والفيديو','Grafik, Audio & Video','#ff2bd6'],tools:['Software & subscriptions','البرامج والاشتراكات','Software & Abos','#9b7bff'],store:['Store & accounts','المتجر والحسابات','Store & Konten','#ffb22e'],ops:['Servers, data & hosting','الخوادم والبيانات والاستضافة','Server, Daten & Hosting','#3dffa9'],qa:['Testing & devices','الاختبار والأجهزة','Tests & Geräte','#c4ff3d'],ua:['Marketing & user acquisition','التسويق والاستحواذ','Marketing & Nutzerakquise','#ff4f6e'],legal:['Company, legal & accounting','الشركة والقانون والمحاسبة','Firma, Recht & Buchhaltung','#7c74a0'],other:['Other','أخرى','Sonstiges','#b4acd4']};
const ccCat=k=>(CC_CATS[k]||CC_CATS.other)[L()];
const ccColor=k=>(CC_CATS[k]||CC_CATS.other)[3];
function ccGuess(n){n=String(n).toLowerCase();return /apple|google play|developer/.test(n)?'store':/replit|server|host|cloud|domain|firebase/.test(n)?'ops':/art|sound|music|asset|video|design/.test(n)?'art':/qa|test|device|iphone/.test(n)?'qa':/analytics|tool|software|figma|canva/.test(n)?'tools':/freelanc|dev/.test(n)?'dev':'other'}
function ccMigrate(){
 if(S.cc)return;
 const d=iso(new Date());
 S.cc={budget:{},items:(S.costs||[]).map(c=>({id:c.id||uid(),cat:ccGuess(c.n),name:c.n,g:'all',type:'monthly',amount:+c.v||0,date:d}))};
 if(S.sample)S.cc.items.push(
  {id:uid(),cat:'qa',name:'Test iPhone (used)',g:'all',type:'once',amount:350,date:d},
  {id:uid(),cat:'art',name:'Ruby Bounce music & SFX pack',g:'ruby',type:'once',amount:60,date:d},
  {id:uid(),cat:'ua',name:'Ad creative production',g:'brick',type:'monthly',amount:150,date:d},
  {id:uid(),cat:'dev',name:'Chess engine tuning (freelance)',g:'chess',type:'once',amount:400,date:d});
}
const ccMonthly=()=>{ccMigrate();return S.cc.items.filter(i=>i.type==='monthly')};
const fixedMonthly=()=>sum(ccMonthly().filter(i=>i.cat!=='ua').map(i=>+i.amount||0));
function fixedFor(days){return fixedMonthly()*days/30}
function series(gf,days,key){
 const rows=rowsFor(gf,days);const by={};rows.forEach(r=>{(by[r.d]=by[r.d]||[]).push(r)});
 const labels=[];for(let i=days-1;i>=0;i--)labels.push(iso(new Date(Date.now()-i*864e5)));
 return {labels,values:labels.map(d=>{const rs=by[d]||[];if(!rs.length)return null;const a=agg(rs);return typeof key==='function'?key(a,rs):a[key]})};
}
function retAt(d1,d7,day){if(day<=0)return 1;const b=Math.log(Math.max(d1,.001)/Math.max(d7,.0005))/Math.log(7);return d1*Math.pow(day,-b)}
function ltv(d1,d7,arpdau,N){let s=1;for(let t=1;t<=N;t++)s+=retAt(d1,d7,t);return s*arpdau}
function health(a){
 if(!a||!a.n)return null;
 const c=x=>clamp(x,0,1);
 return Math.round(100*(c(a.d1/.42)*.25+c(a.d7/.16)*.2+c(a.d30/.07)*.1+c((a.crash-98)/1.8)*.15+c((a.rating-3.5)/1.2)*.15+c(a.roas/1.3)*.15));
}
function benchClass(k,v){const b=BENCH[k];if(!b||v==null)return'';const inv=b[2]==='inv';
 if(inv)return v<=b[0]?'heat-good':v<=b[1]?'heat-ok':'heat-bad';return v>=b[1]?'heat-good':v>=b[0]?'heat-ok':'heat-bad'}
function campCalc(c){return {...c,ctr:c.imp?c.clk/c.imp:0,cvr:c.clk?c.inst/c.clk:0,cpi:c.inst?c.spend/c.inst:0,roas:c.spend?c.rev7/c.spend:0}}
function campRec(r){return r.roas>=.6?['rec_scale','heat-good']:r.roas>=.35?['rec_hold','heat-ok']:['rec_cut','heat-bad']}

/* ---- insights engine (computed from data) ---- */
function insights(){
 const out=[], days=S.period, live=S.games.filter(g=>g.p&&rowsFor(g.id,days).length);
 const A=live.map(g=>({g,a:agg(rowsFor(g.id,days))}));const N=g=>tx(g.name);
 if(A.length){
  const lowD1=[...A].sort((x,y)=>x.a.d1-y.a.d1)[0];
  if(lowD1.a.d1<BENCH.d1[0]) out.push({sev:'bad',t:{en:`${N(lowD1.g)} loses too many players on day 1`,ar:`${N(lowD1.g)} تخسر لاعبين كثيرين في اليوم الأول`,de:`${N(lowD1.g)} verliert an Tag 1 zu viele Spieler`},p:{en:`D1 is ${pct(lowD1.a.d1)} against a ${pct(BENCH.d1[0],0)}–${pct(BENCH.d1[1],0)} range. Rework the first session before adding UA budget.`,ar:`الاحتفاظ لليوم ١ ${pct(lowD1.a.d1)} مقابل نطاق ${pct(BENCH.d1[0],0)}–${pct(BENCH.d1[1],0)}. أعد بناء الجلسة الأولى قبل زيادة الميزانية.`,de:`D1 liegt bei ${pct(lowD1.a.d1)} gegenüber einem Bereich von ${pct(BENCH.d1[0],0)}–${pct(BENCH.d1[1],0)}. Überarbeiten Sie die erste Sitzung, bevor Sie das UA-Budget erhöhen.`}});
  const best=[...A].sort((x,y)=>y.a.roas-x.a.roas)[0];
  out.push({sev:'good',t:{en:`${N(best.g)} returns the most per ad dollar`,ar:`${N(best.g)} تحقق أعلى عائد لكل دولار إعلاني`,de:`${N(best.g)} bringt pro Werbedollar am meisten`},p:{en:`Blended ROAS ${best.a.roas.toFixed(2)}× with ARPDAU ${money(best.a.arpdau,3)}. It should receive the largest share of next month's budget.`,ar:`العائد المختلط ${best.a.roas.toFixed(2)}× وARPDAU ${money(best.a.arpdau,3)}. يجب أن تحصل على الحصة الأكبر من ميزانية الشهر القادم.`,de:`Blended ROAS ${best.a.roas.toFixed(2)}× bei ARPDAU ${money(best.a.arpdau,3)}. Dieses Spiel sollte den größten Anteil am Budget des nächsten Monats erhalten.`}});
  A.forEach(({g})=>{const w1=agg(rowsFor(g.id,7)),w0=agg(rowsFor(g.id,7,7));if(w0.ecpm&&w1.ecpm/w0.ecpm<.88){const dr=pct(1-w1.ecpm/w0.ecpm,0);out.push({sev:'warn',t:{en:`${N(g)} eCPM fell ${dr} week over week`,ar:`انخفض eCPM في ${N(g)} بنسبة ${dr} أسبوعياً`,de:`eCPM von ${N(g)} ist zur Vorwoche um ${dr} gefallen`},p:{en:`Now ${money(w1.ecpm)} vs ${money(w0.ecpm)}. Check mediation waterfall floors and whether a network stopped bidding.`,ar:`الآن ${money(w1.ecpm)} مقابل ${money(w0.ecpm)}. راجع أرضيات الوساطة وهل توقفت شبكة عن المزايدة.`,de:`Jetzt ${money(w1.ecpm)} statt ${money(w0.ecpm)}. Prüfen Sie die Floors im Mediation-Wasserfall und ob ein Netzwerk nicht mehr bietet.`}})}});
  A.forEach(({g,a})=>{if(a.crash<99.3)out.push({sev:'bad',t:{en:`${N(g)} crash-free rate is ${a.crash.toFixed(2)}%`,ar:`نسبة الجلسات بدون أعطال في ${N(g)} ${a.crash.toFixed(2)}%`,de:`Absturzfreie Rate von ${N(g)} liegt bei ${a.crash.toFixed(2)} %`},p:{en:'Below 99.5% hurts ratings and review approval. Fix crashes before the next feature release.',ar:'أقل من ٩٩٫٥٪ يضر التقييم وقبول المراجعة. أصلح الأعطال قبل الإصدار القادم.',de:'Unter 99,5 % leiden Bewertungen und die App-Prüfung. Beheben Sie Abstürze vor dem nächsten Feature-Release.'}})});
  S.games.forEach(g=>{if(!g.funnel)return;let mx=0,at=null;for(let i=1;i<g.funnel.length;i++){const dr=1-g.funnel[i][1]/g.funnel[i-1][1];if(dr>mx){mx=dr;at=[g.funnel[i-1][0],g.funnel[i][0]]}}if(mx>.25)out.push({sev:'warn',t:{en:`Difficulty spike in ${N(g)}, levels ${at[0]}–${at[1]}`,ar:`قفزة صعوبة في ${N(g)} بين المراحل ${at[0]}–${at[1]}`,de:`Schwierigkeitsspitze in ${N(g)}, Level ${at[0]}–${at[1]}`},p:{en:`${pct(mx,0)} of players stop in this stretch. Add a hint or rebalance one level.`,ar:`${pct(mx,0)} من اللاعبين يتوقفون هنا. أضف تلميحاً أو أعد موازنة مرحلة.`,de:`${pct(mx,0)} der Spieler hören in diesem Abschnitt auf. Fügen Sie einen Hinweis hinzu oder balancieren Sie ein Level neu.`}})});
  const all=rowsFor('all',28);let we=0,wen=0,wd=0,wdn=0;const byD={};all.forEach(r=>{byD[r.d]=(byD[r.d]||0)+r.dau});Object.entries(byD).forEach(([d,v])=>{const k=new Date(d+'T12:00:00').getDay();if(k===5||k===6){we+=v;wen++}else{wd+=v;wdn++}});
  if(wen&&wdn){const lift=(we/wen)/(wd/wdn)-1;if(lift>.04)out.push({sev:'info',t:{en:`Weekend DAU runs ${pct(lift,0)} higher (Fri–Sat)`,ar:`المستخدمون في نهاية الأسبوع أعلى بنسبة ${pct(lift,0)} (الجمعة–السبت)`,de:`DAU am Wochenende liegt ${pct(lift,0)} höher (Fr–Sa)`},p:{en:'Start events on Thursday evening and schedule ad budget increases for the weekend.',ar:'ابدأ الفعاليات مساء الخميس وارفع ميزانية الإعلانات لنهاية الأسبوع.',de:'Starten Sie Events am Donnerstagabend und planen Sie Budgeterhöhungen für das Wochenende.'}})}
 }
 const cs=S.campaigns.filter(c=>c.st==='active').map(campCalc).sort((a,b)=>a.roas-b.roas);
 if(cs[0]&&cs[0].roas<.35)out.push({sev:'bad',t:{en:`Cut or rebuild: ${cs[0].ch} for ${gName(cs[0].g)}`,ar:`أوقف أو أعد البناء: ${cs[0].ch} لـ ${gName(cs[0].g)}`,de:`Stoppen oder neu aufbauen: ${cs[0].ch} für ${gName(cs[0].g)}`},p:{en:`ROAS D7 is ${cs[0].roas.toFixed(2)}×. Move this ${money(cs[0].spend)} to the best channel.`,ar:`العائد لـ ٧ أيام ${cs[0].roas.toFixed(2)}×. انقل ${money(cs[0].spend)} إلى أفضل قناة.`,de:`ROAS D7 liegt bei ${cs[0].roas.toFixed(2)}×. Verschieben Sie diese ${money(cs[0].spend)} in den besten Kanal.`}});
 const order={bad:0,warn:1,info:2,good:3};return out.sort((a,b)=>order[a.sev]-order[b.sev]);
}
const SEVC={bad:'var(--red)',warn:'var(--amber)',info:'var(--cyan)',good:'var(--good)'};

/* ================= charts (SVG, measured) ================= */
let CH=[];const chartPh=(spec,h=220)=>{CH.push(spec);return `<div class="chart" data-ch="${CH.length-1}" style="height:${h}px"></div>`};
const PAL={dark:{grid:'#241d3c',axis:'#7c74a0',ink:'#f2eeff',bg:'#120e1f'},light:{grid:'#e7e3f0',axis:'#6b6680',ink:'#1b1630',bg:'#ffffff'}};
function niceMax(v){if(v<=0)return 1;const p=Math.pow(10,Math.floor(Math.log10(v)));const n=v/p;return (n<=1?1:n<=2?2:n<=2.5?2.5:n<=5?5:10)*p}
function shortDate(d){const dt=new Date(d+'T12:00:00');return dt.toLocaleDateString(LOC(),{month:'short',day:'numeric'})}
function drawLine(el,sp){
 const W=el.clientWidth||600,H=el.clientHeight||220,P=sp.pal||PRINT_PAL||PAL.dark,pad={l:46,r:12,t:12,b:24},iw=W-pad.l-pad.r,ih=H-pad.t-pad.b;
 const n=sp.labels.length;let max=0;
 if(sp.stack){for(let i=0;i<n;i++)max=Math.max(max,sum(sp.series.map(s=>s.values[i]||0)))}else sp.series.forEach(s=>s.values.forEach(v=>{if(v!=null)max=Math.max(max,v)}));
 if(sp.refLine)max=Math.max(max,sp.refLine.v);
 if(sp.band)max=Math.max(max,...sp.band.hi);
 max=niceMax(max*1.05);const x=i=>pad.l+(n<=1?iw/2:i*iw/(n-1)),y=v=>pad.t+ih-(v/max)*ih;
 let g='';const id='g'+Math.random().toString(36).slice(2,7);
 for(let k=0;k<=4;k++){const v=max*k/4,yy=y(v);g+=`<line x1="${pad.l}" x2="${W-pad.r}" y1="${yy}" y2="${yy}" stroke="${P.grid}" stroke-dasharray="${k?'3 4':'0'}"/><text x="${pad.l-8}" y="${yy+4}" fill="${P.axis}" font-size="10.5" text-anchor="end" font-family="JetBrains Mono,monospace">${esc(sp.fmtAxis?sp.fmtAxis(v):num(v))}</text>`}
 const step=Math.max(1,Math.ceil(n/Math.max(2,Math.floor(iw/70))));
 for(let i=0;i<n;i+=step)g+=`<text x="${x(i)}" y="${H-6}" fill="${P.axis}" font-size="10.5" text-anchor="middle" font-family="JetBrains Mono,monospace">${esc(sp.xfmt?sp.xfmt(sp.labels[i]):shortDate(sp.labels[i]))}</text>`;
 let defs='';
 if(sp.band){const up=sp.band.hi.map((v,i)=>`${x(i)},${y(v)}`).join(' '),dn=sp.band.lo.map((v,i)=>`${x(i)},${y(v)}`).reverse().join(' ');g+=`<polygon points="${up} ${dn}" fill="${sp.band.color}" opacity=".12"/>`}
 const base=new Array(n).fill(0);
 sp.series.forEach((s,si)=>{
  defs+=`<linearGradient id="${id}${si}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${s.color}" stop-opacity="${sp.stack?.55:.32}"/><stop offset="1" stop-color="${s.color}" stop-opacity="${sp.stack?.25:0}"/></linearGradient>`;
  const pts=[];const lows=[];
  s.values.forEach((v,i)=>{if(v==null)return;const top=sp.stack?base[i]+v:v;pts.push([x(i),y(top)]);lows.push([x(i),y(sp.stack?base[i]:0)]);if(sp.stack)base[i]=top});
  if(!pts.length)return;
  const line=pts.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ');
  if(sp.area!==false){const area=line+' '+lows.reverse().map(p=>'L'+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ')+'Z';g+=`<path d="${area}" fill="url(#${id}${si})"/>`}
  g+=`<path d="${line}" fill="none" stroke="${s.color}" stroke-width="${s.w||2}" stroke-linejoin="round" ${s.dash?`stroke-dasharray="${s.dash}"`:''} style="filter:drop-shadow(0 0 4px ${s.color}88)"/>`;
  const lp=pts[pts.length-1];if(!sp.noEnd)g+=`<circle cx="${lp[0]}" cy="${lp[1]}" r="3.5" fill="${P.bg}" stroke="${s.color}" stroke-width="2"/>`;
 });
 if(sp.refLine){const yy=y(sp.refLine.v);g+=`<line x1="${pad.l}" x2="${W-pad.r}" y1="${yy}" y2="${yy}" stroke="${sp.refLine.color}" stroke-dasharray="6 4" stroke-width="1.5"/><text x="${W-pad.r}" y="${yy-6}" fill="${sp.refLine.color}" font-size="11" text-anchor="end">${esc(sp.refLine.label)}</text>`}
 if(sp.marker!=null&&sp.marker>=0&&sp.marker<n){const xx=x(sp.marker);g+=`<line x1="${xx}" x2="${xx}" y1="${pad.t}" y2="${pad.t+ih}" stroke="${P.ink}" stroke-opacity=".5" stroke-dasharray="2 3"/>`}
 if(!sp.noHover){const cw=iw/Math.max(1,n-1);for(let i=0;i<n;i++){const rows=sp.series.map(s=>({n:s.name,c:s.color,v:s.values[i]})).filter(r=>r.v!=null);if(!rows.length)continue;
  const tip=JSON.stringify({h:sp.xfmt?sp.xfmt(sp.labels[i]):shortDate(sp.labels[i]),r:rows.map(r=>[r.n,r.c,(sp.fmt||num)(r.v)])});
  g+=`<rect x="${x(i)-cw/2}" y="${pad.t}" width="${cw}" height="${ih}" fill="transparent" data-tip='${esc(tip)}'/>`}}
 el.innerHTML=`<svg width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(sp.label||'chart')}"><defs>${defs}</defs>${g}</svg>`;
}
function drawDonut(el,sp){
 const S2=Math.min(el.clientWidth,el.clientHeight)||180,r=S2/2-12,c=2*Math.PI*r,tot=sum(sp.parts.map(p=>p.v))||1;let off=0,g='';
 sp.parts.forEach(p=>{const len=p.v/tot*c;g+=`<circle cx="${S2/2}" cy="${S2/2}" r="${r}" fill="none" stroke="${p.c}" stroke-width="16" stroke-dasharray="${Math.max(0,len-2)} ${c}" stroke-dashoffset="${-off}" transform="rotate(-90 ${S2/2} ${S2/2})" style="filter:drop-shadow(0 0 5px ${p.c}aa)" data-tip='${esc(JSON.stringify({h:p.n,r:[[p.n,p.c,pct(p.v/tot)]]}))}'/>`;off+=len});
 g+=`<text x="${S2/2}" y="${S2/2-2}" text-anchor="middle" fill="${(PRINT_PAL||PAL.dark).ink}" font-size="20" font-weight="600" font-family="JetBrains Mono,monospace">${esc(sp.center)}</text><text x="${S2/2}" y="${S2/2+16}" text-anchor="middle" fill="${(PRINT_PAL||PAL.dark).axis}" font-size="11">${esc(sp.sub||'')}</text>`;
 el.innerHTML=`<svg width="${S2}" height="${S2}" viewBox="0 0 ${S2} ${S2}" style="display:block;margin:0 auto">${g}</svg>`;
}
function drawCharts(root=document){$$('.chart[data-ch]',root).forEach(el=>{const sp=CH[+el.dataset.ch];if(!sp)return;(sp.type==='donut'?drawDonut:drawLine)(el,sp)})}
function ringSVG(v,color,size=54){const r=size/2-5,c=2*Math.PI*r,len=(v||0)/100*c;
 return `<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}"><circle cx="${size/2}" cy="${size/2}" r="${r}" fill="none" stroke="#241d3c" stroke-width="5"/><circle cx="${size/2}" cy="${size/2}" r="${r}" fill="none" stroke="${color}" stroke-width="5" stroke-linecap="round" stroke-dasharray="${len} ${c}" transform="rotate(-90 ${size/2} ${size/2})" style="filter:drop-shadow(0 0 4px ${color})"/></svg>`}
function spark(vals,color,w=120,h=34){const v=vals.filter(x=>x!=null);if(v.length<2)return'';const mx=Math.max(...v),mn=Math.min(...v),rg=mx-mn||1;
 const pts=v.map((x,i)=>[i*(w-4)/(v.length-1)+2,h-3-(x-mn)/rg*(h-8)]);const d=pts.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ');
 return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" aria-hidden="true"><path d="${d} L${w-2} ${h} L2 ${h}Z" fill="${color}" opacity=".12"/><path d="${d}" fill="none" stroke="${color}" stroke-width="1.8" style="filter:drop-shadow(0 0 3px ${color})"/><circle cx="${pts.at(-1)[0]}" cy="${pts.at(-1)[1]}" r="2.6" fill="${color}"/></svg>`}
function hbars(items,fmt,max){const m=max||Math.max(...items.map(i=>i.v),1e-9);return `<div class="hbar">${items.map(i=>`<div class="r"><span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(i.n)}</span><div class="tr"><i style="width:${clamp(i.v/m*100,0,100)}%;background:${i.c};box-shadow:0 0 10px ${i.c}"></i></div><span class="vv">${esc(fmt(i.v))}</span></div>`).join('')}</div>`}

