let afterHooks=[];function afterRender(){afterHooks.forEach(f=>f());afterHooks=[]}
const tab=(v,def)=>S.tab[v]||def;
const tabs=(v,list,def)=>`<div class="tabs" role="tablist">${list.map(k=>`<button role="tab" aria-selected="${tab(v,def)===k}" data-tab="${v}:${k}">${t('t_'+k)}</button>`).join('')}</div>`;
function kpiTile(label,val,delta,color,info,inv){
 let d='';if(delta!=null&&isFinite(delta)){const good=inv?delta<0:delta>0;const cls=Math.abs(delta)<.005?'flat':good?'up':'down';d=`<span class="delta ${cls}" title="${t('vs_prev')}">${delta>0?'▲':delta<0?'▼':'•'} ${pct(Math.abs(delta))}</span>`}
 return `<div class="card kpi"><div class="lb"><span class="dot" style="color:${color}"></span>${label}${info?` <span class="i" title="${esc(info)}">i</span>`:''}</div><div class="row"><div class="v">${val}</div>${d}</div></div>`;
}
const dlt=(a,b)=>b?a/b-1:null;

/* ================= views ================= */
function vOverview(){
 const p=S.period,gf=S.gf,a=agg(rowsFor(gf,p)),b=agg(rowsFor(gf,p,p));
 const fx=fixedFor(p),profit=a.rev-a.ua-fx,profitB=b.rev-b.ua-fx;
 const revS=series(gf,p,'rev');
 const live=S.games.filter(g=>g.p&&(gf==='all'||g.id===gf));
 const stack=live.map(g=>{const s=series(g.id,p,'rev');return{name:tx(g.name),color:g.color,values:s.values.map(v=>v||0)}});
 const ins=insights();const ev=calendarEvents().slice(0,3);
 const openTasks=S.tasks.filter(x=>x.col!=='done').length, openInc=S.incidents.filter(x=>x.st==='open');
 const medShares=[['AdMob','#27e2ff',.31],['AppLovin','#ff2bd6',.24],['Unity','#c4ff3d',.13],['Liftoff','#ffb22e',.1],['Mintegral','#9b7bff',.09],['Pangle','#ff4f6e',.07],['Meta','#3dffa9',.06]];
 return `
 <section class="hero">
  <div style="display:flex;flex-direction:column;justify-content:center">
   <div class="eyebrow">${t('portfolio_rev')} · ${t('last')} ${p} ${t('days')}</div>
   <div class="big num">${money(a.rev)}</div>
   <div class="row">${kDelta(dlt(a.rev,b.rev))}<span class="muted small">${t('vs_prev')}</span></div>
   <p style="margin-top:10px">${t('hero_sub')}</p>
  </div>
  <div style="min-width:0">${chartPh({series:[{name:t('k_rev'),color:'#ff2bd6',values:revS.values,w:2.5}],labels:revS.labels,fmt:v=>money(v),fmtAxis:v=>money(v,0),label:t('portfolio_rev')},190)}</div>
 </section>
 <div class="kpis">
  ${kpiTile(t('k_profit'),moneyS(profit),profitB>0?dlt(profit,profitB):null,'#3dffa9')}
  ${kpiTile(t('k_inst'),num(a.inst),dlt(a.inst,b.inst),'#27e2ff')}
  ${kpiTile(t('k_dau'),num(a.dauAvg),dlt(a.dauAvg,b.dauAvg),'#c4ff3d')}
  ${kpiTile(t('k_arpdau'),money(a.arpdau,3),dlt(a.arpdau,b.arpdau),'#ffb22e',t('def_arpdau'))}
  ${kpiTile(t('k_roas'),a.roas.toFixed(2)+'×',dlt(a.roas,b.roas),'#ff2bd6',t('def_roas'))}
  ${kpiTile(t('k_d1'),pct(a.d1),dlt(a.d1,b.d1),'#9b7bff',t('def_d1'))}
  ${kpiTile(t('k_ecpm'),money(a.ecpm),dlt(a.ecpm,b.ecpm),'#27e2ff',t('def_ecpm'))}
  ${kpiTile(t('k_crash'),a.crash.toFixed(2)+'%',dlt(a.crash,b.crash),'#3dffa9',t('def_crash'))}
 </div>
 <div class="grid g-main">
  <div class="card"><h3>${t('rev_by_game')}</h3>${chartPh({series:stack,labels:revS.labels,stack:true,fmt:v=>money(v),fmtAxis:v=>money(v,0)},250)}
   <div class="legend">${live.map(g=>`<span><i style="background:${g.color}"></i>${esc(tx(g.name))}</span>`).join('')}</div></div>
  <div class="card"><h3>${t('rev_mix')}</h3>
   ${chartPh({type:'donut',parts:[{n:t('ads'),v:a.ad,c:'#27e2ff'},{n:t('iap'),v:a.iapNet,c:'#ff2bd6'}],center:pct(a.ad/(a.rev||1),0),sub:t('ads')},170)}
   <div class="legend" style="justify-content:center"><span><i style="background:#27e2ff"></i>${t('ads')} ${money(a.ad)}</span><span><i style="background:#ff2bd6"></i>${t('iap')} ${money(a.iapNet)}</span></div>
   <h3 style="margin-top:18px">${t('mediation')} ${S.liveMed&&S.liveMed.length?`<span class="pill live" style="font-size:10px;padding:1px 7px">${t('live')} · 30${tr('d','ي','T')}</span>`:`<span class="i" title="${tr('Estimated until you import mediation reports','تقديري حتى تستورد تقارير الوساطة','Geschätzt, bis Sie Mediation-Berichte importieren')}">i</span>`}</h3>
   ${S.liveMed&&S.liveMed.length?hbars(S.liveMed.slice(0,8).map((m,i)=>({n:m.n,v:m.v,c:medShares[i%medShares.length][1]})),v=>money(v)):hbars(medShares.map(m=>({n:m[0],v:m[2]*a.ad,c:m[1]})),v=>money(v))}
  </div>
 </div>
 <div class="spread"><h2 class="sec-title">${t('game_health')}</h2><span class="muted small">${t('health_hint')}</span></div>
 <div class="grid g3">${S.games.filter(g=>gf==='all'||g.id===gf).map(gameCard).join('')}</div>
 <div class="grid g-main">
  <div class="card"><h3>${t('insights')}<span class="r muted small">${ins.length}</span></h3><div class="ins">${ins.slice(0,6).map(insItem).join('')}</div></div>
  <div class="grid" style="align-content:start">
   <div class="card"><h3>${t('alerts')}</h3><div class="ins">
    ${openInc.map(i=>`<div class="it"><span class="sv" style="background:${i.sev==='crit'?'var(--red)':i.sev==='major'?'var(--amber)':'var(--cyan)'}"></span><div><b>${esc(i.tt)}</b><p>${esc(gName(i.g))} · ${t('sev_'+i.sev)}</p></div></div>`).join('')||`<p class="muted">—</p>`}
    <div class="it"><span class="sv" style="background:var(--violet)"></span><div><b>${openTasks} ${tr('open tasks','مهام مفتوحة','offene Aufgaben')}</b><p><a href="#ops" data-nav="ops" style="color:var(--cyan)">${t('nav_ops')} →</a></p></div></div>
   </div></div>
   <div class="card"><h3>${t('upcoming')}</h3><div class="grid">${ev.map(evItem).join('')}</div></div>
  </div>
 </div>`;
}
const kDelta=d=>{if(d==null||!isFinite(d))return'';const cls=Math.abs(d)<.005?'flat':d>0?'up':'down';return `<span class="delta ${cls}">${d>0?'▲':d<0?'▼':'•'} ${pct(Math.abs(d))}</span>`};
const insItem=i=>`<div class="it"><span class="sv" style="background:${SEVC[i.sev]};box-shadow:0 0 8px ${SEVC[i.sev]}"></span><div><b>${esc(tx(i.t))}</b><p>${esc(tx(i.p))}</p></div></div>`;
function evItem(e){const dt=new Date(e.d+'T12:00:00');return `<div class="ev"><div class="dd"><b>${e.on?'●':dt.getDate()}</b><small>${e.on?t('ongoing'):dt.toLocaleDateString('en-US',{month:'short'})}</small></div><div style="min-width:0"><h4>${esc(tx(e.n))}</h4><p>${e.on?'':`<span class="mono" style="color:var(--neon)">${e.left===0?t('today'):e.left+' '+t('days_left')}</span>${e.a?` · <span class="muted">${t('approx')}</span>`:''} — `}${esc(tx(e.i))}</p></div></div>`}
function gameCard(g){
 const a=g.p?agg(rowsFor(g.id,S.period)):null, h=health(a), s=g.p?series(g.id,S.period,'dauAvg').values:[];
 const hc=h==null?'#7c74a0':h>=75?'#3dffa9':h>=55?'#ffb22e':'#ff4f6e';
 return `<div class="card gcard" data-goto="game:${g.id}" tabindex="0" role="button" aria-label="${esc(tx(g.name))}">
  <div class="hd"><div class="gico" style="background:radial-gradient(circle at 30% 20%,${g.color},${g.color}55 70%);box-shadow:0 0 18px ${g.color}66">${esc(tx(g.name)).slice(0,1)}</div>
   <div style="min-width:0"><div class="gname">${esc(tx(g.name))}</div><div class="gmeta">${esc(tx(g.genre))} · v${esc(g.version)}</div></div>
   <div class="ring" title="${t('health_hint')}">${ringSVG(h||0,hc)}<span style="color:${hc}">${h??'—'}</span></div></div>
  <div class="row"><span class="pill ${g.status}">${stLabel(g.status)}</span><span class="muted small">${g.levels?g.levels+' '+t('levels'):''}</span><span style="margin-inline-start:auto">${spark(s,g.color,110,30)}</span></div>
  ${a&&a.n?`<div class="mini"><div><small>DAU</small><b>${num(a.dauAvg)}</b></div><div><small>${t('revenue')}</small><b>${money(a.rev)}</b></div><div><small>D1</small><b class="${benchClass('d1',a.d1)}">${pct(a.d1,0)}</b></div><div><small>★</small><b>${a.rating.toFixed(1)}</b></div></div>`:`<div class="muted small">${t('no_data')}</div>`}
 </div>`;
}

function vGames(){
 return `<div class="spread"><h2 class="sec-title">${t('nav_games')} <span class="muted mono" style="font-size:15px">${S.games.length}</span></h2><div class="row">${canEdit()&&S.games.length?`<button class="btn" data-act="clean-games">${tr('Keep live games only','إبقاء الألعاب الحية فقط','Nur Live-Spiele behalten')}</button>`:''}<button class="btn pri" data-act="add-game">${icon('plus')}${t('add_game')}</button></div></div>
 <div class="grid g3">${S.games.map(gameCard).join('')}</div>`;
}

function vGame(id){
 const g=gById(id);if(!g)return `<div class="empty"><b>—</b></div>`;
 const p=S.period,a=g.p?agg(rowsFor(id,p)):null,b=g.p?agg(rowsFor(id,p,p)):null;
 const head=`<div class="spread"><div class="row"><button class="btn sm" data-nav="games">${icon('back','style="transform:scaleX(var(--flip,1))"')}${t('back')}</button>
  <div class="gico" style="background:radial-gradient(circle at 30% 20%,${g.color},${g.color}55 70%);box-shadow:0 0 18px ${g.color}66">${esc(tx(g.name)).slice(0,1)}</div>
  <div><h2 class="sec-title">${esc(tx(g.name))}</h2><div class="muted small">${esc(tx(g.genre))} · ${g.levels?g.levels+' '+t('levels')+' · ':''}${esc(g.platform)} · v${esc(g.version)}</div></div><span class="pill ${g.status}">${stLabel(g.status)}</span></div>
  <div class="row"><div class="tg">${[7,30,90].map(x=>`<button data-period="${x}" aria-pressed="${p===x}">${x}${tr('d','','T')}</button>`).join('')}</div><button class="btn sm" data-act="add-task" data-id="${id}">${icon('plus')}${tr('Tasks','المهام','Aufgaben')} <span class="mono">${S.tasks.filter(x=>x.g===id&&x.col!=='done').length}</span></button><button class="btn sm" data-act="edit-game" data-id="${id}">${t('edit')}</button></div></div>`;
 const chk=CHECKLIST.length,done=Object.keys(S.checks[id]||{}).length;
 const rel=S.releases.filter(r=>r.g===id);
 const opsCard=`<div class="card"><h3>${t('t_chk')}<span class="r mono" style="color:var(--cyan)">${done}/${chk}</span></h3><div class="meter"><i style="width:${done/chk*100}%"></i></div>
  <div class="tbl-wrap" style="margin-top:12px"><table class="tbl"><thead><tr><th>${t('version')}</th><th>${t('status')}</th><th>${t('date')}</th><th>${t('notes')}</th></tr></thead><tbody>${rel.map(r=>`<tr><td class="mono">${esc(r.ver)} (${esc(r.build)})</td><td>${relPill(r.st)}</td><td class="mono">${esc(r.date)}</td><td>${esc(r.notes)}</td></tr>`).join('')||`<tr><td colspan="4" class="muted">—</td></tr>`}</tbody></table></div></div>`;
 if(!a||!a.n)return head+`<div class="empty"><b>${t('no_data')}</b>${t('no_data_p')}</div>`+opsCard;
 const dau=series(id,p,'dauAvg'),ins=series(id,p,'inst'),ec=series(id,p,'ecpm');
 const days=[1,3,7,14,30,60,90],ret=days.map(d=>retAt(a.d1,a.d7,d)),lo=days.map(d=>retAt(BENCH.d1[0],BENCH.d7[0],d)),hi=days.map(d=>retAt(BENCH.d1[1],BENCH.d7[1],d));
 const f=g.funnel||[];let mx=0,mi=0;for(let i=1;i<f.length;i++){const dr=1-f[i][1]/f[i-1][1];if(dr>mx){mx=dr;mi=i}}
 return head+`<div class="kpis">
  ${kpiTile(t('k_rev'),money(a.rev),dlt(a.rev,b.rev),g.color)}${kpiTile(t('k_dau'),num(a.dauAvg),dlt(a.dauAvg,b.dauAvg),'#c4ff3d')}
  ${kpiTile(t('k_inst'),num(a.inst),dlt(a.inst,b.inst),'#27e2ff')}${kpiTile(t('k_arpdau'),money(a.arpdau,3),dlt(a.arpdau,b.arpdau),'#ffb22e',t('def_arpdau'))}
  ${kpiTile(t('k_d1'),pct(a.d1),dlt(a.d1,b.d1),'#9b7bff',t('def_d1'))}${kpiTile(t('k_d7'),pct(a.d7),dlt(a.d7,b.d7),'#9b7bff')}
  ${kpiTile(t('k_roas'),a.roas.toFixed(2)+'×',dlt(a.roas,b.roas),'#ff2bd6',t('def_roas'))}${kpiTile(t('k_crash'),a.crash.toFixed(2)+'%',dlt(a.crash,b.crash),'#3dffa9',t('def_crash'))}
 </div>
 <div class="grid g2">
  <div class="card"><h3>${t('dau_installs')}</h3>${chartPh({series:[{name:'DAU',color:g.color,values:dau.values},{name:t('k_inst'),color:'#27e2ff',values:ins.values,w:1.5}],labels:dau.labels},230)}<div class="legend"><span><i style="background:${g.color}"></i>DAU</span><span><i style="background:#27e2ff"></i>${t('k_inst')}</span></div></div>
  <div class="card"><h3>${t('retention_curve')}</h3>${chartPh({series:[{name:tx(g.name),color:g.color,values:ret}],labels:days,xfmt:d=>'D'+d,fmt:v=>pct(v),fmtAxis:v=>pct(v,0),band:{lo,hi,color:'#27e2ff'}},230)}<div class="legend"><span><i style="background:${g.color}"></i>${esc(tx(g.name))}</span><span><i style="background:#27e2ff;opacity:.4"></i>${t('benchmark')}</span></div></div>
 </div>
 <div class="grid g2">
  <div class="card"><h3>${t('level_funnel')}${mi?`<span class="r small" style="color:var(--amber)">${t('funnel_note')}: L${f[mi-1][0]}→L${f[mi][0]} (−${pct(mx,0)})</span>`:''}</h3>
   ${hbars(f.map((x,i)=>({n:t('level')+' '+x[0],v:x[1],c:i===mi?'#ff4f6e':g.color})),v=>v.toFixed(0)+'%',100)}</div>
  <div class="card"><h3>${t('ecpm_trend')}</h3>${chartPh({series:[{name:'eCPM',color:'#27e2ff',values:ec.values}],labels:ec.labels,fmt:v=>money(v),fmtAxis:v=>money(v)},200)}
   <div class="grid g2" style="margin-top:12px">${[['k_ad',money(a.ad)],['k_iap',money(a.iapNet)],['k_imp',num(a.imp)],['k_sess',a.sess.toFixed(1)],['k_len',a.len.toFixed(1)+(tr(' min',' د',' Min.'))],['k_rating','★ '+a.rating.toFixed(2)]].map(x=>`<div class="spread" style="border-bottom:1px solid var(--line);padding:6px 0"><span class="muted">${t(x[0])}</span><b class="mono">${x[1]}</b></div>`).join('')}</div></div>
 </div>`+opsCard;
}
const relPill=s=>`<span class="pill ${s==='live'?'live':s==='rejected'?'bad':s==='review'?'review':s==='testflight'?'soft':'dev'}">${t('r_'+s)}</span>`;

