const ptag=(usd,sar)=>S.cur==='SAR'?(S.lang==='ar'?sar.toFixed(2)+' ر.س':'SAR '+sar.toFixed(2)):'$'+usd.toFixed(2);
function pOffers(){
 if(!S.games.length)return `<div class="empty"><b>${tr('No games yet','لا توجد ألعاب بعد','Noch keine Spiele')}</b><p class="muted">${tr('Add a game, or run Discover in Reports → Data.','أضف لعبة أو شغّل الاكتشاف في التقارير ← البيانات.','Spiel hinzufügen oder unter Berichte → Daten „Finden“ ausführen.')}</p></div>`;
 const g=gById(S.tab.adg)||S.games[0],c=g.color,O=k=>esc(tx(OFFER_TX[k]));
 const phone=(k,inner)=>`<div class="card"><div class="phone" style="${cvars(c)}">${art(g)}<div class="dim"></div>${inner}</div><div class="exb" style="margin-top:12px"><span>${t('design_tip')}</span><div>${esc(tx(OFFER_TIPS[k]))}</div></div></div>`;
 return `<div class="chips">${S.games.map(x=>`<button class="chip" data-adg="${x.id}" aria-pressed="${x.id===g.id}"><span class="dot" style="color:${x.color};display:inline-block;margin-inline-end:6px"></span>${esc(tx(x.name))}</button>`).join('')}</div>
 <div class="grid g4">
 ${phone('cont',`<div class="pop"><b class="pt">${O('cont')}</b><small>${O('cont_s')}</small><div class="prog"><i style="width:92%"></i></div><span class="ad-cta">${O('watch')}</span><small class="muted">${O('no')}</small></div>`)}
 ${phone('ra',`<div class="pop"><div style="font-size:30px">🚫📺</div><b class="pt">${O('ra')}</b><small>${O('ra_s')}</small><span class="ad-cta">${ptag(3.99,14.99)} · ${O('buy')}</span><small class="muted">${O('no')}</small></div>`)}
 ${phone('sp',`<div class="pop"><span class="pill soft" style="font-size:10px">${O('once')}</span><b class="pt">${O('sp')}</b><small>${O('sp_s')}</small><div><s class="muted small">${ptag(4.99,19.99)}</s> <b class="mono" style="font-size:18px">${ptag(0.99,3.99)}</b></div><span class="ad-cta">${O('buy')}</span></div>`)}
 ${phone('daily',`<div class="pop"><b class="pt">${O('daily')}</b><div class="days">${[1,2,3,4,5,6,7].map(d=>`<i class="${d<5?'ok':d===5?'now':''}">${d}</i>`).join('')}</div><span class="ad-cta">${O('claim')}</span></div>`)}
 </div><p class="muted small">${tr('Prices shown are common App Store price points in USD or SAR (switch with the currency toggle).','الأسعار المعروضة نقاط سعرية شائعة في App Store بالدولار أو الريال (بدّل من زر العملة).','Die Preise sind übliche App-Store-Preispunkte in USD oder SAR (über den Währungsschalter wechseln).')}</p>`;
}
function pIdeas(){const f=S.tab.ideaf||'all';const L2=IDEAS.filter(x=>f==='all'||x[1]===f);
 return `<div class="chips">${['all','rev','ads','growth'].map(k=>`<button class="chip" data-ideaf="${k}" aria-pressed="${f===k}">${k==='all'?t('all'):esc(tx(IDEA_TY[k]))}</button>`).join('')}</div>
 <div class="grid g3">${L2.map(x=>{const g=gById(x[0]);return `<div class="card tip-card"><div class="spread"><span class="tc">${esc(tx(IDEA_TY[x[1]]))}</span><span class="row small" style="gap:6px"><span class="dot" style="color:${g?.color||'#9b7bff'}"></span>${esc(x[0]==='all'?t('general'):gName(x[0]))}</span></div><h4>${esc(tx(x[2]))}</h4><p>${esc(tx(x[3]))}</p></div>`}).join('')}</div>`}


