QUICK.forEach(c=>COURSES.push(c));
function vAcademy(){const tb=tab('academy','path');return tabs('academy',['path','langs','db','deploy','apis','courses','stories','tools','gloss'],'path')+({path:aPath,langs:aLangs,db:aDb,deploy:aDeploy,apis:aApis,tools:aTools,courses:aCourses,stories:aStories,gloss:aGloss}[tb])()}
function aTools(){const f=S.tab.toolc||'all',q=(S.tab.toolq||'').toLowerCase();const L2=TOOLS.filter(x=>(f==='all'||x.c===f)&&(!q||(x.n+' '+tx(x.d)).toLowerCase().includes(q)));
 return `<div class="row"><input class="inp" id="tool-q" data-q="toolq" value="${esc(S.tab.toolq||'')}" placeholder="${esc(t('search'))}" style="max-width:320px"><span class="muted small mono">${L2.length}/${TOOLS.length}</span></div>
 <div class="chips">${['all',...Object.keys(TOOL_CATS)].map(k=>`<button class="chip" data-toolc="${k}" aria-pressed="${f===k}">${k==='all'?t('all'):esc(tx(TOOL_CATS[k]))}</button>`).join('')}</div>
 <div class="grid g3">${L2.map(x=>`<div class="card tool"><div class="spread"><span class="tc mono">${esc(tx(TOOL_CATS[x.c]))}</span><span class="pill ${x.tier==='free'?'live':x.tier==='freemium'?'review':x.tier==='share'?'soft':'paused'}" style="font-size:10.5px">${esc(tx(TIER[x.tier]))}</span></div><h4>${esc(x.n)}</h4><p>${esc(tx(x.d))}</p>${x.u?`<a class="btn sm" href="${esc(x.u)}" target="_blank" rel="noopener" style="align-self:flex-start">${t('visit')} ↗</a>`:''}</div>`).join('')}</div>`}
function aCourses(){S.course=S.course||{};const tot=sum(COURSES.map(c=>c.l.length)),dn=sum(COURSES.map(c=>Object.keys(S.course[c.id]||{}).length));
 const open=S.tab.course||COURSES[0].id,c=COURSES.find(x=>x.id===open)||COURSES[0],cd=S.course[c.id]||{};
 return `<div class="spread"><p class="muted" style="margin:0">${t('courses_p')}</p><span class="mono" style="color:var(--good)">${dn}/${tot} ${t('done_l')}</span></div>
 <div class="grid" style="grid-template-columns:minmax(0,300px) minmax(0,1fr);align-items:start" id="crs-grid">
 <div class="card" style="padding:8px"><div class="nav">${COURSES.map(x=>{const n=Object.keys(S.course[x.id]||{}).length;return `<button data-course="${x.id}" ${x.id===c.id?'aria-current="page"':''}>${icon(x.ic)}<span style="flex:1;min-width:0">${esc(tx(x.t))}${x.quick?` <span class="pill soft" style="font-size:9.5px;padding:0 6px">${t('quick')}</span>`:''}</span><span class="mono small" style="color:${n===x.l.length?'var(--good)':'var(--ink3)'}">${n}/${x.l.length}</span></button>`}).join('')}</div></div>
 <div class="card"><h3>${esc(tx(c.t))}</h3><div class="meter" style="margin-bottom:14px"><i style="width:${Object.keys(cd).length/c.l.length*100}%;background:var(--good)"></i></div>
 <div class="grid">${c.l.map((ls,i)=>`<div class="lesson ${cd[i]?'done':''}"><div class="ln">${i+1}</div><div style="flex:1;min-width:0"><div class="muted small">${t('lesson')} ${i+1}</div><h4>${esc(tx(ls.t))}</h4><p>${esc(tx(ls.b))}</p>${ls.code?`<div class="codebox"><button class="btn sm" data-copytxt="${esc(ls.code)}">${t('copy')}</button><pre dir="ltr"><code>${esc(ls.code)}</code></pre></div>`:''}<button class="btn sm ${cd[i]?'cy':''}" data-lesson="${c.id}:${i}">${cd[i]?'✓ '+t('done_l'):t('mark_done')}</button></div></div>`).join('')}</div></div></div>
 <style>@media(max-width:900px){body:not(.pdfmode) #crs-grid{grid-template-columns:minmax(0,1fr)!important}}.app[data-layout=mobile] #crs-grid{grid-template-columns:minmax(0,1fr)!important}</style>`}
function aGloss(){const f=S.tab.glc||'all',q=(S.tab.glq||'').toLowerCase();const L2=GLOSS.filter(x=>(f==='all'||x.c===f)&&(!q||(x.k+' '+tx(x.d)).toLowerCase().includes(q)));
 return `<div class="row"><input class="inp" id="gl-q" data-q="glq" value="${esc(S.tab.glq||'')}" placeholder="${esc(t('search'))}" style="max-width:320px"><span class="muted small mono">${L2.length}/${GLOSS.length}</span></div>
 <div class="chips">${['all',...Object.keys(GL_CATS)].map(k=>`<button class="chip" data-glc="${k}" aria-pressed="${f===k}">${k==='all'?t('all'):esc(tx(GL_CATS[k]))}</button>`).join('')}</div>
 <div class="card"><div class="gloss">${L2.map(x=>`<div class="gl"><dt dir="ltr">${esc(x.k)} <span class="pill paused" style="font-size:10px;padding:1px 6px">${esc(tx(GL_CATS[x.c]))}</span></dt><dd>${esc(tx(x.d))}</dd></div>`).join('')}</div></div>`}
