function vFinance(){ccMigrate();const tb=tab('finance','pnl');return tabs('finance',['pnl','bp','cc','csamp','fc','unit'],'pnl')+({pnl:fPnl,bp:fBudget,cc:fCC,csamp:fSamples,fc:fFc,unit:fUnit}[tb])()}
function pnlRows(days,gf){
 const mon=ccMonthly().filter(i=>i.cat!=='ua'),direct=gid=>sum(mon.filter(i=>i.g===gid).map(i=>+i.amount||0)),shared=sum(mon.filter(i=>i.g==='all'||!gById(i.g)).map(i=>+i.amount||0));
 const all=S.games.map(g=>({g,a:agg(rowsFor(g.id,days))}));
 const totRev=sum(all.map(x=>x.a.rev))||1, f=days/30;
 return all.filter(x=>(x.a.n||direct(x.g.id)>0)&&(gf==='all'||x.g.id===gf)).map(({g,a})=>{const fixed=(direct(g.id)+shared*a.rev/totRev)*f;const profit=a.rev-a.ua-fixed;return{g,ad:a.ad,iap:a.iap,fee:a.fee,rev:a.rev,ua:a.ua,fixed,profit,margin:a.rev?profit/a.rev:0}});
}
function fPnl(){
 const rows=pnlRows(S.period,S.gf),T2=k=>sum(rows.map(r=>r[k]));const tot={ad:T2('ad'),iap:T2('iap'),fee:T2('fee'),rev:T2('rev'),ua:T2('ua'),fixed:T2('fixed'),profit:T2('profit')};
 const gross=tot.ad+tot.iap;
 return `<div class="kpis">${kpiTile(t('net_rev'),money(tot.rev),null,'#27e2ff')}${kpiTile(t('ua'),money(tot.ua),null,'#ff2bd6')}${kpiTile(t('fixed'),money(tot.fixed),null,'#ffb22e')}${kpiTile(t('profit'),moneyS(tot.profit),null,tot.profit>=0?'#3dffa9':'#ff4f6e')}</div>
 <div class="card"><h3>${t('t_pnl')} · ${t('last')} ${S.period} ${t('days')}<span class="r"><select class="sel" id="fee-rate" aria-label="${t('fee_rate')}"><option value=".15" ${S.feeRate==.15?'selected':''}>${t('fee_small')}</option><option value=".3" ${S.feeRate==.3?'selected':''}>${t('fee_std')}</option></select></span></h3>
 <div class="tbl-wrap"><table class="tbl"><thead><tr><th>${t('game')}</th><th class="n">${t('ad_rev')}</th><th class="n">${t('iap_gross')}</th><th class="n">${t('store_fee')}</th><th class="n">${t('net_rev')}</th><th class="n">${t('ua')}</th><th class="n">${t('fixed')}</th><th class="n">${t('profit')}</th><th class="n">${t('margin')}</th></tr></thead>
 <tbody>${rows.map(r=>`<tr><td><span class="row" style="gap:8px"><span class="dot" style="color:${r.g.color}"></span>${esc(tx(r.g.name))}</span></td><td class="n">${money(r.ad)}</td><td class="n">${money(r.iap)}</td><td class="n muted">−${money(r.fee)}</td><td class="n">${money(r.rev)}</td><td class="n muted">−${money(r.ua)}</td><td class="n muted">−${money(r.fixed)}</td><td class="n ${r.profit>=0?'heat-good':'heat-bad'}">${moneyS(r.profit)}</td><td class="n ${r.margin>=.2?'heat-good':r.margin>=0?'heat-ok':'heat-bad'}">${pct(r.margin)}</td></tr>`).join('')}</tbody>
 <tfoot><tr><td>${t('total')}</td><td class="n">${money(tot.ad)}</td><td class="n">${money(tot.iap)}</td><td class="n">−${money(tot.fee)}</td><td class="n">${money(tot.rev)}</td><td class="n">−${money(tot.ua)}</td><td class="n">−${money(tot.fixed)}</td><td class="n ${tot.profit>=0?'heat-good':'heat-bad'}">${moneyS(tot.profit)}</td><td class="n">${pct(tot.rev?tot.profit/tot.rev:0)}</td></tr></tfoot></table></div></div>
 <div class="grid g2"><div class="card"><h3>${t('waterfall')}</h3>${hbars([{n:tr('Gross revenue','الإيراد الإجمالي','Bruttoumsatz'),v:gross,c:'#27e2ff'},{n:t('store_fee'),v:tot.fee,c:'#9b7bff'},{n:t('ua'),v:tot.ua,c:'#ff2bd6'},{n:t('fixed'),v:tot.fixed,c:'#ffb22e'},{n:t('profit'),v:Math.max(0,tot.profit),c:'#3dffa9'}],v=>money(v),gross)}</div>
 <div class="card"><h3>${t('fixed_costs')}<span class="r"><button class="btn sm cy" data-tab="finance:cc">${t('t_cc')} →</button></span></h3><p class="muted small" style="margin:-4px 0 10px">${t('fixed_p2')}</p>
 ${hbars(Object.keys(CC_CATS).filter(k=>k!=='ua').map(k=>({n:ccCat(k),v:sum(ccMonthly().filter(i=>i.cat===k).map(i=>+i.amount||0)),c:ccColor(k)})).filter(x=>x.v>0),v=>money(v))}
 <div class="spread" style="margin-top:10px"><span class="muted">${t('per_month')}</span><b class="mono">${money(fixedMonthly())}</b></div></div></div>`;
}
function fcCalc(){
 const a=agg(rowsFor('all',30)),f=S.fc,fx=fixedMonthly(),roas0=a.ua?a.rev/a.ua:0;
 const org0=Math.max(0,a.rev-a.ua*Math.min(roas0,f.roas));let cum=0,be=null;const m=[];
 for(let i=1;i<=12;i++){const ua=a.ua*Math.pow(1+f.u/100,i),rev=org0*Math.pow(1+f.g/100,i)+ua*f.roas,cost=ua+fx,pr=rev-cost;cum+=pr;if(be==null&&cum>0)be=i;m.push({i,rev,cost,pr,cum})}
 return {m,be};
}
function fFc(){
 const f=S.fc,{m,be}=fcCalc(),labels=m.map(x=>x.i);const now=new Date();
 const mlab=i=>{const d=new Date(now.getFullYear(),now.getMonth()+i,1);return d.toLocaleDateString(LOC(),{month:'short',year:'2-digit'})};
 const sl=(k,l,mn,mx,st,unit)=>`<div class="field"><label for="fc-${k}" class="spread"><span>${t(l)}</span><b class="mono" style="color:var(--ink)">${f[k]}${unit}</b></label><input id="fc-${k}" type="range" min="${mn}" max="${mx}" step="${st}" value="${f[k]}" data-fc="${k}"></div>`;
 return `<div class="grid g-main"><div class="card"><h3>${t('t_fc')}</h3>${chartPh({series:[{name:t('revenue'),color:'#27e2ff',values:m.map(x=>x.rev)},{name:t('costs'),color:'#ff2bd6',values:m.map(x=>x.cost),area:false},{name:t('cum_profit'),color:'#3dffa9',values:m.map(x=>Math.max(0,x.cum)),dash:'5 4'}],labels,xfmt:mlab,fmt:v=>money(v),fmtAxis:v=>money(v,0),area:true,marker:be?be-1:null},260)}
  <div class="legend"><span><i style="background:#27e2ff"></i>${t('revenue')}</span><span><i style="background:#ff2bd6"></i>${t('costs')}</span><span><i style="background:#3dffa9"></i>${t('cum_profit')}</span></div></div>
 <div class="card"><div class="grid">${sl('g','g_org',-10,30,1,'%')}${sl('u','g_ua',-20,40,1,'%')}${sl('roas','roas_assume',.3,2.5,.05,'×')}</div>
  <div class="grid g2" style="margin-top:14px"><div><div class="muted small">${t('yr_rev')}</div><div class="bignum" style="font-size:22px">${money(sum(m.map(x=>x.rev)))}</div></div><div><div class="muted small">${t('yr_profit')}</div><div class="bignum" style="font-size:22px;color:${m.at(-1).cum>=0?'var(--good)':'var(--red)'}">${moneyS(m.at(-1).cum)}</div></div></div>
  <div class="banner" style="margin-top:12px;border-color:rgba(61,255,169,.35);background:rgba(61,255,169,.06);color:#b8ffe0">${t('breakeven')}: <b class="mono">${be?mlab(be):t('never')}</b></div></div></div>
 <div class="card"><div class="tbl-wrap"><table class="tbl"><thead><tr><th>${t('month')}</th>${m.map(x=>`<th class="n">${mlab(x.i)}</th>`).join('')}</tr></thead><tbody>
 <tr><td>${t('revenue')}</td>${m.map(x=>`<td class="n">${money(x.rev)}</td>`).join('')}</tr><tr><td>${t('costs')}</td>${m.map(x=>`<td class="n muted">${money(x.cost)}</td>`).join('')}</tr>
 <tr><td>${t('profit')}</td>${m.map(x=>`<td class="n ${x.pr>=0?'heat-good':'heat-bad'}">${moneyS(x.pr)}</td>`).join('')}</tr><tr><td>${t('cum_profit')}</td>${m.map(x=>`<td class="n ${x.cum>=0?'heat-good':'heat-bad'}">${moneyS(x.cum)}</td>`).join('')}</tr></tbody></table></div></div>`;
}
function fUnit(){
 const rows=S.games.filter(g=>g.p).map(g=>{const a=agg(rowsFor(g.id,30));const l=[30,90,180].map(N=>ltv(a.d1,a.d7,a.arpdau,N));let pb=null,c=a.arpdau;for(let d=1;d<=365;d++){c+=retAt(a.d1,a.d7,d)*a.arpdau;if(c>=a.cpi){pb=d;break}}return{g,a,l,pb}});
 return `<div class="card"><h3>${t('t_unit')}</h3><p class="muted small" style="margin:-4px 0 12px">${t('unit_p')}</p><div class="tbl-wrap"><table class="tbl"><thead><tr><th>${t('game')}</th><th class="n">ARPDAU</th><th class="n">D1</th><th class="n">D7</th><th class="n">CPI</th><th class="n">${t('ltv30')}</th><th class="n">${t('ltv90')}</th><th class="n">${t('ltv180')}</th><th class="n">${t('ltv_cpi')}</th><th class="n">${t('payback')}</th></tr></thead>
 <tbody>${rows.map(r=>{const q=r.l[2]/(r.a.cpi||1);return `<tr><td>${esc(tx(r.g.name))}</td><td class="n">${money(r.a.arpdau,3)}</td><td class="n">${pct(r.a.d1)}</td><td class="n">${pct(r.a.d7)}</td><td class="n">${money(r.a.cpi,2)}</td><td class="n">${money(r.l[0],2)}</td><td class="n">${money(r.l[1],2)}</td><td class="n">${money(r.l[2],2)}</td><td class="n ${q>=1.3?'heat-good':q>=1?'heat-ok':'heat-bad'}">${q.toFixed(2)}×</td><td class="n ${r.pb&&r.pb<=60?'heat-good':r.pb&&r.pb<=180?'heat-ok':'heat-bad'}">${r.pb?'D'+r.pb:'—'}</td></tr>`}).join('')}</tbody></table></div></div>
 <div class="grid g2">${rows.map(r=>{const labels=[],vals=[];let c=r.a.arpdau;for(let d=0;d<=180;d+=6){if(d>0)for(let k=d-5;k<=d;k++)c+=retAt(r.a.d1,r.a.d7,k)*r.a.arpdau;labels.push(d);vals.push(c)}
  return `<div class="card"><h3><span class="dot" style="color:${r.g.color}"></span>${esc(tx(r.g.name))}</h3>${chartPh({series:[{name:'LTV',color:r.g.color,values:vals}],labels,xfmt:d=>'D'+d,fmt:v=>money(v,2),fmtAxis:v=>money(v,2),refLine:{v:r.a.cpi,color:'#ff2bd6',label:'CPI'}},170)}</div>`}).join('')}</div>`;
}

