function vKpis(){
 const live=S.games.filter(g=>g.p&&(S.gf==='all'||g.id===S.gf)).map(g=>({g,a:agg(rowsFor(g.id,S.period))})).filter(x=>x.a.n);
 const mv=[];S.games.filter(g=>g.p).forEach(g=>{const w1=agg(rowsFor(g.id,7)),w0=agg(rowsFor(g.id,7,7));if(!w0.n)return;[['k_dau',w1.dauAvg,w0.dauAvg],['k_rev',w1.rev,w0.rev],['k_ecpm',w1.ecpm,w0.ecpm],['k_inst',w1.inst,w0.inst]].forEach(([k,a,b])=>mv.push({g,k,d:b?a/b-1:0}))});
 mv.sort((a,b)=>Math.abs(b.d)-Math.abs(a.d));
 const fmtB=k=>{const b=BENCH[k];const d=KPI_DEFS.find(x=>x[0]===k);return d?d[2](b[0])+' – '+d[2](b[1]):''};
 return `<div class="card"><h3>${t('scorecard')}</h3><p class="muted small" style="margin:-4px 0 12px">${t('scorecard_p')}</p>
 <div class="tbl-wrap"><table class="tbl"><thead><tr><th>KPI</th>${live.map(x=>`<th style="text-align:center">${esc(tx(x.g.name))}</th>`).join('')}<th class="n">${t('bench_range')}</th></tr></thead>
 <tbody>${KPI_DEFS.map(([k,l,f])=>`<tr><td>${t(l)}</td>${live.map(x=>`<td class="cell"><span class="${benchClass(k,x.a[k])}">${f(x.a[k])}</span></td>`).join('')}<td class="n muted">${fmtB(k)}</td></tr>`).join('')}</tbody></table></div>
 <div class="legend"><span><i style="background:var(--good)"></i>${t('good')}</span><span><i style="background:var(--amber)"></i>${t('ok')}</span><span><i style="background:var(--red)"></i>${t('bad')}</span></div></div>
 <div class="grid g2"><div class="card"><h3>${t('movers')}</h3><div class="tbl-wrap"><table class="tbl"><tbody>${mv.slice(0,10).map(m=>`<tr><td><span class="dot" style="color:${m.g.color};display:inline-block;margin-inline-end:8px"></span>${esc(tx(m.g.name))}</td><td>${t(m.k)}</td><td class="n">${kDelta(m.d)}</td></tr>`).join('')}</tbody></table></div></div>
 <div class="card"><h3>${t('glossary')}</h3><div class="grid">${KPI_DEFS.map(([k,l,,d])=>`<div style="border-bottom:1px solid var(--line);padding-bottom:8px"><b>${t(l)}</b><div class="muted small mono" dir="auto">${esc(tx(d))}</div></div>`).join('')}</div></div></div>`;
}

