let TL_CACHE=null;
function taskLib(){
 if(TL_CACHE)return TL_CACHE;
 const items=[],cats=[];
 PATH.forEach((st,i)=>{const c='s'+i;cats.push({k:c,n:{en:(i+1)+'. '+st.t.en,ar:(i+1)+'. '+st.t.ar,de:(i+1)+'. '+st.t.de},a:i});st.k.forEach((k,j)=>items.push({id:c+':'+j,cat:c,t:k,a:i}))});
 cats.push({k:'store',...TL_CATS.store});CHECKLIST.forEach((c,j)=>items.push({id:'store:'+j,cat:'store',t:{en:c[0],ar:c[1],de:c[2]||c[0]},a:TL_CATS.store.a}));
 Object.entries(TL_EXTRA).forEach(([c,l])=>{cats.push({k:c,...TL_CATS[c]});l.forEach((k,j)=>items.push({id:c+':'+j,cat:c,t:k,a:TL_CATS[c].a}))});
 const by={};items.forEach(x=>by[x.id]=x);
 return TL_CACHE={items,cats,by};
}
const libTitle=x=>{const it=x.lib&&taskLib().by[x.lib];return it?tx(it.t):x.tt};
function tlOffset(a){let d=0;for(let i=0;i<=a&&i<TL_DUR.length;i++)d+=TL_DUR[i];return d}
function tlAdd(gid,ids,o){
 const lib=taskLib(),have=new Set(S.tasks.filter(x=>x.g===gid&&x.lib).map(x=>x.lib)),start=new Date(o.start||iso(new Date())).getTime();let n=0;
 ids.forEach(id=>{const it=lib.by[id];if(!it||have.has(id))return;
  const due=o.spread?iso(new Date(start+tlOffset(it.a)*864e5)):(o.due||iso(new Date(start+7*864e5)));
  S.tasks.push({id:uid(),g:gid,lib:id,tt:it.t.en,col:o.col||'backlog',pr:o.pr||'med',due});n++});
 return n;
}
function taskPicker(gid){
 const root=$('#modal-root'),lib=taskLib();
 const st={g:gById(gid)?gid:S.tab.taskg&&S.tab.taskg!=='all'?S.tab.taskg:(S.games[0]?.id||''),q:'',cat:'all',sel:new Set(),col:'backlog',pr:'med',start:iso(new Date()),due:iso(new Date(Date.now()+7*864e5)),spread:true,custom:''};
 const onBoard=()=>new Set(S.tasks.filter(x=>x.g===st.g&&x.lib).map(x=>x.lib));
 const vis=()=>{const q=st.q.trim().toLowerCase();return lib.items.filter(x=>(st.cat==='all'||x.cat===st.cat)&&(!q||[x.t.en,x.t.ar,x.t.de].some(v=>String(v).toLowerCase().includes(q))))};
 const list=()=>{const ob=onBoard(),v=vis();if(!v.length)return `<p class="muted small">${tr('No tasks match.','لا توجد مهام مطابقة.','Keine passenden Aufgaben.')}</p>`;
  return lib.cats.filter(c=>v.some(x=>x.cat===c.k)).map(c=>{const its=v.filter(x=>x.cat===c.k),free=its.filter(x=>!ob.has(x.id)),allSel=free.length&&free.every(x=>st.sel.has(x.id));
   return `<div class="tl-grp"><div class="spread tl-gh"><b>${esc(tx(c.n))}</b>${free.length?`<button type="button" class="btn sm" data-tl-grp="${c.k}">${allSel?tr('Clear','إلغاء','Abwählen'):tr('Select all','تحديد الكل','Alle wählen')} (${free.length})</button>`:''}</div>
   <div class="chk">${its.map(x=>{const on=ob.has(x.id);return `<label class="${on?'done':''}"><input type="checkbox" data-tl="${x.id}" ${on?'disabled checked':st.sel.has(x.id)?'checked':''}><span>${esc(tx(x.t))}${on?` <em class="muted small">· ${tr('on the board','على اللوحة','auf dem Board')}</em>`:''}</span></label>`}).join('')}</div></div>`}).join('')};
 const customN=()=>st.custom.split('\n').map(x=>x.trim()).filter(Boolean).length;
 const count=()=>st.sel.size+customN();
 const missing=()=>lib.items.filter(x=>!onBoard().has(x.id)).length;
 const sel=(k,v,opts)=>`<select class="inp" data-tl-f="${k}">${opts.map(o=>`<option value="${esc(o[0])}" ${String(v)===String(o[0])?'selected':''}>${esc(o[1])}</option>`).join('')}</select>`;
 const draw=()=>{
  root.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-label="${esc(t('add_task'))}"><div class="box tl-box">
  <div class="spread"><h2 style="margin:0">${t('add_task')}</h2><span class="muted small">${lib.items.length} ${tr('ready-made tasks','مهمة جاهزة','fertige Aufgaben')}</span></div>
  <div class="form" style="margin-top:12px">
   <div class="field"><label>${t('game')}</label>${sel('g',st.g,gameOpts())}</div>
   <div class="field"><label>${t('status')}</label>${sel('col',st.col,COLS.map(c=>[c,t('col_'+c)]))}</div>
   <div class="field"><label>${t('priority')}</label>${sel('pr',st.pr,['high','med','low'].map(p=>[p,t('p_'+p)]))}</div>
   <div class="field"><label>${st.spread?tr('Plan starts','بداية الخطة','Planstart'):t('due')}</label><input class="inp" type="date" data-tl-f="${st.spread?'start':'due'}" value="${st.spread?st.start:st.due}"></div>
   <label class="field full row small" style="gap:8px;align-items:center;cursor:pointer"><input type="checkbox" data-tl-f="spread" ${st.spread?'checked':''}><span>${tr('Spread due dates by build stage (from the Academy build routine)','وزّع مواعيد الاستحقاق حسب مراحل البناء (من روتين بناء اللعبة في الأكاديمية)','Fälligkeiten nach Bauphase verteilen (aus der Bau-Routine der Akademie)')}</span></label>
  </div>
  <div class="tl-plan"><div><b>${tr('Full plan for this game','خطة كاملة لهذه اللعبة','Kompletter Plan für dieses Spiel')}</b><div class="muted small">${tr('Every task from idea to LiveOps, with due dates by stage.','كل المهام من الفكرة حتى التشغيل المباشر مع مواعيد حسب المرحلة.','Alle Aufgaben von der Idee bis LiveOps, mit Fälligkeiten pro Phase.')}</div></div><button type="button" class="btn pri sm" data-tl-plan ${missing()?'':'disabled'}>${missing()?tr('Add all','أضف الكل','Alle hinzufügen')+' ('+missing()+')':'✓ '+tr('All on the board','الكل على اللوحة','Alles auf dem Board')}</button></div>
  <input class="inp" type="search" data-tl-f="q" value="${esc(st.q)}" placeholder="${tr('Search tasks…','ابحث في المهام…','Aufgaben suchen…')}" style="margin:12px 0 8px">
  <div class="chips tl-cats"><button type="button" class="chip" data-tl-cat="all" aria-pressed="${st.cat==='all'}">${t('all')}</button>${lib.cats.map(c=>`<button type="button" class="chip" data-tl-cat="${c.k}" aria-pressed="${st.cat===c.k}">${esc(tx(c.n))}</button>`).join('')}</div>
  <div class="tl-list" id="tl-list">${list()}</div>
  <div class="field" style="margin-top:12px"><label for="tl-custom">${tr('Your own tasks (one per line)','مهامك الخاصة (مهمة في كل سطر)','Eigene Aufgaben (eine pro Zeile)')}</label><textarea class="inp" id="tl-custom" data-tl-f="custom" rows="2">${esc(st.custom)}</textarea></div>
  <div class="act"><span class="muted small" id="tl-count" style="margin-inline-end:auto;align-self:center">${count()} ${tr('selected','محددة','ausgewählt')}</span><button type="button" class="btn" data-tl-close>${t('cancel')}</button><button type="button" class="btn pri" data-tl-ok ${count()?'':'disabled'}>${t('add_task')}${count()?' ('+count()+')':''}</button></div>
  </div></div>`;
 };
 const refresh=()=>{const sc=$('#tl-list')?.scrollTop||0,box=root.querySelector('.box'),bs=box?.scrollTop||0,f=document.activeElement?.dataset?.tlF,pos=document.activeElement?.selectionStart;draw();$('#tl-list').scrollTop=sc;root.querySelector('.box').scrollTop=bs;if(f){const el=root.querySelector(`[data-tl-f="${f}"]`);if(el){el.focus();try{if(pos!=null)el.setSelectionRange(pos,pos)}catch(e){}}}};
 const done=n=>{root.innerHTML='';render();toast(n?`${n} ${tr('tasks added','مهام أضيفت','Aufgaben hinzugefügt')}`:tr('Nothing new to add','لا جديد لإضافته','Nichts Neues hinzuzufügen'))};
 draw();
 root.onclick=e=>{if(!root.querySelector('.tl-box'))return;const el=e.target;
  if(el.classList.contains('modal')||el.closest('[data-tl-close]')){root.innerHTML='';root.onclick=root.oninput=root.onchange=null;return}
  const c=el.closest('[data-tl-cat]');if(c){st.cat=c.dataset.tlCat;return refresh()}
  const gp=el.closest('[data-tl-grp]');if(gp){const ob=onBoard(),its=vis().filter(x=>x.cat===gp.dataset.tlGrp&&!ob.has(x.id)),all=its.every(x=>st.sel.has(x.id));its.forEach(x=>all?st.sel.delete(x.id):st.sel.add(x.id));return refresh()}
  if(el.closest('[data-tl-plan]')){const n=tlAdd(st.g,lib.items.map(x=>x.id),{...st,spread:true});root.onclick=root.oninput=root.onchange=null;return done(n)}
  if(el.closest('[data-tl-ok]')){const n=tlAdd(st.g,[...st.sel],st);let m=0;st.custom.split('\n').map(x=>x.trim()).filter(Boolean).forEach(tt=>{S.tasks.push({id:uid(),g:st.g,tt,col:st.col,pr:st.pr,due:st.spread?iso(new Date(new Date(st.start).getTime()+7*864e5)):st.due});m++});root.onclick=root.oninput=root.onchange=null;return done(n+m)}
 };
 root.onchange=e=>{if(!root.querySelector('.tl-box'))return;const el=e.target;
  if(el.dataset.tl){el.checked?st.sel.add(el.dataset.tl):st.sel.delete(el.dataset.tl);return refresh()}
  const f=el.dataset.tlF;if(!f||f==='q'||f==='custom')return;
  if(f==='spread')st.spread=el.checked;else st[f]=el.value;
  if(f==='g')st.sel.clear();
  refresh();
 };
 root.oninput=e=>{if(!root.querySelector('.tl-box'))return;const f=e.target.dataset.tlF;if(f==='q'){st.q=e.target.value;refresh()}else if(f==='custom'){st.custom=e.target.value;const n=count(),ok=root.querySelector('[data-tl-ok]');$('#tl-count').textContent=`${n} ${tr('selected','محددة','ausgewählt')}`;ok.disabled=!n;ok.textContent=t('add_task')+(n?' ('+n+')':'')}};
 setTimeout(()=>root.querySelector('[data-tl-f="q"]')?.focus(),30);
}

