   <div class="ac">${ci>0?`<button data-move="${x.id}:-1" aria-label="←">${S.lang==='ar'?'→':'←'}</button>`:''}${ci<COLS.length-1?`<button data-move="${x.id}:1" aria-label="→">${S.lang==='ar'?'←':'→'}</button>`:''}<button data-act="del-task" data-id="${x.id}" aria-label="${t('del')}">✕</button></div></div>`}).join('')}</div>`}).join('')}</div>`;
