function reportHTML(){
 const r=S.rep,p=r.period,gids=(r.games.length?r.games:S.games.filter(g=>g.p).map(g=>g.id)),light=r.theme==='light',P=light?PAL.light:PAL.dark;
 const rows=S.daily.filter(x=>gids.includes(x.g)),end=iso(new Date()),start=iso(new Date(Date.now()-(p-1)*864e5));
 const a=agg(rows.filter(x=>x.d>=start&&x.d<=end)),fx=fixedFor(p);
 const has=s=>r.sections.includes(s);
 const games=gids.map(id=>({g:gById(id),a:agg(rowsFor(id,p))})).filter(x=>x.g&&x.a.n);
 const labels=[];for(let i=p-1;i>=0;i--)labels.push(iso(new Date(Date.now()-i*864e5)));
 let html=`<div class="rp ${light?'light':'neon'}" id="report" dir="${S.lang==='ar'?'rtl':'ltr'}">
  <div class="rp-block" style="display:flex;justify-content:space-between;align-items:flex-end;gap:16px;border-bottom:1px solid rgba(128,118,170,.35);padding-bottom:14px">
   <div><div style="font-family:var(--f-mono);font-size:10.5px;letter-spacing:${S.lang==='ar'?0:'.16em'};color:#ff2bd6">${t('brand')} · ${t('brand2')}</div><h1>${esc(r.title||(tr('Game portfolio report','تقرير أداء الألعاب','Spiele-Portfolio-Bericht')))}</h1></div>
   <div class="muted" style="text-align:end;font-size:11px">${t('period')}: <b>${start} → ${end}</b><br>${t('generated')}: ${new Date().toLocaleString('en-GB')}</div></div>`;
 if(has('summary'))html+=`<div class="rp-block"><h2>${t('s_summary')}</h2><div class="k4">${[[t('k_rev'),money(a.rev)],[t('k_profit'),moneyS(a.rev-a.ua-fx)],[t('k_inst'),num(a.inst)],[t('k_dau'),num(a.dauAvg)],[t('k_arpdau'),money(a.arpdau,3)],[t('k_roas'),a.roas.toFixed(2)+'×'],[t('k_d1'),pct(a.d1)],[t('k_crash'),a.crash.toFixed(2)+'%']].map(k=>`<div class="kb"><small>${k[0]}</small><b>${k[1]}</b></div>`).join('')}</div></div>`;
 if(has('rev')){const byD={};games.forEach(({g})=>{byD[g.id]={};rowsFor(g.id,p).forEach(x=>byD[g.id][x.d]=x.ad+x.iap*(1-S.feeRate))});
  html+=`<div class="rp-block"><h2>${t('s_rev')}</h2>${chartPh({series:games.map(({g})=>({name:tx(g.name),color:g.color,values:labels.map(d=>byD[g.id][d]||0)})),labels,stack:true,pal:P,noHover:true,fmtAxis:v=>money(v,0)},220)}<div style="display:flex;gap:14px;flex-wrap:wrap;font-size:11px;margin-top:6px">${games.map(({g})=>`<span><span style="display:inline-block;width:9px;height:9px;border-radius:2px;background:${g.color};margin-inline-end:5px"></span>${esc(tx(g.name))}</span>`).join('')}</div></div>`}
 if(has('games'))html+=`<div class="rp-block"><h2>${t('s_games')}</h2><table><thead><tr><th>${t('game')}</th><th class="n">${t('k_rev')}</th><th class="n">DAU</th><th class="n">${t('k_inst')}</th><th class="n">ARPDAU</th><th class="n">D1</th><th class="n">D7</th><th class="n">ROAS</th><th class="n">★</th></tr></thead><tbody>${games.map(({g,a})=>`<tr><td>${esc(tx(g.name))}</td><td class="n">${money(a.rev)}</td><td class="n">${num(a.dauAvg)}</td><td class="n">${num(a.inst)}</td><td class="n">${money(a.arpdau,3)}</td><td class="n">${pct(a.d1)}</td><td class="n">${pct(a.d7)}</td><td class="n">${a.roas.toFixed(2)}×</td><td class="n">${a.rating.toFixed(1)}</td></tr>`).join('')}</tbody></table></div>`;
 if(has('mkt')){const cs=S.campaigns.filter(c=>gids.includes(c.g)).map(campCalc);html+=`<div class="rp-block"><h2>${t('s_mkt')}</h2><table><thead><tr><th>${t('game')}</th><th>${t('channel')}</th><th class="n">${t('spend')}</th><th class="n">${t('installs')}</th><th class="n">CPI</th><th class="n">${t('roas7')}</th><th>${t('action')}</th></tr></thead><tbody>${cs.map(c=>`<tr><td>${esc(gName(c.g))}</td><td>${esc(c.ch)}</td><td class="n">${money(c.spend)}</td><td class="n">${num(c.inst)}</td><td class="n">${money(c.cpi,2)}</td><td class="n">${c.roas.toFixed(2)}×</td><td>${t(campRec(c)[0])}</td></tr>`).join('')}</tbody></table></div>`}
 if(has('fin')){const pr=pnlRows(p,'all').filter(x=>gids.includes(x.g.id));html+=`<div class="rp-block"><h2>${t('s_fin')}</h2><table><thead><tr><th>${t('game')}</th><th class="n">${t('net_rev')}</th><th class="n">${t('ua')}</th><th class="n">${t('fixed')}</th><th class="n">${t('profit')}</th><th class="n">${t('margin')}</th></tr></thead><tbody>${pr.map(x=>`<tr><td>${esc(tx(x.g.name))}</td><td class="n">${money(x.rev)}</td><td class="n">${money(x.ua)}</td><td class="n">${money(x.fixed)}</td><td class="n">${moneyS(x.profit)}</td><td class="n">${pct(x.margin)}</td></tr>`).join('')}</tbody></table></div>`}
 if(has('kpi')){const cc={'heat-good':'#16b877','heat-ok':'#d98e00','heat-bad':'#e23b5a'};html+=`<div class="rp-block"><h2>${t('s_kpi')}</h2><table><thead><tr><th>KPI</th>${games.map(({g})=>`<th class="n">${esc(tx(g.name))}</th>`).join('')}</tr></thead><tbody>${KPI_DEFS.map(([k,l,f])=>`<tr><td>${t(l)}</td>${games.map(({a})=>`<td class="n" style="color:${cc[benchClass(k,a[k])]||'inherit'};font-weight:600">${f(a[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
 if(has('rec'))html+=`<div class="rp-block"><h2>${t('s_rec')}</h2><ul>${insights().slice(0,8).map(i=>`<li><b>${esc(tx(i.t))}.</b> ${esc(tx(i.p))}</li>`).join('')}</ul></div>`;
 if(has('ops'))html+=`<div class="rp-block"><h2>${t('s_ops')}</h2><table><thead><tr><th>${t('game')}</th><th>${t('version')}</th><th>${t('status')}</th><th class="n">${t('t_chk')}</th><th class="n">${tr('Open tasks','مهام مفتوحة','Offene Aufgaben')}</th><th class="n">${t('t_inc')}</th></tr></thead><tbody>${S.games.map(g=>{const rl=S.releases.filter(x=>x.g===g.id).sort((a,b)=>b.date.localeCompare(a.date))[0];return `<tr><td>${esc(tx(g.name))}</td><td class="n" style="text-align:start">${esc(rl?rl.ver:g.version)}</td><td>${rl?t('r_'+rl.st):stLabel(g.status)}</td><td class="n">${Object.keys(S.checks[g.id]||{}).length}/${CHECKLIST.length}</td><td class="n">${S.tasks.filter(x=>x.g===g.id&&x.col!=='done').length}</td><td class="n">${S.incidents.filter(x=>x.g===g.id&&x.st==='open').length}</td></tr>`}).join('')}</tbody></table></div>`;
 html+=`<div class="muted" style="font-size:10px;text-align:center">${S.sample?(tr('This report contains sample data','يحتوي هذا التقرير على بيانات تجريبية','Dieser Bericht enthält Beispieldaten')):''}</div></div>`;
 return html;
}
