const AI={ctl:null,last:''};
function aiContext(){
 const a=agg(rowsFor('all',30));
 const games=S.games.map(g=>{const x=g.p?agg(rowsFor(g.id,30)):null;return{name:g.name.en,status:g.status,levels:g.levels,...(x&&x.n?{dau:Math.round(x.dauAvg),installs:x.inst,net_rev_usd:+x.rev.toFixed(0),arpdau:+x.arpdau.toFixed(3),ecpm:+x.ecpm.toFixed(2),roas:+x.roas.toFixed(2),cpi:+x.cpi.toFixed(2),d1:+x.d1.toFixed(3),d7:+x.d7.toFixed(3),d30:+x.d30.toFixed(3),crash_free:+x.crash.toFixed(2),rating:+x.rating.toFixed(2)}:{})}});
 return JSON.stringify({period:'last 30 days',portfolio:{net_rev_usd:+a.rev.toFixed(0),ua_spend_usd:+a.ua.toFixed(0),roas:+a.roas.toFixed(2)},games,campaigns:S.campaigns.map(c=>({game:gName(c.g),channel:c.ch,status:c.st,spend:c.spend,installs:c.inst,d7_revenue:c.rev7})),fixed_costs_month_usd:fixedMonthly(),market:'Saudi Arabia first, iOS, published via Replit/Expo, ads via AdMob mediation'});
}
async function aiAsk(q){
 const out=$('#ai-out'),note=$('#ai-note');if(!q.trim())return;
 const sample=await capUse('sample');
 if(!sample){note.textContent=t('ai_unavail');return}
 AI.ctl?.abort();AI.ctl=new AbortController();out.textContent=t('thinking');$('#ai-stop').hidden=false;note.textContent='';
 const prompt=`You are a senior mobile-games growth and monetization advisor for an indie studio in Saudi Arabia. Use the portfolio data below. Give specific, numbered, actionable advice tied to the numbers; name games and channels; keep it under 350 words; no tables. Answer in ${tr('English','Arabic (clear Saudi-friendly Modern Standard Arabic)','German')}. Use plain text with short headings and bullets ("-").\n\nDATA:\n${aiContext()}\n\nQUESTION: ${q}`;
 try{const r=await sample(prompt,{signal:AI.ctl.signal,cache:false,onText:({text})=>{out.textContent=text}});AI.last=r.text;out.textContent=r.text;if(r.truncated)note.textContent='…'}
 catch(e){if(e?.code!=='cancelled')note.textContent=e?.code==='not_granted'?t('ai_unavail'):(e?.message||'Error')}
 finally{const s=$('#ai-stop');if(s)s.hidden=true}
}


