const MK_TABN={accounts:['Ad accounts','حسابات الإعلانات','Werbekonten'],auto:['Budget autopilot','الطيار الآلي للميزانية','Budget-Autopilot'],alloc:['Portfolio budget','ميزانية المحفظة','Portfolio-Budget'],lift:['True lift','الأثر الحقيقي','Echter Lift'],fatigue:['Creative fatigue','تشبّع الإعلانات','Creative-Ermüdung'],value:['Player value','قيمة اللاعب','Spielerwert'],store:['Store funnel','قمع المتجر','Store-Trichter'],tests:['Pages & A/B tests','الصفحات واختبارات A/B','Seiten & A/B-Tests'],events:['In-App Events','فعاليات داخل التطبيق','In-App-Events'],reviews:['Review mining','تحليل المراجعات','Review-Analyse'],xpromo:['Cross-promotion','الترويج المتبادل','Cross-Promotion']};
const MK_GN={spend:['Spend','الإنفاق','Ausgaben'],value:['Value','القيمة','Wert'],store:['App Store','متجر التطبيقات','App Store'],grow:['Growth','النمو','Wachstum']};
const mkT=a=>tr(a[0],a[1],a[2]);
const mkTab=k=>MK_TABN[k]?mkT(MK_TABN[k]):t('t_'+k);
function mkS(){
 if(!S.mk||typeof S.mk!=='object')S.mk={};
 const m=S.mk;
 m.rules=Array.isArray(m.rules)?m.rules:[
  {id:'r1',on:1,m:'roas',op:'<',v:.8,days:3,act:'cut',pct:20},
  {id:'r2',on:1,m:'roas',op:'>',v:1.3,days:3,act:'raise',pct:15},
  {id:'r3',on:1,m:'cpix',op:'>',v:1.5,days:5,act:'pause',pct:100},
  {id:'r4',on:1,m:'fat',op:'>',v:.3,days:3,act:'creative',pct:0}];
 m.budget=m.budget||{};m.log=Array.isArray(m.log)?m.log:[];m.dis=m.dis||{};m.q=m.q||{};
 m.alloc=m.alloc||{total:3000,cap:.4,test:.1};m.cpi=m.cpi||{asa:1.2,snap:.55,tiktok:.5,meta:.8,gads:.7};
 m.cpp=Array.isArray(m.cpp)?m.cpp:[];m.tests=Array.isArray(m.tests)?m.tests:[];m.events=Array.isArray(m.events)?m.events:[];m.xp=Array.isArray(m.xp)?m.xp:[];
 return m;
}

