async function mkLoad(force){
 if(!CLOUD){if(MKD.st!=='ok'||force){mkDemo();MKD.st='ok'}return}
 if(MKD.st==='busy'||((MKD.st==='ok'||MKD.st==='err')&&!force))return;
 MKD.st='busy';MKD.err='';
 const r=await Promise.race([api('GET','/api/marketing?days=120'),new Promise(res=>setTimeout(()=>res({ok:false,s:0,j:{error:tr('The server took too long to answer. Press Try again.','تأخر الخادم في الرد. اضغط حاول مجدداً.','Der Server hat zu lange gebraucht. Erneut versuchen.')}}),25000))]);
 if(r.ok&&r.j&&Array.isArray(r.j.ads))Object.assign(MKD,r.j,{st:'ok',err:'',demo:false});
 else{MKD.st='err';MKD.err=((r.j&&r.j.error)||('HTTP '+r.s))+(r.s===404?' · '+tr('the website is still on the old version: check that the latest deploy is Published in Netlify','الموقع ما زال على النسخة القديمة: تأكد أن آخر نشر في Netlify حالته Published','die Website ist noch auf der alten Version: prüfen, ob der letzte Netlify-Deploy veröffentlicht ist'):'')}
 render();
}
function mkRand(seed){let a=seed>>>0;return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function mkDemo(){
 const R=mkRand(42),ads=[],chNet={'Apple Search Ads':'asa','TikTok':'tiktok','Snapchat':'snap','Meta':'meta','Google App Campaigns':'gads'};
 S.campaigns.filter(c=>gById(c.g)).forEach((c,ci)=>{const net=chNet[c.ch]||'csv',cpi=c.inst?c.spend/c.inst:.8,ctr=c.imp?c.clk/c.imp:.01,daily=(c.budget||600)/30;
  for(let i=44;i>=1;i--){const d=iso(new Date(Date.now()-i*864e5)),age=44-i,fat=ci===1?Math.max(.45,1-age*.018):ci===4?Math.max(.6,1-age*.01):1;
   const spend=+(daily*(.75+R()*.5)).toFixed(2),imp=Math.round(spend/((c.spend/(c.imp||1))||.004)*(.9+R()*.2)),clk=Math.round(imp*ctr*fat*(.85+R()*.3)),inst=Math.round(spend/cpi/(.6+.4*fat)*(.8+R()*.4));
   if(c.st==='ended'&&i<20)continue;ads.push({net,cid:'demo-'+ci,n:`${gName(c.g)} · ${c.ch}`,g:c.g,d,spend,imp,clk,inst})}});
 const RV={brick:[[5,'Addictive!','Best brick breaker, love the neon levels'],[2,'Too many ads','ads after every level, please reduce'],[1,'اعلانات كثيرة','اللعبة حلوة بس الإعلانات كثيرة جداً'],[3,'Level 20','level 20 is too hard, stuck for days'],[5,'رائعة','لعبة ممتعة جداً وتصميم جميل']],
  ruby:[[5,'Nostalgia','Just like the old Nokia bounce, amazing'],[4,'حلوة','ذكرتني بالنوكيا، نبي مراحل أكثر'],[2,'Crash','game crashes on level 150 on iPhone 12'],[1,'يعلق','تعلق اللعبة وتطلع فجأة']],
  factory:[[3,'Hard start','tutorial is confusing, too hard at the start'],[4,'Smart puzzles','great puzzles but needs Arabic voice'],[2,'Boring','repetitive after level 30']],
  chess:[[5,'Great teacher','lessons are excellent for kids and adults'],[4,'ممتازة','دروس الشطرنج بالعربي رائعة'],[2,'Price','remove ads is too expensive']]};
 const reviews={};Object.entries(RV).forEach(([g,l])=>{if(gById(g))reviews[g]=l.map((x,i)=>({id:g+i,r:x[0],t:x[1],b:x[2],d:iso(new Date(Date.now()-(i*4+1)*864e5)),c:'SAU'}))});
 Object.assign(MKD,{ads,reviews,adMap:{},storeTerr:{},brief:null,ai:{ready:false},nets:{},demo:true});
}
const mkSince=days=>iso(new Date(Date.now()-days*864e5));
function mkCamps(days=14,gid='all'){
 const since=mkSince(days),by={};
 MKD.ads.forEach(r=>{if(r.d<since||(gid!=='all'&&r.g!==gid))return;const k=r.net+':'+r.cid;
  const c=by[k]||(by[k]={key:k,net:r.net,cid:r.cid,n:r.n,g:r.g,spend:0,inst:0,imp:0,clk:0,first:r.d,last:r.d});
  c.spend+=r.spend;c.inst+=r.inst;c.imp+=r.imp;c.clk+=r.clk;if(r.d<c.first)c.first=r.d;if(r.d>c.last)c.last=r.d});
 const out=Object.values(by);
 if(!MKD.demo&&!out.length)S.campaigns.forEach(c=>{if(gid==='all'||c.g===gid)out.push({key:'manual:'+c.id,net:'manual',cid:c.id,n:c.ch,g:c.g,spend:c.spend,inst:c.inst,imp:c.imp,clk:c.clk,rev7:c.rev7,manual:1})});
 return out.map(c=>({...c,cpi:c.inst?c.spend/c.inst:0,ctr:c.imp?c.clk/c.imp:0,ir:c.imp?c.inst/c.imp:0}));
}
function mkSeries(key,days=45){const[net,...rest]=key.split(':'),cid=rest.join(':'),since=mkSince(days),m={};
 MKD.ads.forEach(r=>{if(r.net===net&&r.cid===cid&&r.d>=since){const o=m[r.d]||(m[r.d]={d:r.d,spend:0,inst:0,imp:0,clk:0});o.spend+=r.spend;o.inst+=r.inst;o.imp+=r.imp;o.clk+=r.clk}});
 return Object.values(m).sort((a,b)=>a.d.localeCompare(b.d))}

/* ---------- player value (LTV) ---------- */
const MK_LTV={};
function mkLtv(gid){
 const a=agg(rowsFor(gid,30));if(!a.dauSum||!(a.arpdau>0))return null;
 const pts=[[1,a.d1],[7,a.d7],[30,a.d30]].filter(p=>p[1]>0&&p[1]<1);
 let A=a.d1||.35,b=.65;
 if(pts.length>=2){const X=pts.map(p=>Math.log(p[0])),Y=pts.map(p=>Math.log(p[1])),mx=sum(X)/X.length,my=sum(Y)/Y.length;
  const sl=sum(X.map((x,i)=>(x-mx)*(Y[i]-my)))/(sum(X.map(x=>(x-mx)**2))||1);b=clamp(-sl,.15,1.6);A=Math.exp(my+b*mx)}
 else if(pts.length===1){A=pts[0][1]}
 A=clamp(A,.02,.95);const cum=[1];for(let t=1;t<366;t++)cum[t]=cum[t-1]+Math.min(1,A*Math.pow(t,-b));
 const L=T=>cum[clamp(Math.round(T)-1,0,365)];
 return {gid,arp:a.arpdau,A,b,d1:a.d1,d7:a.d7,d30:a.d30,L,ltv:T=>a.arpdau*L(T),dau:a.dauAvg,n:a.n,sess:a.sess,est:pts.length<2};
}
function mkL(gid){return MK_LTV[gid]!==undefined?MK_LTV[gid]:(MK_LTV[gid]=mkLtv(gid))}
function mkQ(c){const m=mkS();if(c.manual&&c.rev7&&c.inst){const L=mkL(c.g);if(L&&L.ltv(7)>0)return clamp(c.rev7/c.inst/L.ltv(7),.2,4)}return +(m.q[c.net]??1)||1}
function mkPayback(gid,cpi,q=1){const L=mkL(gid);if(!L||!cpi)return null;for(let T=1;T<=365;T++)if(L.ltv(T)*q>=cpi)return T;return null}
function mkRoas(c,T=180){const L=mkL(c.g);if(!L||!c.spend)return null;return c.inst*L.ltv(T)*mkQ(c)/c.spend}
const mkVerdict=r=>r==null?['—','']:r>=1.3?[tr('Scale','وسّع','Skalieren'),'heat-good']:r>=1?[tr('Profitable · hold','مربح · حافظ','Profitabel · halten'),'heat-good']:r>=.8?[tr('Close · test creatives','قريب · اختبر الإعلانات','Knapp · Creatives testen'),'heat-ok']:[tr('Losing money · cut','خاسر · خفّض','Verlust · kürzen'),'heat-bad'];
const mkPb=d=>d==null?tr('never (365d+)','لا يسترد (+٣٦٥ يوم)','nie (365T+)'):d+tr('d',' يوم','T');
function mkNote(html){return `<p class="muted small" style="margin:10px 0 0">${html}</p>`}
function mkDemoBanner(){return MKD.demo?`<div class="banner" style="margin-bottom:12px">${icon('spark','style="width:16px;height:16px;flex:none"')}<span>${tr('Example data. On your website these pages use your real ad accounts, App Store and Firebase numbers.','بيانات توضيحية. في موقعك تعتمد هذه الصفحات على حسابات إعلاناتك وأرقام المتجر وFirebase الحقيقية.','Beispieldaten. Auf Ihrer Website nutzen diese Seiten Ihre echten Werbekonten-, App-Store- und Firebase-Zahlen.')}</span></div>`:MKD.st==='err'?`<div class="banner" style="border-color:rgba(255,79,110,.4);color:#ffb3c1;margin-bottom:12px"><span>${tr('Marketing data could not load','تعذّر تحميل بيانات التسويق','Marketingdaten konnten nicht geladen werden')}: ${esc(MKD.err)}</span><button class="btn sm" data-mk="reload">${tr('Try again','حاول مجدداً','Erneut versuchen')}</button></div>`:''}
function mkGamePick(cur,key,withAll){const gs=S.games.filter(g=>mkL(g.id)||!withAll);return `<select class="inp" data-mkin="${key}" style="width:auto;padding:6px 8px">${withAll?`<option value="all">${tr('All games','كل الألعاب','Alle Spiele')}</option>`:''}${S.games.map(g=>`<option value="${g.id}" ${cur===g.id?'selected':''}>${esc(tx(g.name))}</option>`).join('')}</select>`}

function mValue(){
 const live=S.games.filter(g=>mkL(g.id));
 if(!live.length)return mkDemoBanner()+`<div class="empty"><b>${tr('No player data yet','لا توجد بيانات لاعبين بعد','Noch keine Spielerdaten')}</b><p class="muted">${tr('Player value needs daily users, retention and revenue. Connect Firebase and AdMob in Reports → Data, then sync.','قيمة اللاعب تحتاج المستخدمين اليوميين والاحتفاظ والإيراد. اربط Firebase وAdMob في التقارير ← البيانات ثم زامن.','Spielerwert braucht DAU, Retention und Umsatz. Firebase und AdMob unter Berichte → Daten verbinden, dann synchronisieren.')}</p></div>`;
 const sel=gById(S.tab.mkg)&&mkL(S.tab.mkg)?S.tab.mkg:live[0].id,L=mkL(sel);
 const camps30=mkCamps(30);
 const rows=live.map(g=>{const l=mkL(g.id),cs=camps30.filter(c=>c.g===g.id),sp=sum(cs.map(c=>c.spend)),ins=sum(cs.map(c=>c.inst)),cpi=ins?sp/ins:null,pb=cpi?mkPayback(g.id,cpi):null;
  return `<tr><td><b>${esc(tx(g.name))}</b>${l.est?` <span class="pill paused" style="font-size:10px" title="${esc(tr('Fewer than two retention points; curve uses a typical shape','أقل من نقطتي احتفاظ؛ المنحنى بشكل نموذجي','Weniger als zwei Retention-Punkte; typische Kurve'))}">~</span>`:''}</td><td class="n">${money(l.arp,3)}</td><td class="n">${pct(l.d1||0,0)} · ${pct(l.d7||0,0)} · ${pct(l.d30||0,1)}</td><td class="n">${money(l.ltv(7),2)}</td><td class="n">${money(l.ltv(30),2)}</td><td class="n">${money(l.ltv(90),2)}</td><td class="n"><b>${money(l.ltv(180),2)}</b></td><td class="n">${cpi?money(cpi,2):'—'}</td><td class="n ${pb==null?(cpi?'heat-bad':''):pb<=60?'heat-good':pb<=180?'heat-ok':'heat-bad'}">${cpi?mkPb(pb):'—'}</td></tr>`}).join('');
 const T=[1,3,7,14,21,30,45,60,90,120,150,180],cs=camps30.filter(c=>c.g===sel&&c.inst),cpiG=cs.length?sum(cs.map(c=>c.spend))/sum(cs.map(c=>c.inst)):null;
 const chart=chartPh({labels:T.map(String),xfmt:x=>x+tr('d','ي','T'),fmt:v=>money(v,2),fmtAxis:v=>money(v,2),series:[{name:tr('Predicted value per player','القيمة المتوقعة للاعب','Erwarteter Wert pro Spieler'),color:'#3dffa9',values:T.map(d=>L.ltv(d))}],refLine:cpiG?{v:cpiG,color:'#ff4f6e',label:'CPI '+money(cpiG,2)}:null},240);
 const camps=mkCamps(14).filter(c=>c.g&&mkL(c.g)).sort((a,b)=>b.spend-a.spend);
 return mkDemoBanner()+`<div class="card"><h3>${tr('What a player is worth','كم يساوي اللاعب','Was ein Spieler wert ist')}</h3><p class="muted small" style="margin:-4px 0 10px">${tr('Predicted net revenue per new player (ads + in-app after Apple\'s fee) from each game\'s real retention curve and revenue per daily user. Payback = days until a player has earned back what he cost.','الإيراد الصافي المتوقع لكل لاعب جديد (إعلانات + مشتريات بعد عمولة Apple) من منحنى الاحتفاظ الحقيقي والإيراد اليومي لكل مستخدم. الاسترداد = عدد الأيام حتى يعيد اللاعب تكلفته.','Erwarteter Nettoumsatz pro neuem Spieler (Werbung + In-App nach Apple-Gebühr) aus echter Retention-Kurve und Umsatz pro DAU. Amortisation = Tage, bis ein Spieler seine Kosten eingespielt hat.')}</p>
  <div class="tbl-wrap"><table class="tbl"><thead><tr><th>${t('game')}</th><th class="n">ARPDAU</th><th class="n">D1 · D7 · D30</th><th class="n">LTV 7</th><th class="n">LTV 30</th><th class="n">LTV 90</th><th class="n">LTV 180</th><th class="n">CPI 30${tr('d','ي','T')}</th><th class="n">${tr('Payback','الاسترداد','Amortisation')}</th></tr></thead><tbody>${rows}</tbody></table></div></div>
 <div class="grid g-main" style="margin-top:14px"><div class="card"><h3>${tr('Value curve','منحنى القيمة','Wertkurve')}<span class="r">${mkGamePick(sel,'tab.mkg')}</span></h3>${chart}${mkNote(tr(`Break-even CPI for 180-day payback: <b>${money(L.ltv(180),2)}</b>. For 90 days: <b>${money(L.ltv(90),2)}</b>.`,`تكلفة التثبيت القصوى للاسترداد خلال ١٨٠ يوماً: <b>${money(L.ltv(180),2)}</b>. وخلال ٩٠ يوماً: <b>${money(L.ltv(90),2)}</b>.`,`Break-even-CPI für 180 Tage: <b>${money(L.ltv(180),2)}</b>. Für 90 Tage: <b>${money(L.ltv(90),2)}</b>.`))}</div>
 <div class="card"><h3>${tr('Channel quality','جودة القناة','Kanalqualität')}</h3><p class="muted small" style="margin:-4px 0 10px">${tr('1.00 = players from this network are worth the game average. Change it only when your attribution shows a difference.','١٫٠٠ = لاعبو هذه الشبكة بقيمة متوسط اللعبة. غيّرها فقط إذا أظهرت بيانات الإسناد فرقاً.','1,00 = Spieler dieses Netzwerks sind so viel wert wie der Spieldurchschnitt. Nur ändern, wenn die Attribution einen Unterschied zeigt.')}</p>
  <div class="form">${['asa','snap','tiktok','meta','gads'].map(n=>`<div class="field"><label>${mkNetName(n)}</label><input class="inp mono" type="number" step="0.05" min="0.2" max="4" value="${+(mkS().q[n]??1)}" data-mkin="q.${n}" data-num="1"></div>`).join('')}</div></div></div>
 <div class="card" style="margin-top:14px"><h3>${tr('Campaigns · last 14 days','الحملات · آخر ١٤ يوماً','Kampagnen · letzte 14 Tage')}</h3>${camps.length?`<div class="tbl-wrap"><table class="tbl"><thead><tr><th>${tr('Campaign','الحملة','Kampagne')}</th><th>${t('game')}</th><th class="n">${t('spend')}</th><th class="n">${t('installs')}</th><th class="n">CPI</th><th class="n">ROAS 7${tr('d','ي','T')}</th><th class="n">ROAS 180${tr('d','ي','T')}</th><th class="n">${tr('Payback','الاسترداد','Amortisation')}</th><th>${t('action')}</th></tr></thead><tbody>${camps.map(c=>{const r7=mkRoas(c,7),r180=mkRoas(c,180),[vk,vc]=mkVerdict(r180);return `<tr><td><span class="dot" style="color:${mkNetColor(c.net)};display:inline-block;margin-inline-end:6px"></span>${esc(c.n)}<div class="muted small">${mkNetName(c.net)}</div></td><td>${esc(gName(c.g))}</td><td class="n">${money(c.spend)}</td><td class="n">${num(c.inst)}</td><td class="n">${money(c.cpi,2)}</td><td class="n">${r7==null?'—':r7.toFixed(2)+'×'}</td><td class="n ${vc}">${r180==null?'—':r180.toFixed(2)+'×'}</td><td class="n">${mkPb(mkPayback(c.g,c.cpi,mkQ(c)))}</td><td class="${vc}">${vk}</td></tr>`}).join('')}</tbody></table></div>`:`<p class="muted">${tr('No campaigns with installs yet. Connect an ad account in Spend → Ad accounts.','لا توجد حملات بتثبيتات بعد. اربط حساب إعلانات في الإنفاق ← حسابات الإعلانات.','Noch keine Kampagnen mit Installs. Werbekonto unter Ausgaben → Werbekonten verbinden.')}</p>`}</div>`;
}

/* ---------- budget autopilot (proposes; you approve) ---------- */
const MK_MET={roas:[['Predicted 180-day ROAS','العائد المتوقع خلال ١٨٠ يوماً','Erwarteter 180-Tage-ROAS'],'×'],cpix:[['CPI ÷ break-even CPI','تكلفة التثبيت ÷ تكلفة التعادل','CPI ÷ Break-even-CPI'],'×'],fat:[['Click-rate drop from peak','انخفاض معدل النقر عن الذروة','CTR-Rückgang vom Höchstwert'],'%']};
const MK_ACT={cut:['Cut budget','خفّض الميزانية','Budget kürzen'],raise:['Raise budget','ارفع الميزانية','Budget erhöhen'],pause:['Pause','أوقف','Pausieren'],creative:['Refresh creative','جدّد الإعلان','Creative erneuern']};
const mkMet=k=>mkT(MK_MET[k][0]),mkAct=k=>MK_ACT[k]?mkT(MK_ACT[k]):k;
function mkDailyMetric(c,day,m){
 const L=mkL(c.g);if(!L)return null;
 if(m==='roas')return day.spend>0?day.inst*L.ltv(180)*mkQ(c)/day.spend:null;
 if(m==='cpix'){const be=L.ltv(180)*mkQ(c);return day.inst&&be?(day.spend/day.inst)/be:null}
 return null;
}
function mkFatigue(c){const s=mkSeries(c.key,60).filter(x=>x.imp>200);if(s.length<8)return null;
 const roll=s.map((x,i)=>{const w=s.slice(Math.max(0,i-2),i+1);const im=sum(w.map(y=>y.imp));return im?sum(w.map(y=>y.clk))/im:0});
 const head=roll.slice(2,Math.max(3,Math.ceil(roll.length*.7))),peak=Math.max(...head),now=roll[roll.length-1];
 const ir=s.map(x=>x.imp?x.inst/x.imp:0);
 return {drop:peak?1-now/peak:0,peak,now,age:Math.round((Date.now()-new Date(s[0].d+'T12:00:00'))/864e5),series:s,roll,ir}}
function mkProposals(){
 const m=mkS(),today=iso(new Date()),out=[];
 mkCamps(30).filter(c=>c.g&&!c.manual).forEach(c=>{
  const s=mkSeries(c.key,14).filter(x=>x.spend>0),avg7=sum(s.slice(-7).map(x=>x.spend))/Math.max(1,Math.min(7,s.length));
  const cur=+(m.budget[c.key]??Math.round(avg7));
  m.rules.filter(r=>r.on).forEach(r=>{
   if(m.dis[c.key+'|'+r.id]&&m.dis[c.key+'|'+r.id]>today)return;
   let hit=false,val=null;
   if(r.m==='fat'){const f=mkFatigue(c);if(f){val=f.drop;hit=r.op==='>'?f.drop>r.v:f.drop<r.v}}
   else{const last=s.slice(-r.days);if(last.length<r.days)return;const vals=last.map(x=>mkDailyMetric(c,x,r.m));if(vals.some(v=>v==null))return;val=sum(vals)/vals.length;hit=vals.every(v=>r.op==='<'?v<r.v:v>r.v)}
   if(!hit)return;
   const to=r.act==='cut'?Math.max(1,Math.round(cur*(1-r.pct/100))):r.act==='raise'?Math.round(cur*(1+r.pct/100)):r.act==='pause'?0:cur;
   out.push({id:c.key+'|'+r.id,key:c.key,c,r,from:cur,to,val});
  });
 });
 // one budget change per campaign: pause beats cut beats raise
 const rank={pause:3,cut:2,raise:1},keep={};
 out.forEach(p=>{if(!rank[p.r.act])return;const k=keep[p.key];if(!k||rank[p.r.act]>rank[k.r.act])keep[p.key]=p});
 return out.filter(p=>!rank[p.r.act]||keep[p.key]===p);
}
function mAuto(){
 const m=mkS(),P=mkProposals();
 const ruleRow=r=>`<tr><td><input type="checkbox" data-mkrule="${r.id}:on" ${r.on?'checked':''} aria-label="on"></td><td><select class="inp" data-mkrule="${r.id}:m" style="width:auto;padding:5px 6px">${Object.keys(MK_MET).map(k=>`<option value="${k}" ${r.m===k?'selected':''}>${mkMet(k)}</option>`).join('')}</select></td><td><select class="inp" data-mkrule="${r.id}:op" style="width:auto;padding:5px 6px"><option ${r.op==='<'?'selected':''}>&lt;</option><option ${r.op==='>'?'selected':''}>&gt;</option></select></td><td><input class="inp mono" type="number" step="0.05" value="${r.v}" data-mkrule="${r.id}:v" style="width:80px"></td><td><input class="inp mono" type="number" min="1" max="14" value="${r.days}" data-mkrule="${r.id}:days" style="width:64px" ${r.m==='fat'?'disabled':''}></td><td><select class="inp" data-mkrule="${r.id}:act" style="width:auto;padding:5px 6px">${Object.keys(MK_ACT).map(k=>`<option value="${k}" ${r.act===k?'selected':''}>${mkAct(k)}</option>`).join('')}</select></td><td><input class="inp mono" type="number" min="0" max="100" value="${r.pct}" data-mkrule="${r.id}:pct" style="width:64px" ${['cut','raise'].includes(r.act)?'':'disabled'}></td><td><button class="btn sm ghost" data-mk="rule-del" data-id="${r.id}" aria-label="${t('del')}">✕</button></td></tr>`;
 return mkDemoBanner()+`<div class="card"><h3>${icon('spark','style="width:16px;height:16px;color:var(--neon)"')} ${tr('Proposed changes','التغييرات المقترحة','Vorgeschlagene Änderungen')} <span class="muted mono" style="font-size:13px">${P.length}</span><span class="r">${P.length&&canEdit()?`<button class="btn sm pri" data-mk="ap-all">${tr('Approve all','اعتمد الكل','Alle genehmigen')}</button>`:''}</span></h3>
  ${P.length?`<div class="grid">${P.map(p=>{const up=p.to>p.from,cl=p.r.act==='creative'?'var(--cyan)':up?'var(--good)':'var(--red)';return `<div class="card" style="border-color:${cl}55;padding:14px"><div class="spread" style="gap:10px;flex-wrap:wrap"><div style="min-width:0"><b>${mkAct(p.r.act)}</b> · ${esc(p.c.n)} <span class="muted small">(${mkNetName(p.c.net)} · ${esc(gName(p.c.g))})</span>
   <div class="small muted">${mkMet(p.r.m)} ${p.r.op} ${p.r.m==='fat'?pct(p.r.v,0):p.r.v} ${p.r.m==='fat'?'':tr(`for ${p.r.days} days`,`لمدة ${p.r.days} أيام`,`seit ${p.r.days} Tagen`)} · ${tr('now','الآن','jetzt')} <b class="mono">${p.r.m==='fat'?pct(p.val,0):p.val.toFixed(2)+'×'}</b></div></div>
   <div class="row" style="gap:8px">${p.r.act!=='creative'?`<span class="mono">${money(p.from)}/${tr('day','يوم','Tag')} → <b style="color:${cl}">${money(p.to)}</b></span>`:''}${canEdit()?`<button class="btn sm pri" data-mk="ap" data-id="${esc(p.id)}">${tr('Approve','اعتمد','Genehmigen')}</button><button class="btn sm ghost" data-mk="dis" data-id="${esc(p.id)}">${tr('Not now','ليس الآن','Nicht jetzt')}</button>`:''}</div></div></div>`}).join('')}</div>`:`<p class="muted" style="margin:0">${tr('Nothing to change. Every campaign is inside your rules.','لا شيء للتغيير. كل الحملات ضمن قواعدك.','Nichts zu ändern. Alle Kampagnen liegen innerhalb Ihrer Regeln.')}</p>`}
  ${mkNote(tr('Kinzhal Nest never spends or changes anything in your ad accounts by itself. Approving records the new daily budget here and in the log; then set the same budget in the ad network.','كينجال نست لا ينفق ولا يغيّر أي شيء في حسابات إعلاناتك بنفسه. الاعتماد يسجّل الميزانية اليومية الجديدة هنا وفي السجل، ثم اضبط الميزانية نفسها في شبكة الإعلانات.','Kinzhal Nest gibt nie selbst Geld aus und ändert nichts in Ihren Werbekonten. Genehmigen speichert das neue Tagesbudget hier und im Protokoll; dasselbe Budget dann im Werbenetzwerk setzen.'))}</div>
 <div class="card" style="margin-top:14px"><h3>${tr('Rules','القواعد','Regeln')}<span class="r">${canEdit()?`<button class="btn sm" data-mk="rule-add">${icon('plus')}${tr('Add rule','أضف قاعدة','Regel hinzufügen')}</button>`:''}</span></h3>
  <div class="tbl-wrap"><table class="tbl"><thead><tr><th></th><th>${tr('When','عندما','Wenn')}</th><th></th><th>${tr('Value','القيمة','Wert')}</th><th>${tr('Days','أيام','Tage')}</th><th>${tr('Then','إذن','Dann')}</th><th>%</th><th></th></tr></thead><tbody>${m.rules.map(ruleRow).join('')}</tbody></table></div>
  ${mkNote(tr('ROAS uses each game\'s predicted 180-day player value. A rule fires only when every one of the last N days breaks it, so one bad day never moves money.','العائد يعتمد على قيمة اللاعب المتوقعة خلال ١٨٠ يوماً لكل لعبة. القاعدة تعمل فقط إذا خالفها كل يوم من آخر N أيام، فلا يتحرك المال بسبب يوم سيئ واحد.','ROAS nutzt den erwarteten 180-Tage-Spielerwert jedes Spiels. Eine Regel greift nur, wenn jeder der letzten N Tage sie verletzt.'))}</div>
 <div class="card" style="margin-top:14px"><h3>${tr('Log','السجل','Protokoll')}</h3>${m.log.length?`<div class="tbl-wrap"><table class="tbl"><thead><tr><th>${tr('Date','التاريخ','Datum')}</th><th>${tr('Campaign','الحملة','Kampagne')}</th><th>${tr('Change','التغيير','Änderung')}</th><th>${tr('By','بواسطة','Von')}</th></tr></thead><tbody>${m.log.slice(0,40).map(l=>`<tr><td class="mono">${esc(l.at.slice(0,16).replace('T',' '))}</td><td>${esc(l.n)}</td><td>${esc(mkAct(l.act))} ${l.act!=='creative'?`<span class="mono">${money(l.from)} → ${money(l.to)}</span>`:''}</td><td class="small">${esc(l.by||'')}</td></tr>`).join('')}</tbody></table></div>`:`<p class="muted" style="margin:0">—</p>`}</div>`;
}
function mkApprove(ids){
 const m=mkS(),P=mkProposals().filter(p=>ids.includes(p.id));
 P.forEach(p=>{if(p.r.act!=='creative')m.budget[p.key]=p.to;else S.tasks.push({id:uid(),g:p.c.g,tt:tr(`New creative for ${p.c.n} (${mkNetName(p.c.net)})`,`إعلان جديد لـ ${p.c.n} (${mkNetName(p.c.net)})`,`Neues Creative für ${p.c.n} (${mkNetName(p.c.net)})`),col:'backlog',pr:'high',due:iso(new Date(Date.now()+3*864e5))});
  m.log.unshift({at:new Date().toISOString(),key:p.key,n:p.c.n,act:p.r.act,from:p.from,to:p.to,by:CLOUD&&C.me?C.me.email:''});
  m.dis[p.id]=iso(new Date(Date.now()+3*864e5))});
 m.log=m.log.slice(0,200);toast(tr(`${P.length} change(s) approved`,`اعتُمد ${P.length} تغيير`,`${P.length} Änderung(en) genehmigt`));render();
}

/* ---------- portfolio budget allocator ---------- */
function mkAllocate(){
 const m=mkS(),A=m.alloc,total=Math.max(0,+A.total||0),capG=clamp(+A.cap||.4,.1,1)*total,camps=mkCamps(30),cand=[];
 S.games.forEach(g=>{const L=mkL(g.id);if(!L)return;
  ['asa','snap','tiktok','meta','gads'].forEach(net=>{const cs=camps.filter(c=>c.g===g.id&&c.net===net),sp=sum(cs.map(c=>c.spend)),ins=sum(cs.map(c=>c.inst));
   const real=ins>=20,cpi=real?sp/ins:+m.cpi[net]||1,q=+(m.q[net]??1)||1,sat=Math.max(600,sp*3);
   cand.push({g:g.id,net,cpi,real,q,sat,v:L.ltv(180)*q,s:0,inst:0})})});
 if(!cand.length||!total)return {cand:[],total,left:total};
 const step=Math.max(10,total/200);let left=total;const gSpend={},R0={capped:false};
 const marg=c=>{const e=c.cpi*(1+(c.s+step/2)/c.sat);return step/e*c.v-step};
 cand.filter(c=>!c.real).forEach(c=>{c.test=1});
 while(left>=step){let best=null,bv=0;
  let capped=false;for(const c of cand){const v=marg(c);if((gSpend[c.g]||0)+step>capG){if(v>0)capped=true;continue}if(v>bv){bv=v;best=c}}
  if(!best){R0.capped=capped;break}best.s+=step;best.inst+=step/(best.cpi*(1+best.s/best.sat));gSpend[best.g]=(gSpend[best.g]||0)+step;left-=step}
 const testBudget=Math.min(left,total*clamp(+A.test||0,0,.3));
 return {cand:cand.filter(c=>c.s>0).sort((a,b)=>b.s-a.s),total,left,testBudget,capped:R0.capped};
}
function mAlloc(){
 const m=mkS(),R=mkAllocate(),spent=sum(R.cand.map(c=>c.s)),rev=sum(R.cand.map(c=>c.inst*c.v));
 const byG={};R.cand.forEach(c=>{byG[c.g]=(byG[c.g]||0)+c.s});
 return mkDemoBanner()+`<div class="card"><h3>${tr('Monthly budget split','توزيع الميزانية الشهرية','Monatliche Budgetverteilung')}</h3>
 <div class="form"><div class="field"><label>${tr('Monthly budget (USD)','الميزانية الشهرية (دولار)','Monatsbudget (USD)')}</label><input class="inp mono" type="number" min="0" step="100" value="${m.alloc.total}" data-mkin="alloc.total" data-num="1"></div>
 <div class="field"><label>${tr('Max share per game (%)','الحد الأعلى لكل لعبة (٪)','Max. Anteil pro Spiel (%)')}</label><input class="inp mono" type="number" min="10" max="100" step="5" value="${Math.round(m.alloc.cap*100)}" data-mkin="alloc.cap" data-pct="1"></div>
 <div class="field"><label>${tr('Reserve for tests (%)','احتياطي للاختبارات (٪)','Reserve für Tests (%)')}</label><input class="inp mono" type="number" min="0" max="30" step="5" value="${Math.round(m.alloc.test*100)}" data-mkin="alloc.test" data-pct="1"></div></div>
 <div class="kpis" style="margin-top:12px">${kpiTile(tr('Allocated','الموزّع','Verteilt'),money(spent),null,'#ff2bd6')}${kpiTile(tr('Expected installs','التثبيتات المتوقعة','Erwartete Installs'),num(sum(R.cand.map(c=>c.inst))),null,'#27e2ff')}${kpiTile(tr('Expected 180-day revenue','الإيراد المتوقع ١٨٠ يوماً','Erwarteter 180-Tage-Umsatz'),money(rev),null,'#3dffa9')}${kpiTile('ROAS 180'+tr('d','ي','T'),spent?(rev/spent).toFixed(2)+'×':'—',null,'#ffb22e')}</div>
 ${R.left>=1?`<div class="banner" style="margin-top:12px">${R.capped?tr(`${money(R.left)} is not allocated because the profitable games reached the ${pct(m.alloc.cap,0)} cap per game. Raise the cap to scale them, or use ${money(R.testBudget||0)} to test other games.`,`لم يُوزَّع ${money(R.left)} لأن الألعاب المربحة وصلت للحد الأعلى ${pct(m.alloc.cap,0)} لكل لعبة. ارفع الحد لتوسيعها أو استخدم ${money(R.testBudget||0)} لاختبار ألعاب أخرى.`,`${money(R.left)} nicht verteilt, weil die profitablen Spiele das Limit von ${pct(m.alloc.cap,0)} pro Spiel erreicht haben. Limit erhöhen oder ${money(R.testBudget||0)} für Tests nutzen.`):tr(`${money(R.left)} is not allocated: no game/channel is predicted to pay back with more spend. Keep it, or use ${money(R.testBudget||0)} to test new creatives.`,`لم يُوزَّع ${money(R.left)}: لا توجد لعبة/قناة يُتوقع أن تسترد إنفاقاً أكثر. احتفظ به أو استخدم ${money(R.testBudget||0)} لاختبار إعلانات جديدة.`,`${money(R.left)} nicht verteilt: kein Spiel/Kanal amortisiert mehr Ausgaben. Behalten oder ${money(R.testBudget||0)} für neue Creatives testen.`)}</div>`:''}</div>
 <div class="grid g-main" style="margin-top:14px"><div class="card"><h3>${tr('Where the money goes','أين يذهب المال','Wohin das Geld geht')}</h3>${R.cand.length?`<div class="tbl-wrap"><table class="tbl"><thead><tr><th>${t('game')}</th><th>${tr('Channel','القناة','Kanal')}</th><th class="n">${tr('Budget','الميزانية','Budget')}</th><th class="n">CPI</th><th class="n">${t('installs')}</th><th class="n">ROAS 180${tr('d','ي','T')}</th></tr></thead><tbody>${R.cand.map(c=>`<tr><td>${esc(gName(c.g))}</td><td><span class="dot" style="color:${mkNetColor(c.net)};display:inline-block;margin-inline-end:6px"></span>${mkNetName(c.net)}${c.real?'':` <span class="pill paused" style="font-size:10px" title="${esc(tr('No data yet: estimated CPI, treat as a test','لا بيانات بعد: تكلفة تقديرية، اعتبرها اختباراً','Noch keine Daten: geschätzter CPI, als Test behandeln'))}">${tr('test','اختبار','Test')}</span>`}</td><td class="n"><b>${money(c.s)}</b></td><td class="n">${money(c.cpi,2)}</td><td class="n">${num(c.inst)}</td><td class="n">${(c.inst*c.v/c.s).toFixed(2)}×</td></tr>`).join('')}</tbody></table></div>`:`<p class="muted">${tr('Needs player value for at least one game.','يحتاج قيمة اللاعب للعبة واحدة على الأقل.','Braucht den Spielerwert für mindestens ein Spiel.')}</p>`}</div>
 <div class="card"><h3>${tr('By game','حسب اللعبة','Nach Spiel')}</h3>${hbars(Object.entries(byG).map(([g,v])=>({n:gName(g),v,c:gById(g)?.color||'#27e2ff'})).sort((a,b)=>b.v-a.v),v=>money(v))}
 <h4 style="margin:16px 0 6px">${tr('Estimated CPI when a channel has no data','تكلفة التثبيت التقديرية عند غياب البيانات','Geschätzter CPI ohne Kanaldaten')}</h4><div class="form">${['asa','snap','tiktok','meta','gads'].map(n=>`<div class="field"><label>${mkNetName(n)}</label><input class="inp mono" type="number" step="0.05" min="0.05" value="${m.cpi[n]}" data-mkin="cpi.${n}" data-num="1"></div>`).join('')}</div></div></div>
 ${mkNote(tr('Each extra dollar goes where it earns the most predicted 180-day revenue. Cost per install rises as a channel scales, so money spreads out instead of piling into one game.','كل دولار إضافي يذهب حيث يحقق أعلى إيراد متوقع خلال ١٨٠ يوماً. تكلفة التثبيت ترتفع مع التوسع في القناة، فيتوزع المال بدلاً من تكدسه في لعبة واحدة.','Jeder zusätzliche Dollar geht dorthin, wo er den höchsten erwarteten 180-Tage-Umsatz bringt. CPI steigt mit der Skalierung, daher verteilt sich das Geld.'))}`;
}

/* ---------- true lift (incrementality) ---------- */
function mLift(){
 const gs=S.games.filter(g=>S.daily.some(r=>r.g===g.id&&r.inst));
 if(!gs.length)return mkDemoBanner()+`<div class="empty"><b>${tr('No install data yet','لا توجد بيانات تثبيت بعد','Noch keine Installdaten')}</b></div>`;
 const sel=gById(S.tab.mkl)&&gs.some(g=>g.id===S.tab.mkl)?S.tab.mkl:gs[0].id;
 const since=mkSince(60),days=[];for(let i=60;i>=1;i--)days.push(iso(new Date(Date.now()-i*864e5)));
 const tot={},paid={},sp={};S.daily.forEach(r=>{if(r.g===sel&&r.d>=since){tot[r.d]=(tot[r.d]||0)+(+r.inst||0);if(!MKD.ads.length){paid[r.d]=(paid[r.d]||0)+(+r.paid||0);sp[r.d]=(sp[r.d]||0)+(+r.ua||0)}}});
 MKD.ads.forEach(r=>{if(r.g===sel&&r.d>=since){paid[r.d]=(paid[r.d]||0)+r.inst;sp[r.d]=(sp[r.d]||0)+r.spend}});
 const D=days.filter(d=>tot[d]!=null),avgSp=sum(D.map(d=>sp[d]||0))/(D.length||1);
 const off=D.filter(d=>(sp[d]||0)<=avgSp*.1),on=D.filter(d=>(sp[d]||0)>avgSp*.1);
 const med=a=>{const s=[...a].sort((x,y)=>x-y);return s.length?s[Math.floor(s.length/2)]:null};
 let base=off.length>=4?med(off.map(d=>tot[d])):null,how='off';
 if(base==null&&on.length){const first=D.findIndex(d=>(sp[d]||0)>avgSp*.1);if(first>=5){base=med(D.slice(0,first).map(d=>tot[d]));how='before'}}
 const avg=a=>a.length?sum(a)/a.length:0,onTot=avg(on.map(d=>tot[d])),onPaid=avg(on.map(d=>paid[d]||0)),onSp=avg(on.map(d=>sp[d]||0));
 const inc=base!=null?onTot-base:null,lift=inc!=null&&onPaid?inc/onPaid:null,tcpi=inc>0?onSp/inc:null;
 const verdict=lift==null?'':lift<.6?tr('Networks over-credit themselves: many "paid" installs would have come anyway. Judge spend by the true CPI below.','الشبكات تنسب لنفسها أكثر من الواقع: كثير من التثبيتات «المدفوعة» كانت ستأتي على أي حال. احكم على الإنفاق بالتكلفة الحقيقية أدناه.','Netzwerke schreiben sich zu viel zu: viele „bezahlte“ Installs wären ohnehin gekommen. Ausgaben am echten CPI messen.'):lift<=1.25?tr('Reported installs match the real lift. Network numbers can be trusted for this game.','التثبيتات المعلنة تطابق الأثر الحقيقي. يمكن الوثوق بأرقام الشبكات لهذه اللعبة.','Gemeldete Installs entsprechen dem echten Lift. Netzwerkzahlen sind vertrauenswürdig.'):tr('Halo effect: ads also lift organic installs (store ranking, word of mouth). Paid spend is worth more than networks report.','أثر الهالة: الإعلانات ترفع التثبيتات العضوية أيضاً (ترتيب المتجر والتوصيات). الإنفاق المدفوع أعلى قيمة مما تعلنه الشبكات.','Halo-Effekt: Werbung hebt auch organische Installs. Bezahlte Ausgaben sind mehr wert als gemeldet.');
 const chart=chartPh({labels:D,fmt:v=>num(v),series:[{name:tr('All installs','كل التثبيتات','Alle Installs'),color:'#27e2ff',values:D.map(d=>tot[d])},{name:tr('Paid (reported)','المدفوعة (المعلنة)','Bezahlt (gemeldet)'),color:'#ff2bd6',values:D.map(d=>paid[d]||0),area:false}],refLine:base!=null?{v:base,color:'#ffb22e',label:tr('Organic baseline','الخط العضوي','Organische Basis')}:null},240);
 return mkDemoBanner()+`<div class="card"><h3>${tr('Did the ads really add players?','هل أضافت الإعلانات لاعبين فعلاً؟','Haben die Anzeigen wirklich Spieler gebracht?')}<span class="r">${mkGamePick(sel,'tab.mkl')}</span></h3>${chart}
 <div class="kpis" style="margin-top:12px">${kpiTile(tr('Organic baseline / day','الخط العضوي / يوم','Organische Basis / Tag'),base==null?'—':num(base),null,'#ffb22e')}${kpiTile(tr('Extra installs / day','تثبيتات إضافية / يوم','Zusätzliche Installs / Tag'),inc==null?'—':num(inc),null,'#27e2ff')}${kpiTile(tr('Reported paid / day','المدفوعة المعلنة / يوم','Gemeldet bezahlt / Tag'),num(onPaid),null,'#ff2bd6')}${kpiTile(tr('True lift','الأثر الحقيقي','Echter Lift'),lift==null?'—':lift.toFixed(2)+'×',null,'#3dffa9')}${kpiTile(tr('True CPI','التكلفة الحقيقية','Echter CPI'),tcpi?money(tcpi,2):'—',null,'#9b7bff')}</div>
 ${lift!=null?`<div class="banner" style="margin-top:12px">${verdict}</div>`:`<div class="banner" style="margin-top:12px">${tr('Needs at least 4 days without ads (or 5 days before the first campaign) to measure the organic baseline. Use the test plan below.','يحتاج ٤ أيام على الأقل بدون إعلانات (أو ٥ أيام قبل أول حملة) لقياس الخط العضوي. استخدم خطة الاختبار أدناه.','Braucht mindestens 4 Tage ohne Anzeigen (oder 5 Tage vor der ersten Kampagne) für die organische Basis.')}</div>`}
 ${mkNote(how==='before'&&base!=null?tr('Baseline = median installs in the days before the first campaign.','الخط العضوي = وسيط التثبيتات في الأيام قبل أول حملة.','Basis = Median der Installs vor der ersten Kampagne.'):tr('Baseline = median installs on days with almost no ad spend.','الخط العضوي = وسيط التثبيتات في الأيام شبه الخالية من الإنفاق.','Basis = Median der Installs an Tagen fast ohne Werbeausgaben.'))}</div>
 <div class="grid g2" style="margin-top:14px"><div class="card"><h3>${tr('Why iPhone numbers differ','لماذا تختلف أرقام الآيفون','Warum iPhone-Zahlen abweichen')}</h3><p class="small" style="margin:0">${tr('Since Apple\'s tracking prompt, most iPhone players cannot be followed one by one. Networks get grouped, delayed reports from Apple (SKAdNetwork / AdAttributionKit), usually 1–3 days late and without per-player detail. They also model the rest, so their totals can overlap. The total-installs line comes from App Store Connect and cannot double count, which is why lift is the honest test.','منذ نافذة التتبع من Apple لا يمكن تتبع معظم لاعبي الآيفون فردياً. تحصل الشبكات على تقارير مجمّعة ومتأخرة من Apple ‏(SKAdNetwork / AdAttributionKit)، عادة بتأخير ١–٣ أيام وبدون تفاصيل لكل لاعب، وتقدّر الباقي فقد تتداخل أرقامها. خط إجمالي التثبيتات من App Store Connect ولا يُحسب مرتين، لذلك قياس الأثر هو الاختبار الصادق.','Seit Apples Tracking-Abfrage lassen sich die meisten iPhone-Spieler nicht einzeln verfolgen. Netzwerke erhalten gruppierte, verzögerte Apple-Berichte (SKAdNetwork / AdAttributionKit) und modellieren den Rest. Die Gesamt-Installs aus App Store Connect zählen nichts doppelt.')}</p></div>
 <div class="card"><h3>${tr('Run a clean lift test','نفّذ اختبار أثر نظيف','Sauberen Lift-Test durchführen')}</h3><ol class="small" style="margin:0;padding-inline-start:18px;line-height:1.8"><li>${tr('Pick one game and keep everything else the same (no update, no price change).','اختر لعبة واحدة وثبّت كل شيء آخر (لا تحديث ولا تغيير أسعار).','Ein Spiel wählen, alles andere gleich lassen.')}</li><li>${tr('Week 1: ads ON at your normal budget.','الأسبوع ١: الإعلانات تعمل بميزانيتك المعتادة.','Woche 1: Anzeigen AN mit normalem Budget.')}</li><li>${tr('Week 2: pause all paid campaigns for that game.','الأسبوع ٢: أوقف كل الحملات المدفوعة لتلك اللعبة.','Woche 2: alle bezahlten Kampagnen dieses Spiels pausieren.')}</li><li>${tr('Week 3: ads ON again. Avoid Ramadan, Eid and paydays (27th) for the test weeks.','الأسبوع ٣: شغّل الإعلانات مجدداً. تجنّب رمضان والعيد وأيام الرواتب (٢٧) في أسابيع الاختبار.','Woche 3: Anzeigen wieder AN. Ramadan, Eid und Zahltage meiden.')}</li><li>${tr('Come back here: the off week sets the baseline automatically.','عُد هنا: أسبوع الإيقاف يحدد الخط العضوي تلقائياً.','Hierher zurückkommen: die Pause-Woche setzt die Basis automatisch.')}</li></ol></div></div>`;
}

/* ---------- creative fatigue ---------- */
function mFatigue(){
 const cs=mkCamps(30).filter(c=>!c.manual).map(c=>({c,f:mkFatigue(c)})).filter(x=>x.f).sort((a,b)=>b.f.drop-a.f.drop);
 if(!cs.length)return mkDemoBanner()+`<div class="empty"><b>${tr('Needs at least 8 days of campaign data','يحتاج ٨ أيام على الأقل من بيانات الحملات','Braucht mindestens 8 Tage Kampagnendaten')}</b><p class="muted">${tr('Connect an ad account in Ad accounts, then sync.','اربط حساب إعلانات في حسابات الإعلانات ثم زامن.','Werbekonto unter Werbekonten verbinden, dann synchronisieren.')}</p></div>`;
 const sel=cs.find(x=>x.c.key===S.tab.mkf)||cs[0],F=sel.f;
 const st=x=>x.f.drop>=.3?[tr('Worn out · replace','مستهلك · استبدله','Ermüdet · ersetzen'),'heat-bad']:x.f.drop>=.15?[tr('Watch','راقب','Beobachten'),'heat-ok']:(x.f.age>=21&&['snap','tiktok'].includes(x.c.net))?[tr('Old · prepare a new one','قديم · جهّز بديلاً','Alt · neues vorbereiten'),'heat-ok']:[tr('Fresh','جديد','Frisch'),'heat-good'];
 const chart=chartPh({labels:F.series.map(x=>x.d),fmt:v=>pct(v,2),fmtAxis:v=>pct(v,1),series:[{name:'CTR (3-day)',color:'#ff2bd6',values:F.roll},{name:tr('Install rate','معدل التثبيت','Installrate'),color:'#27e2ff',values:F.ir,area:false}]},230);
 return mkDemoBanner()+`<div class="card"><h3>${tr('Creative health','صحة الإعلانات','Creative-Zustand')}</h3><div class="tbl-wrap"><table class="tbl"><thead><tr><th>${tr('Campaign','الحملة','Kampagne')}</th><th class="n">${tr('Age','العمر','Alter')}</th><th class="n">${tr('Peak CTR','ذروة النقر','Höchste CTR')}</th><th class="n">${tr('CTR now','النقر الآن','CTR jetzt')}</th><th class="n">${tr('Drop','الانخفاض','Rückgang')}</th><th>${t('status')}</th><th></th></tr></thead><tbody>${cs.map(x=>{const[s,cl]=st(x);return `<tr ${x===sel?'style="background:rgba(255,43,214,.06)"':''}><td><button class="lnk" data-mkset="tab.mkf" data-v="${esc(x.c.key)}" style="text-align:start">${esc(x.c.n)}</button><div class="muted small">${mkNetName(x.c.net)} · ${esc(gName(x.c.g))}</div></td><td class="n">${x.f.age}${tr('d','ي','T')}</td><td class="n">${pct(x.f.peak,2)}</td><td class="n">${pct(x.f.now,2)}</td><td class="n ${cl}">${pct(Math.max(0,x.f.drop),0)}</td><td class="${cl}">${s}</td><td>${canEdit()&&x.f.drop>=.15?`<button class="btn sm" data-mk="fat-task" data-id="${esc(x.c.key)}">${tr('Make task','أنشئ مهمة','Aufgabe')}</button>`:''}</td></tr>`}).join('')}</tbody></table></div></div>
 <div class="card" style="margin-top:14px"><h3>${esc(sel.c.n)}<span class="r"><button class="btn sm" data-goto="profit:addesign">${tr('Design fresh versions','صمّم نسخاً جديدة','Neue Versionen gestalten')}</button></span></h3>${chart}${mkNote(tr('On TikTok and Snapchat a creative usually wears out after 2–3 weeks. Replace it when the 3-day click rate falls 30% below its best, before the cost per install climbs. Keep the hook, change the first 2 seconds.','على تيك توك وسناب شات يُستهلك الإعلان عادة بعد ٢–٣ أسابيع. استبدله عندما ينخفض معدل النقر لثلاثة أيام ٣٠٪ عن أفضل قيمة، قبل أن ترتفع تكلفة التثبيت. احتفظ بالفكرة وغيّر أول ثانيتين.','Auf TikTok und Snapchat ermüdet ein Creative meist nach 2–3 Wochen. Ersetzen, wenn die 3-Tage-CTR 30% unter dem Bestwert liegt. Hook behalten, erste 2 Sekunden ändern.'))}</div>`;
}

/* ---------- App Store funnel ---------- */
function mStore(){
 const since=mkSince(30),G={};
 S.daily.forEach(r=>{if(r.d<since)return;const o=G[r.g]||(G[r.g]={imp:0,view:0,inst:0,days:{}});if(r.sImp!=null){o.imp+=+r.sImp||0;o.view+=+r.sView||0;o.inst+=+r.inst||0;o.days[r.d]=r}});
 if(MKD.demo)S.games.forEach(g=>{const a=agg(rowsFor(g.id,30));if(!a.inst||G[g.id]?.imp)return;const R=mkRand(g.id.length*97),cv=.22+R()*.18,tt=.04+R()*.06;const view=a.inst/cv,imp=view/tt;G[g.id]={imp,view,inst:a.inst,days:{},demo:1}});
 const L=Object.entries(G).filter(([,o])=>o.imp>0).map(([g,o])=>({g,...o,tt:o.view/o.imp,cv:o.inst/(o.view||1),all:o.inst/o.imp}));
 if(!L.length)return mkDemoBanner()+`<div class="empty"><b>${tr('No App Store funnel yet','لا يوجد قمع للمتجر بعد','Noch kein App-Store-Trichter')}</b><p class="muted">${tr('Connect App Store Connect in Reports → Data. Apple starts sending impressions and page views 1–2 days after the first sync.','اربط App Store Connect في التقارير ← البيانات. تبدأ Apple بإرسال مرات الظهور ومشاهدات الصفحة بعد ١–٢ يوم من أول مزامنة.','App Store Connect unter Berichte → Daten verbinden. Apple liefert Impressionen 1–2 Tage nach der ersten Synchronisierung.')}</p></div>`;
 const flag=x=>x.tt<.05?[tr('Few people open the page: test the icon, title, subtitle and first screenshot (what shows in search).','قلة يفتحون الصفحة: اختبر الأيقونة والاسم والعنوان الفرعي وأول لقطة (ما يظهر في البحث).','Wenige öffnen die Seite: Icon, Titel, Untertitel und erstes Screenshot testen.'),'heat-bad']:x.cv<.25?[tr('Visitors don\'t download: improve screenshots, the preview video and ratings; try a custom product page.','الزوار لا يحمّلون: حسّن اللقطات والفيديو والتقييمات وجرّب صفحة منتج مخصصة.','Besucher laden nicht: Screenshots, Video und Bewertungen verbessern; Custom Product Page testen.'),'heat-ok']:[tr('Healthy funnel','قمع جيد','Gesunder Trichter'),'heat-good'];
 const sel=L.find(x=>x.g===S.tab.mks)||L[0],terr={};
 Object.values(MKD.storeTerr[sel.g]||{}).forEach(day=>Object.entries(day||{}).forEach(([c,v])=>{const o=terr[c]||(terr[c]={imp:0,view:0});o.imp+=v.imp||0;o.view+=v.view||0}));
 const TT=Object.entries(terr).sort((a,b)=>b[1].imp-a[1].imp).slice(0,10);
 const days=Object.keys(sel.days).sort();
 return mkDemoBanner()+`<div class="card"><h3>${tr('App Store funnel · last 30 days','قمع المتجر · آخر ٣٠ يوماً','App-Store-Trichter · letzte 30 Tage')}</h3><div class="tbl-wrap"><table class="tbl"><thead><tr><th>${t('game')}</th><th class="n">${tr('Impressions','مرات الظهور','Impressionen')}</th><th class="n">${tr('Page views','مشاهدات الصفحة','Seitenaufrufe')}</th><th class="n">${t('installs')}</th><th class="n">${tr('Open rate','نسبة الفتح','Öffnungsrate')}</th><th class="n">${tr('Page → install','الصفحة ← التثبيت','Seite → Install')}</th><th class="n">${tr('Overall','الإجمالي','Gesamt')}</th><th>${tr('What to fix','ما يجب إصلاحه','Was verbessern')}</th></tr></thead><tbody>${L.map(x=>{const[fx,cl]=flag(x);return `<tr><td><button class="lnk" data-mkset="tab.mks" data-v="${x.g}">${esc(gName(x.g))}</button>${x.demo?' <span class="muted small">~</span>':''}</td><td class="n">${num(x.imp)}</td><td class="n">${num(x.view)}</td><td class="n">${num(x.inst)}</td><td class="n ${x.tt<.05?'heat-bad':'heat-good'}">${pct(x.tt)}</td><td class="n ${x.cv<.25?'heat-ok':'heat-good'}">${pct(x.cv)}</td><td class="n">${pct(x.all,2)}</td><td class="small ${cl}">${fx}</td></tr>`}).join('')}</tbody></table></div>
 ${mkNote(tr('Rough guide for games: open rate 5%+ and page-to-install 25–40% are healthy. Compare a game with itself over time more than with these numbers.','دليل تقريبي للألعاب: نسبة فتح ٥٪ فأكثر و٢٥–٤٠٪ من الصفحة إلى التثبيت أرقام جيدة. قارن اللعبة بنفسها عبر الوقت أكثر من هذه الأرقام.','Faustregel für Spiele: Öffnungsrate ab 5% und Seite→Install 25–40% sind gesund. Ein Spiel eher mit sich selbst vergleichen.'))}</div>
 <div class="grid g-main" style="margin-top:14px"><div class="card"><h3>${esc(gName(sel.g))}</h3>${days.length>2?chartPh({labels:days,fmt:v=>pct(v),fmtAxis:v=>pct(v,0),series:[{name:tr('Open rate','نسبة الفتح','Öffnungsrate'),color:'#ffb22e',values:days.map(d=>{const r=sel.days[d];return r.sImp?r.sView/r.sImp:null})},{name:tr('Page → install','الصفحة ← التثبيت','Seite → Install'),color:'#3dffa9',values:days.map(d=>{const r=sel.days[d];return r.sView?(+r.inst||0)/r.sView:null}),area:false}]},220):`<p class="muted">${tr('Daily detail appears after a few syncs.','تظهر التفاصيل اليومية بعد عدة مزامنات.','Tägliche Details nach einigen Synchronisierungen.')}</p>`}</div>
 <div class="card"><h3>${tr('By country','حسب الدولة','Nach Land')}</h3>${TT.length?`<div class="tbl-wrap"><table class="tbl"><thead><tr><th></th><th class="n">${tr('Impr.','الظهور','Impr.')}</th><th class="n">${tr('Open rate','نسبة الفتح','Öffnungsrate')}</th></tr></thead><tbody>${TT.map(([c,v])=>`<tr><td class="mono">${esc(c)}</td><td class="n">${num(v.imp)}</td><td class="n">${v.imp?pct(v.view/v.imp):'—'}</td></tr>`).join('')}</tbody></table></div>`:`<p class="muted small">${tr('Shown when App Store Connect is connected.','يظهر عند ربط App Store Connect.','Sichtbar, wenn App Store Connect verbunden ist.')}</p>`}</div></div>`;
}

/* ---------- custom product pages & A/B tests ---------- */
const CPP_THEMES=[
 {k:'ramadan',n:['Ramadan nights','ليالي رمضان','Ramadan-Nächte'],p:['Lantern-lit levels and calm night play after Iftar.','مراحل بأجواء الفوانيس ولعب هادئ بعد الإفطار.','Laternen-Level und ruhiges Spiel nach dem Iftar.'],s:['Hero shot with lanterns and crescent','Night-themed gameplay with Arabic caption','Reward box styled as Eidiya'],ch:'snap'},
 {k:'brain',n:['Brain training','تمرين الذكاء','Gehirntraining'],p:['Short puzzles that make you think. Free and offline.','ألغاز قصيرة تحرك عقلك. مجانية وبدون إنترنت.','Kurze Rätsel zum Nachdenken. Gratis und offline.'],s:['"Can you solve it?" level with timer','Before/after puzzle solution','Progress map: 300 levels'],ch:'meta'},
 {k:'offline',n:['Play offline','العب بدون إنترنت','Offline spielen'],p:['No Wi-Fi needed. Perfect for road trips and flights.','لا تحتاج واي فاي. مثالية للسفر والرحلات.','Kein WLAN nötig. Perfekt für Reisen.'],s:['Airplane-mode badge over gameplay','Car trip scene with the game','"300 levels, zero data" caption'],ch:'asa'},
 {k:'arabic',n:['Arabic first','عربية أولاً','Arabisch zuerst'],p:['Fully in Arabic, made in Saudi Arabia.','بالعربية بالكامل، صُنعت في السعودية.','Komplett auf Arabisch, made in Saudi-Arabien.'],s:['Arabic UI hero shot','Saudi landmarks or patterns','Family playing together'],ch:'tiktok'},
 {k:'challenge',n:['Hard mode challenge','تحدي المستوى الصعب','Hard-Mode-Challenge'],p:['Only 3% beat level 50. Are you next?','٣٪ فقط تجاوزوا المرحلة ٥٠. هل أنت التالي؟','Nur 3% schaffen Level 50. Du?'],s:['Hardest level with "3% finish" stamp','Leaderboard / badge screen','Fail-and-retry moment'],ch:'tiktok'},
 {k:'national',n:['National Day','اليوم الوطني','Nationalfeiertag'],p:['Green theme pack and a national-colours challenge.','حزمة باللون الأخضر وتحدي الألوان الوطنية.','Grünes Themenpaket und Nationalfarben-Challenge.'],s:['Green-themed hero shot','Event badge and dates','Exclusive skin reveal'],ch:'snap'}];
function mkZ(c1,n1,c2,n2){if(!n1||!n2)return null;const p1=c1/n1,p2=c2/n2,p=(c1+c2)/(n1+n2),se=Math.sqrt(p*(1-p)*(1/n1+1/n2));if(!se)return null;const z=(p2-p1)/se;const cdf=x=>{const t=1/(1+.2316419*Math.abs(x)),d=.3989423*Math.exp(-x*x/2),q=d*t*(.3193815+t*(-.3565638+t*(1.781478+t*(-1.821256+t*1.330274))));return x>0?1-q:q};return cdf(z)}
function mTests(){
 const m=mkS(),g0=gById(S.tab.mkt)?S.tab.mkt:(S.games[0]?.id||'');
 const plans=m.cpp.filter(p=>gById(p.g));
 const appId=g=>((CONN?.games||[]).find(x=>x.id===g)||{}).ascAppleId||'APP_ID';
 return `<div class="card"><h3>${tr('Custom product pages','صفحات المنتج المخصصة','Custom Product Pages')}<span class="r row" style="gap:6px">${mkGamePick(g0,'tab.mkt')}${canEdit()?`<button class="btn sm pri" data-mk="cpp-gen">${icon('spark')}${tr('Plan pages','خطط الصفحات','Seiten planen')}</button>`:''}</span></h3>
 <p class="muted small" style="margin:-4px 0 10px">${tr('Apple allows up to 35 extra store pages per app, each with its own screenshots, promo text and link. Send each ad to the page that matches it: a Ramadan ad lands on a Ramadan page, so more visitors download.','تسمح Apple بحتى ٣٥ صفحة متجر إضافية لكل تطبيق، لكل منها لقطاتها ونصها الترويجي ورابطها. أرسل كل إعلان إلى الصفحة المطابقة له: إعلان رمضان يصل لصفحة رمضان فيحمّل زوار أكثر.','Apple erlaubt bis zu 35 zusätzliche Store-Seiten pro App, jede mit eigenen Screenshots, Promo-Text und Link. Jede Anzeige auf die passende Seite schicken.')}</p>
 ${plans.length?`<div class="grid g2">${plans.map(p=>{const th=CPP_THEMES.find(x=>x.k===p.k)||CPP_THEMES[0],url=`https://apps.apple.com/app/id${appId(p.g)}${p.ppid?'?ppid='+p.ppid:'?ppid=PAGE_ID'}`;return `<div class="card" style="padding:14px"><div class="spread"><b>${esc(mkT(th.n))} · ${esc(gName(p.g))}</b><select class="inp" data-mkcpp="${p.id}:st" style="width:auto;padding:4px 6px">${[['idea',tr('Idea','فكرة','Idee')],['build',tr('Building','قيد البناء','In Arbeit')],['review',tr('In review','قيد المراجعة','In Prüfung')],['live',tr('Live','منشورة','Live')]].map(([k,v])=>`<option value="${k}" ${p.st===k?'selected':''}>${v}</option>`).join('')}</select></div>
  <div class="small" style="margin:6px 0"><span class="muted">${tr('Promo text','النص الترويجي','Promo-Text')}:</span> ${esc(th.p[0])}<br><span dir="rtl">${esc(th.p[1])}</span></div>
  <div class="small"><span class="muted">${tr('Screenshots','اللقطات','Screenshots')}:</span><ol style="margin:2px 0;padding-inline-start:18px">${th.s.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div>
  <div class="small"><span class="muted">${tr('Send ads from','أرسل الإعلانات من','Anzeigen aus')}:</span> ${mkNetName(th.ch)}</div>
  <div class="row" style="gap:6px;margin-top:8px"><input class="inp mono" placeholder="${tr('Page ID (ppid) from App Store Connect','معرّف الصفحة (ppid) من App Store Connect','Seiten-ID (ppid) aus App Store Connect')}" value="${esc(p.ppid||'')}" data-mkcpp="${p.id}:ppid" style="flex:1;min-width:160px"><button class="btn sm" data-copytxt="${esc(url)}">${tr('Copy ad link','انسخ رابط الإعلان','Anzeigenlink kopieren')}</button><button class="btn sm ghost" data-mk="cpp-del" data-id="${p.id}">✕</button></div></div>`}).join('')}</div>`:`<p class="muted" style="margin:0">${tr('Pick a game and press Plan pages.','اختر لعبة واضغط خطط الصفحات.','Spiel wählen und „Seiten planen“ drücken.')}</p>`}</div>
 <div class="card" style="margin-top:14px"><h3>${tr('A/B tests (Product Page Optimization)','اختبارات A/B (تحسين صفحة المنتج)','A/B-Tests (Product Page Optimization)')}<span class="r">${canEdit()?`<button class="btn sm" data-mk="test-add">${icon('plus')}${tr('New test','اختبار جديد','Neuer Test')}</button>`:''}</span></h3>
 ${m.tests.length?m.tests.map(T=>{const c=T.v[0]||{};return `<div class="card" style="padding:12px;margin-bottom:10px"><div class="spread" style="flex-wrap:wrap;gap:8px"><b>${esc(gName(T.g))} · ${esc({icon:tr('Icon','الأيقونة','Icon'),shots:tr('Screenshots','اللقطات','Screenshots'),video:tr('Preview video','الفيديو','Video')}[T.el]||T.el)}</b><span class="muted small mono">${esc(T.start)}</span><button class="btn sm ghost" data-mk="test-del" data-id="${T.id}">✕</button></div>
  <div class="tbl-wrap"><table class="tbl"><thead><tr><th>${tr('Variant','النسخة','Variante')}</th><th class="n">${tr('Impressions','مرات الظهور','Impressionen')}</th><th class="n">${t('installs')}</th><th class="n">${tr('Conversion','التحويل','Conversion')}</th><th class="n">${tr('vs original','مقابل الأصل','vs. Original')}</th><th class="n">${tr('Confidence','الثقة','Konfidenz')}</th></tr></thead><tbody>${T.v.map((v,i)=>{const cv=v.n?v.c/v.n:0,up=i&&c.n&&c.c?cv/(c.c/c.n)-1:null,conf=i?mkZ(c.c||0,c.n||0,v.c||0,v.n||0):null;return `<tr><td><input class="inp" value="${esc(v.name)}" data-mktest="${T.id}:${i}:name" style="min-width:110px"></td><td class="n"><input class="inp mono" type="number" min="0" value="${v.n||0}" data-mktest="${T.id}:${i}:n" style="width:100px"></td><td class="n"><input class="inp mono" type="number" min="0" value="${v.c||0}" data-mktest="${T.id}:${i}:c" style="width:90px"></td><td class="n">${pct(cv,2)}</td><td class="n ${up==null?'':up>0?'heat-good':'heat-bad'}">${up==null?'—':(up>0?'+':'')+pct(up)}</td><td class="n ${conf!=null&&conf>=.9?'heat-good':''}">${conf==null?'—':pct(conf,0)}</td></tr>`}).join('')}</tbody></table></div></div>`}).join(''):`<p class="muted" style="margin:0">${tr('Test the icon or the first screenshots: up to 3 variants against the original, for up to 90 days. Copy the numbers from App Store Connect → Product Page Optimization.','اختبر الأيقونة أو أول اللقطات: حتى ٣ نسخ مقابل الأصل ولمدة ٩٠ يوماً. انسخ الأرقام من App Store Connect ← Product Page Optimization.','Icon oder erste Screenshots testen: bis zu 3 Varianten gegen das Original, bis 90 Tage.')}</p>`}
 ${mkNote(tr('Call a winner only at 90% confidence or more, and after at least 7 days so weekends are included.','أعلن الفائز فقط عند ثقة ٩٠٪ أو أكثر وبعد ٧ أيام على الأقل حتى تدخل عطلة نهاية الأسبوع.','Gewinner erst ab 90% Konfidenz und nach mindestens 7 Tagen festlegen.'))}</div>`;
}

/* ---------- In-App Events ---------- */
const IAE_BADGE={challenge:['Challenge','تحدٍّ'],competition:['Competition','منافسة'],live:['Live Event','حدث مباشر'],update:['Major Update','تحديث كبير'],season:['New Season','موسم جديد'],premiere:['Premiere','عرض أول'],special:['Special Event','حدث خاص']};
const cut=(s,n)=>{s=String(s||'');return s.length<=n?s:s.slice(0,n-1).replace(/\s+\S*$/,'')+'…'};
function mkEventDraft(e,g){
 const nm=tx(g.name),en=e.n.en.replace(/\s*begins?\b/i,'').replace(/\bschool\s+/i,''),ar=(e.n.ar||e.n.en).replace(/^بداية\s*/,''),end=iso(new Date(new Date(e.d+'T12:00:00').getTime()+(/ramadan|رمضان/i.test(en)?29:/summer|winter|break/i.test(en)?20:6)*864e5));
 const badge=/ramadan|season/i.test(en)?'season':/national|founding/i.test(en)?'special':/eid/i.test(en)?'live':'challenge';
 return {id:uid(),g:g.id,ev:e.n.en,start:e.d,end,badge,st:'draft',
  nEn:cut(`${en} ${badge==='challenge'?'Challenge':badge==='season'?'Season':'Event'}`,30),nAr:cut(`${badge==='challenge'?'تحدي':badge==='season'?'موسم':'فعالية'} ${ar}`,30),
  sEn:cut(`Limited ${en} levels and rewards`,50),sAr:cut(`مراحل ومكافآت ${ar} لفترة محدودة`,50),
  lEn:cut(`Celebrate ${en} in ${nm}: themed levels, daily rewards and a special badge for every player who finishes.`,120),
  lAr:cut(`احتفل بـ${ar} في ${tx(g.name)}: مراحل خاصة ومكافآت يومية وشارة مميزة لكل من يُكمل التحدي.`,120)};
}
function mEvents(){
 const m=mkS(),E=calendarEvents().filter(e=>!e.on).slice(0,8),ev=m.events.filter(x=>gById(x.g)).sort((a,b)=>a.start.localeCompare(b.start));
 const cnt=(v,n)=>`<span class="mono small ${String(v||'').length>n?'heat-bad':'muted'}">${String(v||'').length}/${n}</span>`;
 const fld=(x,k,n,dir)=>`<div class="field"><label class="spread"><span>${k}</span>${cnt(x[k],n)}</label><input class="inp" ${dir?'dir="rtl"':''} value="${esc(x[k])}" data-mkev="${x.id}:${k}" maxlength="${n+20}"></div>`;
 return `<div class="card"><h3>${tr('Upcoming moments','المناسبات القادمة','Kommende Anlässe')}</h3><p class="muted small" style="margin:-4px 0 10px">${tr('In-App Events appear on your App Store page, in search and on the Today tab. Make one per game for each season so no moment is missed.','الفعاليات داخل التطبيق تظهر في صفحة المتجر والبحث وتبويب اليوم. أنشئ واحدة لكل لعبة في كل موسم حتى لا تفوتك مناسبة.','In-App-Events erscheinen auf der Store-Seite, in der Suche und im Heute-Tab. Pro Spiel und Saison eines anlegen.')}</p>
 <div class="tbl-wrap"><table class="tbl"><thead><tr><th>${tr('Moment','المناسبة','Anlass')}</th><th>${tr('Date','التاريخ','Datum')}</th><th class="n">${tr('Days left','الأيام المتبقية','Tage übrig')}</th><th></th></tr></thead><tbody>${E.map((e,i)=>`<tr><td>${esc(tx(e.n))}</td><td class="mono">${esc(e.d)}</td><td class="n ${e.left<=21?'heat-bad':e.left<=45?'heat-ok':''}">${e.left}</td><td>${canEdit()?`<button class="btn sm" data-mk="ev-gen" data-id="${i}">${tr('Draft for live games','مسودة للألعاب الحية','Entwurf für Live-Spiele')}</button>`:''}</td></tr>`).join('')}</tbody></table></div>
 ${mkNote(tr('Submit events at least 2 weeks early: Apple reviews them, and featuring needs time.','قدّم الفعاليات قبل أسبوعين على الأقل: Apple تراجعها والإبراز يحتاج وقتاً.','Events mindestens 2 Wochen vorher einreichen: Apple prüft sie.'))}</div>
 ${ev.length?`<div class="card" style="margin-top:14px"><h3>${tr('Event drafts','مسودات الفعاليات','Event-Entwürfe')} <span class="muted mono" style="font-size:13px">${ev.length}</span><span class="r"><button class="btn sm" data-mk="ev-export">${tr('Copy all','انسخ الكل','Alle kopieren')}</button></span></h3><div class="grid g2">${ev.map(x=>`<div class="card" style="padding:14px"><div class="spread" style="flex-wrap:wrap;gap:6px"><b>${esc(gName(x.g))} · ${esc(x.ev)}</b><span class="row" style="gap:6px"><select class="inp" data-mkev="${x.id}:badge" style="width:auto;padding:4px 6px">${Object.entries(IAE_BADGE).map(([k,v])=>`<option value="${k}" ${x.badge===k?'selected':''}>${S.lang==='ar'?v[1]:v[0]}</option>`).join('')}</select><select class="inp" data-mkev="${x.id}:st" style="width:auto;padding:4px 6px">${[['draft',tr('Draft','مسودة','Entwurf')],['sub',tr('Submitted','مقدّمة','Eingereicht')],['live',tr('Live','منشورة','Live')]].map(([k,v])=>`<option value="${k}" ${x.st===k?'selected':''}>${v}</option>`).join('')}</select><button class="btn sm ghost" data-mk="ev-del" data-id="${x.id}">✕</button></span></div>
  <div class="row small mono muted" style="gap:6px;margin:6px 0"><input class="inp mono" type="date" value="${esc(x.start)}" data-mkev="${x.id}:start" style="width:auto"> → <input class="inp mono" type="date" value="${esc(x.end)}" data-mkev="${x.id}:end" style="width:auto"></div>
  <div class="form">${fld(x,'nEn',30)}${fld(x,'nAr',30,1)}${fld(x,'sEn',50)}${fld(x,'sAr',50,1)}${fld(x,'lEn',120)}${fld(x,'lAr',120,1)}</div></div>`).join('')}</div>
  ${mkNote(tr('Limits: name 30, short description 50, long description 120 characters. Event card image 1920×1080 and event details image; make them in Ad design.','الحدود: الاسم ٣٠ والوصف القصير ٥٠ والطويل ١٢٠ حرفاً. صورة البطاقة ١٩٢٠×١٠٨٠ وصورة التفاصيل؛ صمّمها في تصميم الإعلانات.','Limits: Name 30, Kurzbeschreibung 50, Langbeschreibung 120 Zeichen. Kartenbild 1920×1080.'))}</div>`:''}`;
}

