const PS=(en,ar,de)=>({en,ar,de});
const PM_STRATS=[
 {n:PS('Core loop first','الحلقة الأساسية أولاً','Core Loop zuerst'),h:PS('Prove the 30-second loop is fun with grey boxes before any art, menus or monetization.','أثبت أن حلقة الـ٣٠ ثانية ممتعة بأشكال بسيطة قبل أي رسوم أو قوائم أو تحقيق دخل.','Beweisen, dass die 30-Sekunden-Schleife mit Platzhaltern Spaß macht, bevor Grafik, Menüs oder Monetarisierung kommen.'),s:PS('Build a one-level prototype in 3 days and watch 5 people play without helping them.','ابنِ نموذجاً بمرحلة واحدة في ٣ أيام وراقب ٥ أشخاص يلعبون دون مساعدتهم.','In 3 Tagen einen Ein-Level-Prototyp bauen und 5 Leuten ohne Hilfe zusehen.')},
 {n:PS('Kill fast, scale slow','أوقف بسرعة ووسّع ببطء','Schnell stoppen, langsam skalieren'),h:PS('Set kill criteria before each stage. Most game ideas should die cheaply; the few that pass every gate get the budget.','حدد معايير الإيقاف قبل كل مرحلة. معظم الأفكار يجب أن تموت بتكلفة قليلة؛ والقليل الذي يجتاز كل البوابات يحصل على الميزانية.','Abbruchkriterien vor jeder Phase festlegen. Die meisten Ideen sterben günstig; wenige, die alle Gates bestehen, bekommen Budget.'),s:PS('Write the soft-launch gate (D1, D7, crash-free, cost per install) in the Product board before building.','اكتب بوابة الإطلاق التجريبي (D1 وD7 والاستقرار وتكلفة التثبيت) في لوحة المنتجات قبل البناء.','Soft-Launch-Gate (D1, D7, Absturzfreiheit, CPI) vor dem Bauen im Board festhalten.')},
 {n:PS('Retention before acquisition','الاحتفاظ قبل الاستحواذ','Retention vor Akquise'),h:PS('Paid installs into a leaky game burn money. Fix D1 and D7 first; every point of retention makes each install worth more.','التثبيتات المدفوعة في لعبة تسرّب لاعبيها تحرق المال. أصلح D1 وD7 أولاً؛ كل نقطة احتفاظ تزيد قيمة كل تثبيت.','Bezahlte Installs in ein undichtes Spiel verbrennen Geld. Erst D1 und D7 verbessern.'),s:PS('Spend only a test budget until D7 reaches 12%.','أنفق ميزانية اختبار فقط حتى يصل D7 إلى ١٢٪.','Nur Testbudget, bis D7 12% erreicht.')},
 {n:PS('Soft launch in a look-alike market','إطلاق تجريبي في سوق مشابه','Soft Launch in ähnlichem Markt'),h:PS('Test in smaller markets similar to your target (for KSA: Bahrain, Oman or Kuwait) to read retention cheaply before the big launch.','اختبر في أسواق أصغر مشابهة لهدفك (للسعودية: البحرين أو عُمان أو الكويت) لقراءة الاحتفاظ بتكلفة قليلة قبل الإطلاق الكبير.','In kleineren ähnlichen Märkten testen (für KSA: Bahrain, Oman, Kuwait).'),s:PS('Run 2–4 weeks with a small UA budget, then compare with your gates.','شغّل ٢–٤ أسابيع بميزانية استحواذ صغيرة ثم قارن ببواباتك.','2–4 Wochen mit kleinem Budget, dann mit Gates vergleichen.')},
 {n:PS('LiveOps calendar','تقويم العمليات الحية','LiveOps-Kalender'),h:PS('Players return for things that change. Plan events around Ramadan, Eid, National Day, summer and weekends a quarter ahead.','اللاعبون يعودون لما يتغير. خطط للفعاليات حول رمضان والعيد واليوم الوطني والصيف وعطلات الأسبوع قبل ربع سنة.','Spieler kommen für Neues zurück. Events zu Ramadan, Eid, Nationalfeiertag, Sommer ein Quartal vorausplanen.'),s:PS('Use Marketing → In-App Events to draft them for all live games at once.','استخدم التسويق ← الفعاليات داخل التطبيق لصياغتها لكل الألعاب الحية دفعة واحدة.','Marketing → In-App-Events nutzen, um alle Live-Spiele auf einmal zu planen.')},
 {n:PS('Monetization ladder','سُلّم تحقيق الدخل','Monetarisierungs-Leiter'),h:PS('Give every player a fair way to pay: rewarded ads for everyone, a cheap starter pack, remove-ads for loyal players, and premium bundles for fans.','أعطِ كل لاعب طريقة عادلة للدفع: إعلانات مكافأة للجميع، وحزمة بداية رخيصة، وإزالة الإعلانات للأوفياء، وحزماً مميزة للمعجبين.','Jedem Spieler einen fairen Weg zu zahlen geben: Rewarded Ads, günstiges Starterpaket, Remove-Ads, Premium-Bundles.'),s:PS('Map each rung to a moment in the game where the player wants it.','اربط كل درجة بلحظة في اللعبة يريدها فيها اللاعب.','Jede Stufe einem Spielmoment zuordnen.')},
 {n:PS('Arabic first','العربية أولاً','Arabisch zuerst'),h:PS('Few games are truly Arabic-first. Right-to-left UI, local humour, Saudi voice and culture-aware events are a moat big studios rarely build.','قليل من الألعاب عربية أولاً حقاً. واجهة من اليمين لليسار، ودعابة محلية، وصوت سعودي، وفعاليات واعية بالثقافة ميزة نادراً ما تبنيها الاستوديوهات الكبيرة.','Wenige Spiele sind wirklich Arabisch-first. RTL-UI, lokaler Humor, saudische Stimme sind ein Burggraben.'),s:PS('Audit one game: every screen, font, number and date in Arabic.','راجع لعبة واحدة: كل شاشة وخط ورقم وتاريخ بالعربية.','Ein Spiel prüfen: jeder Screen, Font, Zahl, Datum auf Arabisch.')},
 {n:PS('Portfolio thinking','التفكير بالمحفظة','Portfolio-Denken'),h:PS('Treat games as a portfolio: a few earners fund experiments. Shared tech, art style and cross-promotion make each new game cheaper.','تعامل مع الألعاب كمحفظة: القليل الرابح يموّل التجارب. التقنية المشتركة وأسلوب الرسوم والترويج المتبادل تجعل كل لعبة جديدة أرخص.','Spiele als Portfolio: wenige Verdiener finanzieren Experimente. Gemeinsame Technik und Cross-Promo machen neue Spiele günstiger.'),s:PS('Each quarter label every game: scale, maintain, fix or sunset.','صنّف كل لعبة كل ربع: توسّع أو صيانة أو إصلاح أو إيقاف.','Jedes Quartal jedes Spiel einordnen: skalieren, halten, reparieren, auslaufen.')},
 {n:PS('Feature flags and staged rollout','مفاتيح الميزات والطرح التدريجي','Feature Flags & gestaffelter Rollout'),h:PS('Ship risky changes behind Remote Config switches, roll out to 10%, watch crashes and retention, then go to 100%.','أطلق التغييرات الخطرة خلف مفاتيح Remote Config، واطرحها لـ١٠٪، وراقب الأعطال والاحتفاظ، ثم ١٠٠٪.','Riskante Änderungen hinter Remote-Config-Schaltern ausliefern, 10% Rollout, dann 100%.'),s:PS('Add a kill switch to every new feature.','أضف مفتاح إيقاف لكل ميزة جديدة.','Jedem neuen Feature einen Kill-Switch geben.')},
 {n:PS('Featuring-ready quality','جودة جاهزة للإبراز','Featuring-taugliche Qualität'),h:PS('Apple features polished, accessible, well-localized games that use new iOS features. Featuring is free reach.','تبرز Apple الألعاب المصقولة سهلة الاستخدام والمترجمة جيداً التي تستخدم ميزات iOS الجديدة. الإبراز وصول مجاني.','Apple featured polierte, barrierearme, gut lokalisierte Spiele mit neuen iOS-Features.'),s:PS('Submit a featuring request in App Store Connect 6–8 weeks before a big update.','قدّم طلب إبراز في App Store Connect قبل ٦–٨ أسابيع من التحديث الكبير.','Featuring-Anfrage 6–8 Wochen vor großem Update in App Store Connect stellen.')}];
