const PM_TIPS=[
 ['disc','Watch, don\'t ask. Five silent playtests beat fifty survey answers.','راقب ولا تسأل. خمسة اختبارات لعب صامتة أفضل من خمسين إجابة استبيان.','Beobachten statt fragen. Fünf stille Playtests schlagen fünfzig Umfrageantworten.'],
 ['disc','Ask about the past (“last time you…”), not the future (“would you…”).','اسأل عن الماضي («آخر مرة…») لا عن المستقبل («هل ستفعل…»).','Nach Vergangenem fragen („letztes Mal…“), nicht nach Zukunft („würdest du…“).'],
 ['disc','Read 1–2★ reviews every Sunday; the same complaint three times is a roadmap item.','اقرأ مراجعات ١–٢★ كل أحد؛ الشكوى نفسها ثلاث مرات عنصر في خارطة الطريق.','Jeden Sonntag 1–2★-Reviews lesen; dreimal dieselbe Beschwerde ist ein Roadmap-Item.'],
 ['disc','Write the problem in the player\'s words before writing the solution.','اكتب المشكلة بكلمات اللاعب قبل كتابة الحل.','Problem in Worten des Spielers aufschreiben, bevor die Lösung kommt.'],
 ['prio','If everything is a priority, nothing is. Keep “Now” to what one release can ship.','إذا كان كل شيء أولوية فلا شيء أولوية. اجعل «الآن» بقدر ما يحتمله إصدار واحد.','Wenn alles Priorität hat, hat nichts Priorität. „Jetzt“ auf einen Release begrenzen.'],
 ['prio','Score with RICE, then sanity-check: does it move this quarter\'s goal?','قيّم بـRICE ثم تحقق: هل يحرك هدف هذا الربع؟','Mit RICE bewerten, dann prüfen: bewegt es das Quartalsziel?'],
 ['prio','Say no with a reason and a date: “Not now, we revisit after Ramadan.”','قل لا مع سبب وتاريخ: «ليس الآن، نراجعها بعد رمضان».','Nein sagen mit Grund und Datum: „Nicht jetzt, nach Ramadan wieder.“'],
 ['prio','Fix crashes and basic expectations before adding delighters.','أصلح الأعطال والتوقعات الأساسية قبل إضافة المبهجات.','Abstürze und Basiserwartungen vor Begeisterungs-Features beheben.'],
 ['data','Pick one metric per feature before building; no number, no feature.','اختر مقياساً واحداً لكل ميزة قبل البناء؛ لا رقم، لا ميزة.','Vor dem Bauen eine Kennzahl pro Feature wählen; ohne Zahl kein Feature.'],
 ['data','Compare cohorts, not totals: new players this week vs new players last month.','قارن الدفعات لا الإجماليات: لاعبو هذا الأسبوع الجدد مقابل لاعبي الشهر الماضي الجدد.','Kohorten statt Summen vergleichen.'],
 ['data','A level funnel shows exactly where players quit; fix the steepest drop first.','قمع المراحل يبين بالضبط أين يتوقف اللاعبون؛ أصلح أكبر انخفاض أولاً.','Ein Level-Funnel zeigt, wo Spieler aufhören; steilsten Abfall zuerst beheben.'],
 ['data','Weekdays and weekends behave differently in KSA; compare full weeks.','أيام الأسبوع وعطلاته تختلف في السعودية؛ قارن أسابيع كاملة.','Werktage und Wochenenden verhalten sich anders; volle Wochen vergleichen.'],
 ['game','The first 60 seconds decide D1: no long intro, play immediately, win early.','أول ٦٠ ثانية تحدد D1: لا مقدمة طويلة، العب فوراً، وفُز مبكراً.','Die ersten 60 Sekunden entscheiden D1: sofort spielen, früh gewinnen.'],
 ['game','Difficulty should be a saw-tooth: hard level, then two easier ones.','الصعوبة كأسنان المنشار: مرحلة صعبة ثم مرحلتان أسهل.','Schwierigkeit als Sägezahn: schweres Level, dann zwei leichtere.'],
 ['game','Put ads at natural breaks only; never interrupt a level.','ضع الإعلانات عند الاستراحات الطبيعية فقط؛ لا تقاطع مرحلة أبداً.','Ads nur an natürlichen Pausen; nie ein Level unterbrechen.'],
 ['game','Every session should end with a reason to come back tomorrow.','يجب أن تنتهي كل جلسة بسبب للعودة غداً.','Jede Session endet mit einem Grund, morgen wiederzukommen.'],
 ['launch','Ship small and often: a 2-week update rhythm beats one big update a quarter.','أطلق صغيراً ومتكرراً: تحديث كل أسبوعين أفضل من تحديث كبير كل ربع.','Klein und oft ausliefern: 2-Wochen-Rhythmus schlägt ein großes Quartals-Update.'],
 ['launch','Use phased release in App Store Connect for every update.','استخدم الإطلاق المرحلي في App Store Connect لكل تحديث.','Phased Release in App Store Connect für jedes Update nutzen.'],
 ['launch','Write release notes for players, not developers: what is new and fun.','اكتب ملاحظات الإصدار للاعبين لا للمطورين: ما الجديد والممتع.','Release Notes für Spieler schreiben, nicht für Entwickler.'],
 ['launch','Have a rollback plan before you press release.','جهّز خطة تراجع قبل الضغط على الإطلاق.','Rollback-Plan haben, bevor Sie veröffentlichen.'],
 ['team','A weekly 30-minute product review with numbers beats daily opinions.','مراجعة منتج أسبوعية لمدة ٣٠ دقيقة بالأرقام أفضل من آراء يومية.','Ein wöchentlicher 30-Minuten-Review mit Zahlen schlägt tägliche Meinungen.'],
 ['team','Share the why, not only the what; people build better when they know the goal.','شارك السبب لا الماذا فقط؛ الناس يبنون أفضل حين يعرفون الهدف.','Das Warum teilen, nicht nur das Was.'],
 ['team','Write decisions down in the spec; memory is not a process.','دوّن القرارات في المواصفات؛ الذاكرة ليست عملية.','Entscheidungen in der Spec festhalten; Erinnerung ist kein Prozess.'],
 ['team','Celebrate killed features that saved time, not only shipped ones.','احتفل بالميزات الملغاة التي وفّرت الوقت لا بالمطلقة فقط.','Auch gestoppte Features feiern, die Zeit gespart haben.']];
const PM_STORIES=[
 {n:'Supercell',y:'2010s',t:PS('Small teams, many cancelled games','فرق صغيرة وألعاب كثيرة أُلغيت','Kleine Teams, viele gestoppte Spiele'),b:PS('Supercell organizes into small independent “cells” that decide themselves whether a game continues. The studio has publicly described cancelling many games in soft launch and celebrating the lessons, which kept only the strongest titles such as Clash of Clans and Clash Royale.','تنظّم Supercell نفسها في «خلايا» صغيرة مستقلة تقرر بنفسها استمرار اللعبة. وأعلن الاستوديو إيقاف ألعاب كثيرة في الإطلاق التجريبي والاحتفاء بدروسها، فبقيت الأقوى فقط مثل Clash of Clans وClash Royale.','Supercell arbeitet in kleinen unabhängigen „Cells“, die selbst über ein Spiel entscheiden. Viele Spiele wurden im Soft Launch gestoppt; nur die stärksten wie Clash of Clans und Clash Royale blieben.'),l:PS('Strict stage gates protect your budget for the winners.','بوابات المراحل الصارمة تحمي ميزانيتك للرابحين.','Strenge Gates schützen das Budget für Gewinner.')},
 {n:'Candy Crush Saga',y:'2012',t:PS('Tested on the web first','اختُبرت على الويب أولاً','Zuerst im Web getestet'),b:PS('King first ran the game on its website and on Facebook, studied how players progressed, and only then built the mobile version, which became one of the most played mobile games.','شغّلت King اللعبة أولاً على موقعها وعلى فيسبوك ودرست تقدم اللاعبين، ثم بنت نسخة الجوال التي أصبحت من أكثر ألعاب الجوال لعباً.','King testete das Spiel erst auf der Website und Facebook, studierte den Fortschritt und baute dann die Mobile-Version.'),l:PS('Validate the design where it is cheapest, then scale.','تحقق من التصميم حيث يكون الأرخص ثم توسّع.','Design dort validieren, wo es am günstigsten ist, dann skalieren.')},
 {n:'Fortnite Battle Royale',y:'2017',t:PS('A fast pivot inside an existing game','تحول سريع داخل لعبة قائمة','Schneller Pivot in einem bestehenden Spiel'),b:PS('Epic saw the rise of the battle royale genre and built a free battle royale mode on top of Fortnite\'s existing tech in about two months. That mode became the product.','لاحظت Epic صعود نوع باتل رويال فبنت طوراً مجانياً فوق تقنية Fortnite الموجودة في نحو شهرين، وأصبح هذا الطور هو المنتج.','Epic baute in rund zwei Monaten einen kostenlosen Battle-Royale-Modus auf vorhandener Fortnite-Technik; dieser Modus wurde das Produkt.'),l:PS('Reuse your tech to test a new market shape quickly.','أعد استخدام تقنيتك لاختبار شكل سوق جديد بسرعة.','Vorhandene Technik nutzen, um schnell neue Marktformen zu testen.')},
 {n:'Among Us',y:'2018 → 2020',t:PS('A second life two years later','حياة ثانية بعد عامين','Zweites Leben zwei Jahre später'),b:PS('Innersloth released Among Us in 2018 with modest results. In 2020 streamers made it a worldwide hit, and the small team kept the game alive with updates instead of starting a sequel.','أصدرت Innersloth لعبة Among Us في ٢٠١٨ بنتائج متواضعة. وفي ٢٠٢٠ جعلها صناع المحتوى نجاحاً عالمياً، واستمر الفريق الصغير بتحديثها بدلاً من البدء بجزء ثانٍ.','Innersloth veröffentlichte Among Us 2018 mit mäßigem Erfolg. 2020 machten Streamer es weltweit bekannt; das kleine Team pflegte das Spiel weiter.'),l:PS('Social play and creators can revive a live game; keep it ready.','اللعب الجماعي وصناع المحتوى قد يعيدون الحياة للعبة؛ اجعلها جاهزة.','Soziales Spielen und Creator können ein Spiel wiederbeleben.')},
 {n:'Wordle',y:'2021',t:PS('Constraint as the feature','القيد كميزة','Die Einschränkung als Feature'),b:PS('Josh Wardle\'s word game allowed one puzzle a day and a simple emoji share grid. The limit created a daily ritual and free word of mouth; The New York Times bought it in early 2022.','لعبة الكلمات من Josh Wardle سمحت بلغز واحد يومياً ومشاركة بسيطة بالرموز. صنع القيد عادة يومية وانتشاراً مجانياً، واشترتها نيويورك تايمز بداية ٢٠٢٢.','Josh Wardles Wortspiel erlaubte ein Rätsel pro Tag und ein Emoji-Teilen-Raster. Die Grenze schuf ein Ritual; die New York Times kaufte es Anfang 2022.'),l:PS('A daily limit plus a shareable result can beat endless content.','حد يومي مع نتيجة قابلة للمشاركة قد يتفوق على المحتوى اللامحدود.','Tageslimit plus teilbares Ergebnis kann endlosen Content schlagen.')},
 {n:'Duolingo',y:'2010s',t:PS('Streaks and constant A/B tests','السلاسل واختبارات A/B المستمرة','Streaks und ständige A/B-Tests'),b:PS('Duolingo has written publicly about running many experiments at the same time and treating the daily streak as a core retention feature, improving it through repeated tests.','كتبت Duolingo علناً عن تشغيل تجارب كثيرة في وقت واحد واعتبار السلسلة اليومية ميزة أساسية للاحتفاظ تتحسن عبر اختبارات متكررة.','Duolingo berichtet über viele parallele Experimente; der tägliche Streak ist ein Kern-Retention-Feature, verbessert durch Tests.'),l:PS('Small tested improvements to one habit loop compound.','التحسينات الصغيرة المختبرة على حلقة عادة واحدة تتراكم.','Kleine getestete Verbesserungen an einer Gewohnheitsschleife summieren sich.')},
 {n:'Slack',y:'2013',t:PS('Born from a failed game','وُلدت من لعبة فاشلة','Aus einem gescheiterten Spiel geboren'),b:PS('Tiny Speck built the online game Glitch, which shut down in 2012. The internal chat tool the team had built for itself became Slack.','بنت Tiny Speck لعبة Glitch الإلكترونية التي أُغلقت في ٢٠١٢، وأصبحت أداة المحادثة الداخلية التي بناها الفريق لنفسه هي Slack.','Tiny Speck baute das Onlinespiel Glitch, das 2012 schloss. Das interne Chat-Tool wurde zu Slack.'),l:PS('Look at the tools you build for yourself; one may be a product.','انظر إلى الأدوات التي تبنيها لنفسك؛ قد تكون إحداها منتجاً.','Eigene interne Tools anschauen; eins kann ein Produkt sein.')},
 {n:'Instagram',y:'2010',t:PS('Cut everything but one thing','احذف كل شيء إلا شيئاً واحداً','Alles außer einer Sache streichen'),b:PS('The founders started with Burbn, a check-in app with many features. Seeing that people mainly shared photos, they removed the rest and relaunched as Instagram.','بدأ المؤسسون بتطبيق Burbn للتسجيل في الأماكن بميزات كثيرة. ولما رأوا أن الناس يشاركون الصور أساساً، حذفوا الباقي وأعادوا الإطلاق باسم Instagram.','Die Gründer starteten mit Burbn, einer Check-in-App. Da Nutzer vor allem Fotos teilten, strichen sie den Rest und starteten Instagram.'),l:PS('Follow what users actually do, then simplify hard.','اتبع ما يفعله المستخدمون فعلاً ثم بسّط بقوة.','Dem echten Nutzerverhalten folgen, dann radikal vereinfachen.')}];
const PG=[['North Star metric','data','The one number that best shows players get value (e.g. weekly players who finish a level).','الرقم الوحيد الذي يبين أن اللاعبين يحصلون على قيمة (مثل اللاعبين الأسبوعيين الذين يُنهون مرحلة).','Die eine Zahl, die zeigt, dass Spieler Wert erhalten.'],['OKR','team','Objective plus 2–4 measurable key results for a quarter.','هدف مع ٢–٤ نتائج رئيسية قابلة للقياس لربع سنة.','Ziel plus 2–4 messbare Schlüsselergebnisse pro Quartal.'],['PRD','team','Product requirements document: problem, goal, scope and launch plan of a feature.','وثيقة متطلبات المنتج: المشكلة والهدف والنطاق وخطة الإطلاق.','Product Requirements Document: Problem, Ziel, Umfang, Launch-Plan.'],['MVP','disc','Smallest version that tests the riskiest assumption with real players.','أصغر نسخة تختبر أخطر افتراض مع لاعبين حقيقيين.','Kleinste Version, die die riskanteste Annahme testet.'],['RICE','prio','Reach × Impact × Confidence ÷ Effort.','الوصول × الأثر × الثقة ÷ الجهد.','Reichweite × Wirkung × Sicherheit ÷ Aufwand.'],['ICE','prio','Impact × Confidence × Ease, a quicker score.','الأثر × الثقة × السهولة، درجة أسرع.','Wirkung × Sicherheit × Einfachheit.'],['MoSCoW','prio','Must, Should, Could, Won\'t: sorting a release scope.','ضروري، مهم، ممكن، ليس الآن: لترتيب نطاق الإصدار.','Must, Should, Could, Won\'t.'],['Kano model','prio','Basic, performance and delighter features.','الميزات الأساسية والأداء والمبهجة.','Basis-, Leistungs- und Begeisterungsmerkmale.'],['Opportunity solution tree','disc','Outcome → opportunities (player problems) → solutions → tests.','النتيجة ← الفرص (مشكلات اللاعبين) ← الحلول ← الاختبارات.','Ergebnis → Chancen → Lösungen → Tests.'],['Jobs to be done','disc','The progress a player wants in a situation (kill 5 minutes, feel smart).','التقدم الذي يريده اللاعب في موقف (قضاء ٥ دقائق، الشعور بالذكاء).','Der Fortschritt, den ein Spieler will (5 Minuten füllen, sich klug fühlen).'],['Persona','disc','A realistic profile of a key player group.','ملف واقعي لمجموعة لاعبين أساسية.','Realistisches Profil einer Spielergruppe.'],['Cohort','data','Players who started in the same period, followed over time.','لاعبون بدأوا في الفترة نفسها ونتابعهم عبر الوقت.','Spieler mit gleichem Startzeitraum.'],['Funnel','data','Steps players go through; the drop between steps shows friction.','خطوات يمر بها اللاعبون؛ الانخفاض بينها يبين الاحتكاك.','Schritte der Spieler; Abfall zeigt Reibung.'],['Stickiness (DAU/MAU)','data','Share of monthly players who play on a given day.','نسبة اللاعبين الشهريين الذين يلعبون في يوم ما.','Anteil der Monatsspieler, die an einem Tag spielen.'],['Statistical significance','data','How sure we are a test difference is not luck.','مدى تأكدنا أن الفرق في الاختبار ليس صدفة.','Wie sicher ein Unterschied kein Zufall ist.'],['MDE','data','Minimum detectable effect: the smallest lift a test is sized to see.','أقل أثر يمكن رصده: أصغر تحسّن صُمم الاختبار لرؤيته.','Kleinster nachweisbarer Effekt.'],['Feature flag','launch','Switch that turns a feature on or off without a new build.','مفتاح يشغّل الميزة أو يوقفها بدون إصدار جديد.','Schalter, der ein Feature ohne neuen Build schaltet.'],['Phased release','launch','App Store rollout to a growing share of users over 7 days.','طرح تدريجي في المتجر لنسبة متزايدة خلال ٧ أيام.','Gestaffelter App-Store-Rollout über 7 Tage.'],['Soft launch','launch','Release in a few markets to measure before going global.','إطلاق في أسواق قليلة للقياس قبل العالمي.','Release in wenigen Märkten vor global.'],['Stage gate','launch','Agreed numbers a game must reach before the next stage.','أرقام متفق عليها يجب أن تبلغها اللعبة قبل المرحلة التالية.','Vereinbarte Zahlen vor der nächsten Phase.'],['Core loop','game','The repeated action–reward cycle at the heart of the game.','دورة الفعل والمكافأة المتكررة في قلب اللعبة.','Der wiederholte Aktion-Belohnungs-Zyklus.'],['Meta game','game','Long-term layer around the core loop: collections, progression, map.','الطبقة طويلة المدى حول الحلقة الأساسية: المجموعات والتقدم والخريطة.','Langfristige Ebene: Sammlungen, Fortschritt, Karte.'],['FTUE','game','First-time user experience: the first minutes of play.','تجربة المستخدم الأولى: أول دقائق اللعب.','Erste Spielerfahrung.'],['Economy','game','How coins, lives and rewards are earned and spent.','كيف تُكسب العملات والأرواح والمكافآت وتُصرف.','Wie Münzen, Leben, Belohnungen verdient und ausgegeben werden.'],['LiveOps','game','Ongoing events, offers and content after launch.','الفعاليات والعروض والمحتوى المستمر بعد الإطلاق.','Laufende Events, Angebote, Inhalte nach Launch.'],['Roadmap','team','Plan of what comes now, next and later, tied to goals.','خطة ما يأتي الآن والتالي ولاحقاً مرتبطة بالأهداف.','Plan von Jetzt, Als Nächstes, Später.'],['Backlog','team','Ordered list of everything that could be built.','قائمة مرتبة بكل ما يمكن بناؤه.','Geordnete Liste aller möglichen Arbeiten.'],['Product-market fit','disc','Players keep coming back and tell others without being pushed.','اللاعبون يعودون ويخبرون غيرهم دون دفع.','Spieler kommen wieder und empfehlen ohne Druck.'],['TAM / SAM / SOM','data','Total, serviceable and obtainable market.','السوق الكلي والقابل للخدمة والقابل للتحصيل.','Gesamt-, bedienbarer und erreichbarer Markt.'],['NPS','data','Promoters minus detractors on a 0–10 recommend question.','المروّجون ناقص المنتقدين في سؤال التوصية من ٠–١٠.','Promotoren minus Kritiker (0–10).']];
const PCL=(en,ar,de,ben,bar,bde,code)=>({t:PS(en,ar,de),b:PS(ben,bar,bde),code});
const PM_COURSES=[
 {id:'pm1',ic:'product',t:PS('Product management for game studios','إدارة المنتجات لاستوديوهات الألعاب','Produktmanagement für Spielestudios'),l:[
  PCL('What a game PM does','ماذا يفعل مدير منتج الألعاب','Was ein Game-PM macht','Owns the why and the what: player problems, goals, priorities and success numbers. The team owns the how. A PM decides with data, writes it down and says no often.','يملك «لماذا» و«ماذا»: مشكلات اللاعبين والأهداف والأولويات وأرقام النجاح. والفريق يملك «كيف». يقرر المدير بالبيانات ويدوّن ويقول لا كثيراً.','Verantwortet Warum und Was: Spielerprobleme, Ziele, Prioritäten, Erfolgszahlen. Das Team verantwortet das Wie.'),
  PCL('Products, not projects','منتجات لا مشاريع','Produkte, nicht Projekte','A project ends at launch; a product is judged by what players do after it. Measure success by retention and revenue, not by shipping on time.','المشروع ينتهي بالإطلاق، أما المنتج فيُقاس بما يفعله اللاعبون بعده. قِس النجاح بالاحتفاظ والإيراد لا بالتسليم في الموعد.','Ein Projekt endet mit dem Launch; ein Produkt wird danach gemessen.'),
  PCL('Vision, strategy, roadmap','الرؤية والاستراتيجية وخارطة الطريق','Vision, Strategie, Roadmap','Vision: where the game is going in 2 years. Strategy: the few bets to get there. Roadmap: the order of work. Each level answers why for the one below.','الرؤية: إلى أين تتجه اللعبة خلال سنتين. الاستراتيجية: الرهانات القليلة للوصول. خارطة الطريق: ترتيب العمل. كل مستوى يجيب «لماذا» للمستوى تحته.','Vision: wohin in 2 Jahren. Strategie: wenige Wetten. Roadmap: Reihenfolge der Arbeit.'),
  PCL('The weekly rhythm','الإيقاع الأسبوعي','Der Wochenrhythmus','Sunday: read numbers and reviews. Monday: product review with the team. Midweek: talk to players and write specs. Thursday: decide next week\'s priorities.','الأحد: اقرأ الأرقام والمراجعات. الاثنين: مراجعة المنتج مع الفريق. منتصف الأسبوع: تحدث مع اللاعبين واكتب المواصفات. الخميس: قرر أولويات الأسبوع القادم.','Sonntag Zahlen lesen, Montag Review, Mitte Spieler sprechen und Specs schreiben, Donnerstag Prioritäten.'),
  PCL('Your first 30 days','أول ٣٠ يوماً لك','Ihre ersten 30 Tage','Week 1: learn every game and metric. Week 2: interview 10 players. Week 3: pick one North Star per game. Week 4: publish a Now/Next/Later roadmap.','الأسبوع ١: تعلّم كل لعبة ومقياس. الأسبوع ٢: قابل ١٠ لاعبين. الأسبوع ٣: اختر نجم شمال لكل لعبة. الأسبوع ٤: انشر خارطة الآن/التالي/لاحقاً.','Woche 1 Spiele lernen, Woche 2 Spieler interviewen, Woche 3 North Star, Woche 4 Roadmap.')]},
 {id:'pm2',ic:'spark',t:PS('Discovery: find what players need','الاستكشاف: اكتشف ما يحتاجه اللاعبون','Discovery: Spielerbedürfnisse finden'),l:[
  PCL('Four risks','أربع مخاطر','Vier Risiken','Before building, check value (will they want it), usability (can they use it), feasibility (can we build it) and viability (does it make money).','قبل البناء تحقق من القيمة (هل يريدونها) وسهولة الاستخدام والجدوى التقنية والجدوى المالية.','Vor dem Bauen Wert, Bedienbarkeit, Machbarkeit und Wirtschaftlichkeit prüfen.'),
  PCL('Playtests that tell the truth','اختبارات لعب تقول الحقيقة','Ehrliche Playtests','Give the phone, say nothing, watch faces and fingers. Note where they hesitate, smile or quit. Five players find most problems.','أعطِ الجوال ولا تقل شيئاً وراقب الوجوه والأصابع. سجّل أين يترددون أو يبتسمون أو يتوقفون. خمسة لاعبين يكشفون معظم المشكلات.','Handy geben, schweigen, Gesichter und Finger beobachten. Fünf Spieler finden die meisten Probleme.'),
  PCL('Interviews without bias','مقابلات بلا تحيّز','Interviews ohne Verzerrung','Ask about real past behaviour, follow with “why” twice, never pitch. Record the exact words players use; they become store copy later.','اسأل عن السلوك الماضي الحقيقي، وتابع بـ«لماذا» مرتين، ولا تعرض فكرتك. سجّل كلمات اللاعبين بدقة؛ ستصبح نصوص المتجر لاحقاً.','Nach echtem Verhalten fragen, zweimal warum, nie verkaufen. Exakte Worte notieren.'),
  PCL('Reviews and data as research','المراجعات والبيانات كبحث','Reviews und Daten als Forschung','Combine what players say (reviews) with what they do (funnels, retention). When both point to the same place, you found an opportunity.','اجمع ما يقوله اللاعبون (المراجعات) مع ما يفعلونه (القمع والاحتفاظ). حين يشيران للمكان نفسه وجدت فرصة.','Sagen (Reviews) und Tun (Funnels) kombinieren. Zeigen beide auf dieselbe Stelle, ist das eine Chance.'),
  PCL('Fake doors and prototypes','الأبواب الوهمية والنماذج','Fake Doors und Prototypen','Test demand before building: a “coming soon” button that counts taps, or a paper prototype of a new mode. Cheap tests kill bad ideas early.','اختبر الطلب قبل البناء: زر «قريباً» يحسب النقرات أو نموذج ورقي لطور جديد. الاختبارات الرخيصة تقتل الأفكار السيئة مبكراً.','Nachfrage vor dem Bauen testen: „Bald verfügbar“-Button zählt Taps.')]},
 {id:'pm3',ic:'reports',t:PS('Prioritize and build roadmaps','حدد الأولويات وابنِ خارطة الطريق','Priorisieren und Roadmaps bauen'),l:[
  PCL('Start from goals','ابدأ من الأهداف','Von Zielen ausgehen','Set one quarterly goal per game (an OKR). Only work that moves it goes into Now.','حدد هدفاً ربعياً واحداً لكل لعبة (OKR). فقط العمل الذي يحركه يدخل «الآن».','Ein Quartalsziel pro Spiel (OKR). Nur Arbeit, die es bewegt, kommt in „Jetzt“.'),
  PCL('Scoring with RICE and ICE','التقييم بـRICE وICE','Bewerten mit RICE und ICE','Use RICE when you have reach data, ICE for quick triage. Scores start the conversation; they do not replace judgment.','استخدم RICE حين تتوفر بيانات الوصول وICE للفرز السريع. الدرجات تبدأ النقاش ولا تلغي الحكم.','RICE mit Reichweitendaten, ICE für schnelle Triage. Scores ersetzen kein Urteil.'),
  PCL('Now / Next / Later','الآن / التالي / لاحقاً','Jetzt / Als Nächstes / Später','Avoid date-heavy roadmaps for uncertain work. Commit to Now, sketch Next, keep Later as a list of problems, not features.','تجنب خارطة طريق مثقلة بالتواريخ للعمل غير المؤكد. التزم بالآن وارسم التالي واجعل لاحقاً قائمة مشكلات لا ميزات.','Bei Unsicherheit keine Datums-Roadmaps. Jetzt verbindlich, Später als Problemliste.'),
  PCL('Balancing the portfolio','موازنة المحفظة','Portfolio ausbalancieren','Split capacity roughly: 60% growth of winners, 25% quality and tech, 15% new bets. Revisit every quarter.','وزّع الطاقة تقريباً: ٦٠٪ لنمو الرابحين و٢٥٪ للجودة والتقنية و١٥٪ لرهانات جديدة. راجعها كل ربع.','Kapazität grob: 60% Wachstum, 25% Qualität/Technik, 15% neue Wetten.'),
  PCL('Saying no well','قول لا بشكل جيد','Gut Nein sagen','Explain the goal, show the ranked list and offer when it could be revisited. A clear no protects the team\'s focus.','اشرح الهدف واعرض القائمة المرتبة واقترح موعداً للمراجعة. الرفض الواضح يحمي تركيز الفريق.','Ziel erklären, Rangliste zeigen, Wiedervorlage anbieten.')]},
 {id:'pm4',ic:'kpis',t:PS('Metrics that matter','المقاييس المهمة','Kennzahlen, die zählen'),l:[
  PCL('Pick a North Star','اختر نجم الشمال','Einen North Star wählen','It must reflect player value, lead revenue and be movable by the team. For casual games: weekly players who complete at least 3 levels.','يجب أن يعكس قيمة اللاعب ويسبق الإيراد ويمكن للفريق تحريكه. للألعاب العابرة: اللاعبون الأسبوعيون الذين يُكملون ٣ مراحل على الأقل.','Muss Spielerwert abbilden, Umsatz vorausgehen und beeinflussbar sein.'),
  PCL('The metric tree','شجرة المقاييس','Der Kennzahlenbaum','Break the North Star into acquisition, activation, engagement, retention, monetization and quality. Assign each branch an owner.','قسّم نجم الشمال إلى استحواذ وتفعيل وتفاعل واحتفاظ ودخل وجودة. عيّن مسؤولاً لكل فرع.','North Star in Akquise, Aktivierung, Engagement, Retention, Monetarisierung, Qualität zerlegen.'),
  PCL('Reading retention curves','قراءة منحنيات الاحتفاظ','Retention-Kurven lesen','A curve that flattens means a loyal core; one that keeps falling means no long-term reason to play. Compare new cohorts after each update.','المنحنى الذي يستقر يعني نواة وفية، والذي يستمر بالهبوط يعني غياب سبب طويل للعب. قارن الدفعات الجديدة بعد كل تحديث.','Abflachende Kurve = treuer Kern; weiter fallend = kein Langzeitgrund.'),
  PCL('Unit economics','اقتصاديات الوحدة','Unit Economics','Value per player (LTV) must beat cost per install (CPI). Payback days tell how long money is locked in growth.','قيمة اللاعب (LTV) يجب أن تتجاوز تكلفة التثبيت (CPI). أيام الاسترداد تبين كم يبقى المال محبوساً في النمو.','LTV muss CPI schlagen. Amortisationstage zeigen, wie lange Geld gebunden ist.'),
  PCL('Dashboards people use','لوحات يستخدمها الناس','Dashboards, die genutzt werden','One page per game, five numbers, trend vs last period, and one sentence of interpretation. Kinzhal Nest\'s Product board does exactly this.','صفحة لكل لعبة وخمسة أرقام واتجاه مقارنة بالفترة السابقة وجملة تفسير واحدة. لوحة المنتجات في كينجال نست تفعل ذلك تماماً.','Eine Seite pro Spiel, fünf Zahlen, Trend, ein Satz Interpretation.')]},
 {id:'pm5',ic:'profit',t:PS('Experiments and A/B tests','التجارب واختبارات A/B','Experimente und A/B-Tests'),l:[
  PCL('Write a hypothesis','اكتب فرضية','Eine Hypothese schreiben','If we change X for players Y, metric Z will move by N because of reason R. Without a reason you cannot learn from a loss.','إذا غيّرنا X للاعبين Y فسيتحرك المقياس Z بمقدار N بسبب R. بلا سبب لا يمكنك التعلم من الفشل.','Wenn wir X für Spieler Y ändern, bewegt sich Z um N wegen R.'),
  PCL('Size before you start','حدد الحجم قبل البدء','Vor dem Start dimensionieren','Use the sample-size calculator: baseline, smallest lift that matters, daily players. Run full weeks.','استخدم حاسبة حجم العينة: الأساس وأقل تحسّن مهم واللاعبون اليوميون. شغّل أسابيع كاملة.','Stichprobenrechner nutzen: Basis, kleinster Lift, tägliche Spieler. Volle Wochen.'),
  PCL('Run it with Firebase','شغّلها بـFirebase','Mit Firebase durchführen','Firebase A/B Testing splits players with Remote Config values and reports retention and revenue per group.','يقسم Firebase A/B Testing اللاعبين بقيم Remote Config ويعرض الاحتفاظ والإيراد لكل مجموعة.','Firebase A/B Testing teilt Spieler per Remote Config und zeigt Retention und Umsatz.'),
  PCL('Read results honestly','اقرأ النتائج بصدق','Ergebnisse ehrlich lesen','Decide on the metric chosen beforehand, at 95% confidence, after the planned sample. Check that the guardrails (crashes, ratings) did not drop.','قرر على المقياس المختار مسبقاً عند ثقة ٩٥٪ بعد العينة المخططة. وتحقق أن مقاييس الحماية (الأعطال والتقييم) لم تنخفض.','Nach vorab gewählter Kennzahl, 95%, nach Stichprobe entscheiden; Leitplanken prüfen.'),
  PCL('Build a learning log','ابنِ سجل تعلّم','Ein Lernprotokoll führen','Record every test, result and lesson. Losing tests are valuable: they stop the team repeating ideas that do not work.','سجّل كل اختبار ونتيجته ودرسه. الاختبارات الخاسرة قيّمة لأنها تمنع تكرار أفكار لا تنجح.','Jeden Test, jedes Ergebnis, jede Lektion festhalten.')]},
 {id:'pm6',ic:'games',t:PS('Game product craft','حرفة منتج الألعاب','Handwerk Spielprodukt'),l:[
  PCL('The first session','الجلسة الأولى','Die erste Session','Play within 5 seconds, teach by doing, give a win in the first minute, and show what comes next before the session ends.','العب خلال ٥ ثوانٍ وعلّم بالممارسة وامنح فوزاً في الدقيقة الأولى وأظهر ما سيأتي قبل انتهاء الجلسة.','In 5 Sekunden spielen, durch Tun lehren, in Minute 1 gewinnen, Ausblick zeigen.'),
  PCL('Core loop and meta','الحلقة الأساسية والطبقة العليا','Core Loop und Meta','The core loop is fun minute to minute; the meta (collections, map, progression) gives reasons to keep going for weeks.','الحلقة الأساسية ممتعة دقيقة بدقيقة، والطبقة العليا (المجموعات والخريطة والتقدم) تعطي أسباباً للاستمرار أسابيع.','Core Loop macht minütlich Spaß; das Meta gibt wochenlang Gründe.'),
  PCL('Difficulty and level funnels','الصعوبة وقمع المراحل','Schwierigkeit und Level-Funnels','Use the level funnel to find walls. Smooth spikes with hints, extra moves or easier variants rather than removing challenge.','استخدم قمع المراحل لإيجاد الجدران. خفف القفزات بالتلميحات أو حركات إضافية أو نسخ أسهل بدلاً من إزالة التحدي.','Mit dem Level-Funnel Wände finden; mit Hinweisen und Extrazügen glätten.'),
  PCL('Economy and fair monetization','الاقتصاد وتحقيق الدخل العادل','Ökonomie und faire Monetarisierung','Balance earning and spending so free players progress, payers save time, and nobody feels tricked. Rewarded ads should feel like a gift.','وازن الكسب والإنفاق ليتقدم اللاعبون المجانيون ويوفر الدافعون الوقت ولا يشعر أحد بالخداع. إعلان المكافأة يجب أن يبدو كهدية.','Verdienen und Ausgeben ausbalancieren; Rewarded Ads wie ein Geschenk.'),
  PCL('LiveOps cadence','إيقاع العمليات الحية','LiveOps-Takt','A weekly event, a monthly content drop and seasonal moments keep the game alive. Plan them on a shared calendar.','فعالية أسبوعية ومحتوى شهري ولحظات موسمية تُبقي اللعبة حية. خطط لها في تقويم مشترك.','Wöchentliches Event, monatlicher Content, saisonale Momente.')]},
 {id:'pm7',ic:'ops',t:PS('Launch and release management','إدارة الإطلاق والإصدارات','Launch- und Release-Management'),l:[
  PCL('Release train','قطار الإصدارات','Release-Train','A fixed rhythm (every 2 weeks) with a code freeze, QA and store submission. Features that miss the train wait for the next one.','إيقاع ثابت (كل أسبوعين) مع تجميد الكود والاختبار والتقديم للمتجر. الميزات التي تفوت القطار تنتظر التالي.','Fester Rhythmus (alle 2 Wochen) mit Code-Freeze, QA, Einreichung.'),
  PCL('Checklists and QA','قوائم التحقق والاختبار','Checklisten und QA','Use the Operations checklist for every build: ads, consent, privacy, devices, Arabic text, store screenshots.','استخدم قائمة التحقق في العمليات لكل إصدار: الإعلانات والموافقة والخصوصية والأجهزة والنص العربي ولقطات المتجر.','Ops-Checkliste für jeden Build nutzen.'),
  PCL('Staged rollout','الطرح التدريجي','Gestaffelter Rollout','Phased release plus feature flags: 10% first, watch crash-free users and ratings for 48 hours, then continue.','إطلاق مرحلي مع مفاتيح الميزات: ١٠٪ أولاً، راقب الاستقرار والتقييم ٤٨ ساعة ثم أكمل.','Phased Release plus Flags: erst 10%, 48 Stunden beobachten.'),
  PCL('Launch communication','التواصل عند الإطلاق','Launch-Kommunikation','Release notes, social posts, In-App Event and a featuring request, all ready before submission.','ملاحظات الإصدار ومنشورات التواصل والفعالية داخل التطبيق وطلب الإبراز، كلها جاهزة قبل التقديم.','Release Notes, Posts, In-App-Event, Featuring-Anfrage vorab bereit.'),
  PCL('Post-launch review','مراجعة ما بعد الإطلاق','Post-Launch-Review','After two weeks compare the goal with the result, write what you learned, and decide: iterate, scale or roll back.','بعد أسبوعين قارن الهدف بالنتيجة ودوّن ما تعلمته وقرر: تحسين أو توسيع أو تراجع.','Nach zwei Wochen Ziel vs. Ergebnis, Lernen festhalten, entscheiden.')]}];


/* ---------- shared learning views (used by Products and Steam) ---------- */
function lStrat(L){return `<div class="grid g2">${L.map((x,i)=>`<div class="card tip-card"><div class="spread"><span class="tc">${i+1}</span></div><h4>${esc(tx(x.n))}</h4><p>${esc(tx(x.h))}</p><div class="exb"><span>${tr('Start with','ابدأ بـ','Start mit')}</span><div>${esc(tx(x.s))}</div></div></div>`).join('')}</div>`}
function lTips(L,CATS,key){
 const P=pmS(),done=P.tips,f=S.tab[key+'c']||'all',list=L.map((x,i)=>({x,i,id:key+i})).filter(o=>f==='all'||o.x[0]===f),dn=L.filter((x,i)=>done[key+i]).length;
 return `<div class="spread"><div class="chips">${['all',...Object.keys(CATS)].map(k=>`<button class="chip" data-pmset="tab.${key}c" data-v="${k}" aria-pressed="${f===k}">${k==='all'?t('all'):esc(mkT(CATS[k]))}</button>`).join('')}</div><span class="mono" style="color:var(--good)">${dn}/${L.length} ${tr('applied','مطبّقة','umgesetzt')}</span></div>
 <div class="grid g2" style="margin-top:12px">${list.map(o=>`<div class="card tip-card ${done[o.id]?'done':''}"><div class="spread"><span class="tc">${esc(mkT(CATS[o.x[0]]))}</span><button class="btn sm ${done[o.id]?'cy':''}" data-pmtip="${o.id}">${done[o.id]?'✓ '+tr('Applied','مطبّقة','Umgesetzt'):tr('Mark applied','علّمها مطبّقة','Als umgesetzt')}</button></div><p style="margin:8px 0 0">${esc(tr(o.x[1],o.x[2],o.x[3]))}</p></div>`).join('')}</div>`}
function lCourses(CS,key){
 const P=pmS(),prog=P.course,tot=sum(CS.map(c=>c.l.length)),dn=sum(CS.map(c=>Object.keys(prog[c.id]||{}).length));
 const c=CS.find(x=>x.id===S.tab[key])||CS[0],cd=prog[c.id]||{};
 return `<div class="spread"><p class="muted" style="margin:0">${tr('Short lessons you can apply this week. Mark each one done.','دروس قصيرة يمكنك تطبيقها هذا الأسبوع. علّم كل درس عند إنجازه.','Kurze Lektionen zum Anwenden. Jede als erledigt markieren.')}</p><span class="mono" style="color:var(--good)">${dn}/${tot} ${t('done_l')}</span></div>
 <div class="grid" style="grid-template-columns:minmax(0,300px) minmax(0,1fr);align-items:start;margin-top:12px" id="${key}-grid">
 <div class="card" style="padding:8px"><div class="nav">${CS.map(x=>{const n2=Object.keys(prog[x.id]||{}).length;return `<button data-pmset="tab.${key}" data-v="${x.id}" ${x.id===c.id?'aria-current="page"':''}>${icon(x.ic)}<span style="flex:1;min-width:0">${esc(tx(x.t))}</span><span class="mono small" style="color:${n2===x.l.length?'var(--good)':'var(--ink3)'}">${n2}/${x.l.length}</span></button>`}).join('')}</div></div>
 <div class="card"><h3>${esc(tx(c.t))}</h3><div class="meter" style="margin-bottom:14px"><i style="width:${Object.keys(cd).length/c.l.length*100}%;background:var(--good)"></i></div>
 <div class="grid">${c.l.map((ls,i)=>`<div class="lesson ${cd[i]?'done':''}"><div class="ln">${i+1}</div><div style="flex:1;min-width:0"><div class="muted small">${t('lesson')} ${i+1}</div><h4>${esc(tx(ls.t))}</h4><p>${esc(tx(ls.b))}</p>${ls.code?`<div class="codebox"><button class="btn sm" data-copytxt="${esc(ls.code)}">${t('copy')}</button><pre dir="ltr"><code>${esc(ls.code)}</code></pre></div>`:''}<button class="btn sm ${cd[i]?'cy':''}" data-pmlesson="${c.id}:${i}">${cd[i]?'✓ '+t('done_l'):t('mark_done')}</button></div></div>`).join('')}</div></div></div>
 <style>@media(max-width:900px){body:not(.pdfmode) #${key}-grid{grid-template-columns:minmax(0,1fr)!important}}.app[data-layout=mobile] #${key}-grid{grid-template-columns:minmax(0,1fr)!important}</style>`}
function lStories(L){return `<div class="grid g2">${L.map(x=>`<div class="card tip-card"><div class="spread"><span class="tc">${esc(x.y)}</span></div><h4>${esc(x.n)} · ${esc(tx(x.t))}</h4><p>${esc(tx(x.b))}</p><div class="exb"><span>${tr('Lesson','الدرس','Lektion')}</span><div>${esc(tx(x.l))}</div></div></div>`).join('')}</div>${mkNote(tr('Figures are as publicly reported by the companies or press; treat them as directional.','الأرقام كما أعلنتها الشركات أو الصحافة؛ اعتبرها استرشادية.','Zahlen wie von Firmen oder Presse berichtet; als Richtwerte verstehen.'))}`}
function lGloss(L,CATS,key){const f=S.tab[key+'c']||'all',q=(S.tab[key+'q']||'').toLowerCase(),list=L.filter(x=>(f==='all'||x[1]===f)&&(!q||(x[0]+' '+x[2]+' '+x[3]).toLowerCase().includes(q)));
 return `<div class="row"><input class="inp" data-pmq="${key}q" value="${esc(S.tab[key+'q']||'')}" placeholder="${esc(t('search'))}" style="max-width:320px"><span class="muted small mono">${list.length}/${L.length}</span></div>
 <div class="chips">${['all',...Object.keys(CATS)].map(k=>`<button class="chip" data-pmset="tab.${key}c" data-v="${k}" aria-pressed="${f===k}">${k==='all'?t('all'):esc(mkT(CATS[k]))}</button>`).join('')}</div>
 <div class="card"><div class="gloss">${list.map(x=>`<div class="gl"><dt dir="ltr">${esc(x[0])} <span class="pill paused" style="font-size:10px;padding:1px 6px">${esc(mkT(CATS[x[1]]))}</span></dt><dd>${esc(tr(x[2],x[3],x[4]))}</dd></div>`).join('')}</div></div>`}

/* ---------- Products view ---------- */
function vProduct(){
 pmS();if(CLOUD)mkLoad();Object.keys(MK_LTV).forEach(k=>delete MK_LTV[k]);
 let tb=tab('product','pboard');if(!PM_TABS.includes(tb))tb='pboard';
 const grp=Object.keys(PM_GROUPS).find(g=>PM_GROUPS[g].includes(tb));
 const body={pboard:pBoard,proad:pRoad,pprio:pPrio,pdisc:pDisc,pspec:pSpec,pexp:pExp,pmet:pMet,pcalc:pCalc,pstrat:()=>lStrat(PM_STRATS),ptips:()=>lTips(PM_TIPS,PT_CATS,'pmtip'),pcourse:()=>lCourses(PM_COURSES,'pmcrs'),pstory:()=>lStories(PM_STORIES),pgloss:()=>lGloss(PG,PT_CATS,'pmgl')}[tb];
 let html;try{html=body()}catch(e){console.error(e);html=`<div class="banner">${esc(e.message)}</div>`}
 return `<div class="tg" style="margin-bottom:10px">${Object.keys(PM_GROUPS).map(g=>`<button data-pmset="tab.product" data-v="${PM_GROUPS[g][0]}" aria-pressed="${g===grp}">${mkT(PM_GN[g])}</button>`).join('')}</div>
 <div class="tabs" role="tablist">${PM_GROUPS[grp].map(k=>`<button role="tab" aria-selected="${tb===k}" data-tab="product:${k}">${t('t_'+k)}</button>`).join('')}</div>`+html;
}

/* ---------- Products events ---------- */
function pmPath(path,val){const parts=path.split('.');let o;if(parts[0]==='tab'){o=S.tab;parts.shift()}else o=pmS();for(let i=0;i<parts.length-1;i++)o=o[parts[i]]=o[parts[i]]&&typeof o[parts[i]]==='object'?o[parts[i]]:{};o[parts[parts.length-1]]=val}
document.addEventListener('click',e=>{
 const s=e.target.closest('button[data-pmset],a[data-pmset]');if(s){pmPath(s.dataset.pmset,s.dataset.v);render();return}
 const tp=e.target.closest('[data-pmtip]');if(tp){const P=pmS();if(P.tips[tp.dataset.pmtip])delete P.tips[tp.dataset.pmtip];else P.tips[tp.dataset.pmtip]=1;render();return}
 const ls=e.target.closest('[data-pmlesson]');if(ls){const P=pmS(),[c,i]=ls.dataset.pmlesson.split(':');P.course[c]=P.course[c]||{};if(P.course[c][i])delete P.course[c][i];else P.course[c][i]=1;render();return}
 const mv=e.target.closest('[data-pmmove]');if(mv){const[id,d]=mv.dataset.pmmove.split(':'),x=pmS().road.find(y=>y.id===id);if(x){const i=PM_COLS.findIndex(c=>c[0]===x.col);x.col=PM_COLS[clamp(i+ +d,0,PM_COLS.length-1)][0]}render();return}
 const b=e.target.closest('[data-pm]');if(!b)return;const P=pmS(),id=b.dataset.id;
 switch(b.dataset.pm){
  case 'gate':pmGate(id);break;
  case 'gate-go':P.stage[id]=b.dataset.v;$('#modal-root').innerHTML='';toast(tr('Stage updated','تم تحديث المرحلة','Phase aktualisiert'));render();break;
  case 'road-add':pmRoadForm();break;
  case 'road-edit':pmRoadForm(P.road.find(x=>x.id===id));break;
  case 'road-del':confirmBox(t('del')+'?',()=>{P.road=P.road.filter(x=>x.id!==id);render()});break;
  case 'road-spec':pmPrdNew(P.road.find(x=>x.id===id));break;
  case 'fb-add':modal(tr('Add feedback','أضف ملاحظة','Feedback hinzufügen'),[{k:'t',l:tr('What players said or did','ما قاله اللاعبون أو فعلوه','Was Spieler sagten oder taten'),req:1,full:1},{k:'g',l:t('game'),type:'select',opts:gameOpts(),v:S.tab.pmg&&gById(S.tab.pmg)?S.tab.pmg:S.games[0]?.id},{k:'src',l:tr('Source','المصدر','Quelle'),type:'select',v:'playtest',opts:[['review',tr('App Store review','مراجعة المتجر','App-Store-Review')],['playtest',tr('Playtest','اختبار لعب','Playtest')],['social',tr('Social / community','التواصل / المجتمع','Social / Community')],['support',tr('Support email','بريد الدعم','Support-E-Mail')],['data',tr('Data insight','ملاحظة من البيانات','Daten-Erkenntnis')],['team',tr('Team idea','فكرة الفريق','Team-Idee')]]},{k:'n',l:tr('How many times','كم مرة','Wie oft'),type:'number',v:1}],d=>P.fb.unshift({id:uid(),g:d.g,src:d.src,t:d.t.slice(0,300),n:Math.max(1,+d.n||1),at:iso(new Date())}));break;
  case 'fb-plus':{const x=P.fb.find(y=>y.id===id);if(x)x.n=(x.n||1)+1;render();break}
  case 'fb-del':P.fb=P.fb.filter(x=>x.id!==id);render();break;
  case 'fb-road':{const x=P.fb.find(y=>y.id===id);if(x){P.road.push({id:uid(),g:x.g,t:x.t.slice(0,80),type:'feature',col:'later',r:Math.max(100,(x.n||1)*100),i:1,c:.5,e:2,mo:'could',ka:'performance',due:''});toast(tr('Added to roadmap · Later','أُضيفت لخارطة الطريق · لاحقاً','Zur Roadmap · Später'))}render();break}
  case 'rv-fb':P.fb.unshift({id:uid(),g:b.dataset.g,src:'review',t:b.dataset.v,n:1,at:iso(new Date())});render();break;
  case 'opp-add':modal(tr('New outcome','نتيجة جديدة','Neues Ergebnis'),[{k:'out',l:tr('Outcome (a number to move)','النتيجة (رقم نحركه)','Ergebnis (eine Zahl)'),req:1,full:1,v:tr('Raise D7 from 12% to 15%','رفع D7 من ١٢٪ إلى ١٥٪','D7 von 12% auf 15%')}],d=>P.opp.push({id:uid(),out:d.out.slice(0,140),items:[]}));break;
  case 'opp-del':P.opp=P.opp.filter(o=>o.id!==id);render();break;
  case 'opp-prob':{const o=P.opp.find(x=>x.id===id);if(o)modal(tr('Player problem','مشكلة اللاعب','Spielerproblem'),[{k:'p',l:tr('Problem','المشكلة','Problem'),req:1,full:1}],d=>o.items.push({p:d.p.slice(0,160),ideas:[]}));break}
  case 'opp-idea':{const o=P.opp.find(x=>x.id===id);if(o&&o.items.length)modal(tr('Idea','فكرة','Idee'),[{k:'i',l:tr('For problem','للمشكلة','Für Problem'),type:'select',opts:o.items.map((it,i)=>[String(i),cut(it.p,50)]),v:'0'},{k:'t',l:tr('Idea','الفكرة','Idee'),req:1,full:1}],d=>{const it=o.items[+d.i];if(it)(it.ideas=it.ideas||[]).push(d.t.slice(0,120))});else toast(tr('Add a problem first','أضف مشكلة أولاً','Zuerst ein Problem anlegen'));break}
  case 'prd-add':pmPrdNew();break;
  case 'prd-del':confirmBox(t('del')+'?',()=>{P.prd=P.prd.filter(x=>x.id!==id);S.tab.pmspec='';render()});break;
  case 'exp-add':modal(tr('New experiment','تجربة جديدة','Neues Experiment'),[{k:'name',l:tr('Name','الاسم','Name'),req:1,v:tr('Shorter tutorial','تعليم أقصر','Kürzeres Tutorial')},{k:'g',l:t('game'),type:'select',opts:gameOpts(),v:S.games[0]?.id},{k:'metric',l:tr('Decision metric','مقياس القرار','Entscheidungskennzahl'),v:'D1'},{k:'base',l:tr('Baseline %','الأساس ٪','Basis %'),type:'number',v:35,step:'0.1'},{k:'mde',l:tr('Smallest lift (% relative)','أقل تحسّن (٪ نسبي)','Kleinster Lift (% relativ)'),type:'number',v:5,step:'0.5'},{k:'dau',l:tr('New players / day','لاعبون جدد / يوم','Neue Spieler / Tag'),type:'number',v:500}],d=>P.exp.unshift({id:uid(),...d,share:100,st:'plan',hyp:'',an:0,ac:0,bn:0,bc:0}));break;
  case 'exp-del':P.exp=P.exp.filter(x=>x.id!==id);render();break;
  case 'calc-reset':delete P.calc[id];render();break;
 }
});
let pmRT=0;const pmRender=()=>{clearTimeout(pmRT);pmRT=setTimeout(render,0)};
