const dDiff=(a,b)=>Math.round((new Date(a+'T12:00:00')-new Date(b+'T12:00:00'))/864e5);
const addD=(d,n)=>iso(new Date(new Date(d+'T12:00:00').getTime()+n*864e5));

/* ---------- which games are on Steam, and their numbers ---------- */
function stTitles(){
 const s=stS(),srv=new Map((CONN&&!CONN.err?CONN.games||[]:[]).map(g=>[g.id,g]));
 return S.games.filter(g=>s.titles[g.id]||srv.get(g.id)?.steamAppId||S.daily.some(r=>r.g===g.id&&(r.stCcu!=null||r.stUnits!=null)));
}
const ST_DEMO={};
function stRows(gid,days=60){
 const since=mkSince(days),real=S.daily.filter(r=>r.g===gid&&r.d>=since&&(r.stUnits!=null||r.stCcu!=null));
 if(real.length||CLOUD)return real.sort((a,b)=>a.d.localeCompare(b.d));
 if(!ST_DEMO[gid]){const R=mkRand(gid.length*131+7),o=[];let pos=380+Math.round(R()*200),neg=40+Math.round(R()*30);for(let i=90;i>=1;i--){const d=iso(new Date(Date.now()-i*864e5)),w=new Date(d).getDay(),sale=i<=20&&i>=14,u=Math.round((18+R()*14)*(w===5||w===6?1.4:1)*(sale?3.2:1)*(1-i/300));pos+=Math.round(u*.09);neg+=Math.round(u*.012);o.push({g:gid,d,stUnits:u,stGross:+(u*(sale?11.99:14.99)).toFixed(2),stNet:+(u*(sale?11.99:14.99)*.88).toFixed(2),stRet:Math.round(u*(.05+R()*.05)),stCcu:Math.round(60+u*2.2+R()*40),stPos:pos,stNeg:neg})}ST_DEMO[gid]=o}
 return ST_DEMO[gid].filter(r=>r.d>=since);
}
function stScore(pos,neg){const n=pos+neg;if(n<10)return {n,p:n?pos/n:0,l:tr('Too few reviews','مراجعات قليلة جداً','Zu wenige Reviews'),c:'var(--ink3)'};const p=pos/n;
 const L=p>=.95&&n>=500?['Overwhelmingly Positive','إيجابية ساحقة','Äußerst positiv','#66c0f4']:p>=.8&&n>=50?['Very Positive','إيجابية جداً','Sehr positiv','#66c0f4']:p>=.8?['Positive','إيجابية','Positiv','#66c0f4']:p>=.7?['Mostly Positive','إيجابية غالباً','Größtenteils positiv','#66c0f4']:p>=.4?['Mixed','مختلطة','Ausgeglichen','#b9a074']:p>=.2?['Mostly Negative','سلبية غالباً','Größtenteils negativ','#a34c25']:n>=500?['Overwhelmingly Negative','سلبية ساحقة','Äußerst negativ','#a34c25']:n>=50?['Very Negative','سلبية جداً','Sehr negativ','#a34c25']:['Negative','سلبية','Negativ','#a34c25'];
 return {n,p,l:tr(L[0],L[1],L[2]),c:L[3]}}
function stDemoBanner(){return !CLOUD?`<div class="banner" style="margin-bottom:12px">${icon('steam','style="width:16px;height:16px;flex:none"')}<span>${tr('Example data. On your website these numbers come from Steam (players, reviews) and the Steamworks sales API.','بيانات توضيحية. في موقعك تأتي هذه الأرقام من ستيم (اللاعبون والمراجعات) وواجهة مبيعات Steamworks.','Beispieldaten. Auf Ihrer Website kommen diese Zahlen von Steam und der Steamworks-Sales-API.')}</span></div>`:''}

function sDash(){
 const L=stTitles();
 if(!L.length)return `<div class="empty"><b>${tr('No Steam games yet','لا توجد ألعاب على ستيم بعد','Noch keine Steam-Spiele')}</b><p class="muted">${tr('Mark which games are on Steam (or coming), then add their Steam App IDs in Connect.','حدد الألعاب الموجودة (أو القادمة) على ستيم ثم أضف معرّفات تطبيقاتها في الربط.','Markieren Sie Ihre Steam-Spiele und tragen Sie unter Verbinden die App-IDs ein.')}</p><div class="row" style="justify-content:center;margin-top:10px"><button class="btn pri" data-pmset="tab.steam" data-v="sconn">${t('t_sconn')}</button></div></div>`;
 const cards=L.map(g=>{const R=stRows(g.id,30),last=R[R.length-1]||{},sc=stScore(+last.stPos||0,+last.stNeg||0),u=sum(R.map(r=>+r.stUnits||0)),net=sum(R.map(r=>+r.stNet||0)),gross=sum(R.map(r=>+r.stGross||0)),ret=sum(R.map(r=>+r.stRet||0)),peak=Math.max(0,...R.map(r=>+r.stCcu||0));
  const w=(stS().wish[g.id]||[]),wNet=sum(w.map(x=>x[1]-x[2]-x[3]-x[4]));
  return `<div class="card"><div class="spread"><b>${esc(tx(g.name))}</b><span class="mono small" style="color:${sc.c}">${sc.n?esc(sc.l)+' · '+pct(sc.p,0):'—'}</span></div>
  <div class="kpis" style="margin-top:10px">${kpiTile(tr('Players now','اللاعبون الآن','Spieler jetzt'),num(+last.stCcu||0),null,'#66c0f4')}${kpiTile(tr('Peak (30d)','الذروة (٣٠ي)','Peak (30T)'),num(peak),null,'#27e2ff')}${kpiTile(tr('Units (30d)','النسخ (٣٠ي)','Einheiten (30T)'),num(u),null,'#3dffa9')}${kpiTile(tr('Net sales (30d)','صافي المبيعات (٣٠ي)','Nettoumsatz (30T)'),money(net),null,'#ff2bd6')}${kpiTile(tr('Refund rate','نسبة الاسترداد','Rückerstattungsquote'),u+ret?pct(ret/(u+ret),1):'—',null,ret/(u+ret||1)>.12?'#ff4f6e':'#ffb22e')}${kpiTile(tr('You receive (est.)','ما تستلمه (تقدير)','Sie erhalten (geschätzt)'),money(net*.7),null,'#9b7bff')}</div>
  ${R.length>3?chartPh({labels:R.map(r=>r.d),fmt:v=>num(v),series:[{name:tr('Units','النسخ','Einheiten'),color:'#3dffa9',values:R.map(r=>+r.stUnits||0)},{name:tr('Players now','اللاعبون الآن','Spieler jetzt'),color:'#66c0f4',values:R.map(r=>+r.stCcu||0),area:false}]},200):''}
  <p class="muted small" style="margin:8px 0 0">${tr('Gross','الإجمالي','Brutto')} ${money(gross)} · ${tr('wishlists (imported)','قوائم الرغبات (مستوردة)','Wunschlisten (importiert)')} ${w.length?num(wNet):'—'} · ${tr('“You receive” = net × 70% (Steam keeps 30% up to $10M per game).','«ما تستلمه» = الصافي × ٧٠٪ (يأخذ ستيم ٣٠٪ حتى ١٠ ملايين دولار لكل لعبة).','„Sie erhalten“ = Netto × 70% (Steam behält 30% bis 10 Mio. $ pro Spiel).')}</p></div>`}).join('');
 return stDemoBanner()+`<div class="grid g2">${cards}</div>`;
}

