function sLaunch(){
 const s=stS(),L=stTitles().length?stTitles():S.games,gid=L.some(g=>g.id===S.tab.stg)?S.tab.stg:L[0]?.id;if(!gid)return `<div class="empty"><b>${tr('No games','لا ألعاب','Keine Spiele')}</b></div>`;
 const rel=s.rel[gid]||addD(iso(new Date()),180),ck=s.chk[gid]||{},today=iso(new Date());
 const fests=ST_EVENTS.filter(e=>e[3]==='next'&&e[1]<rel&&e[2]>=today);
 const rows=ST_STEPS.map(([k,off,txt])=>{const d=addD(rel,off),left=dDiff(d,today),done=!!ck[k];return {k,d,left,done,txt}}).sort((a,b)=>a.d.localeCompare(b.d));
 const n=rows.filter(r=>r.done).length;
 return `<div class="card"><div class="spread" style="flex-wrap:wrap;gap:10px"><div class="row" style="gap:8px">${mkGamePick(gid,'tab.stg').replace('data-mkin','data-pmset')}<label class="small">${tr('Release date','تاريخ الإطلاق','Release-Datum')} <input class="inp mono" type="date" value="${rel}" data-stin="rel.${gid}" style="width:auto"></label></div><span class="mono" style="color:var(--good)">${n}/${rows.length} ${t('done_l')}</span></div>
 <div class="meter" style="margin:12px 0"><i style="width:${n/rows.length*100}%;background:var(--good)"></i></div>
 ${rows.map(r=>`<div class="lesson ${r.done?'done':''}" style="margin-bottom:8px"><div class="ln" style="${!r.done&&r.left<0?'background:var(--red);color:#fff':''}">${r.done?'✓':r.left<0?'!':Math.max(0,r.left)}</div><div style="flex:1;min-width:0"><div class="spread"><span class="mono small muted">${esc(r.d)} · ${r.left>=0?tr(`in ${r.left} days`,`بعد ${r.left} يوماً`,`in ${r.left} Tagen`):tr(`${-r.left} days ago`,`قبل ${-r.left} يوماً`,`vor ${-r.left} Tagen`)}</span><input type="checkbox" data-stchk="${gid}:${r.k}" ${r.done?'checked':''} aria-label="done"></div><p style="margin:4px 0 0">${esc(mkT(r.txt))}</p></div></div>`).join('')}
 ${fests.length?`<div class="exb" style="margin-top:6px"><span>Next Fest</span><div>${fests.map(f=>`${esc(f[0])}: <span class="mono">${f[1]} → ${f[2]}</span>`).join('<br>')}</div></div>`:''}</div>`;
}

