/* ---------- Steam view ---------- */
function vSteam(){
 stS();if(CLOUD&&!CONN&&!CONN_BUSY)setTimeout(connLoad,0);
 let tb=tab('steam','sdash');if(!ST_TABS.includes(tb))tb='sdash';
 const grp=Object.keys(ST_GROUPS).find(g=>ST_GROUPS[g].includes(tb));
 const body={sdash:sDash,slaunch:sLaunch,spage:sPage,swish:sWish,sprice:sPrice,sevents:sEvents,stech:sTech,sconn:sConn,scalc:sCalc,sstrat:()=>lStrat(ST_STRATS),stips:()=>lTips(ST_TIPS,STP_CATS,'sttip'),scourse:()=>lCourses(ST_COURSES,'stcrs'),sstory:()=>lStories(ST_STORIES),sgloss:()=>lGloss(STG,STP_CATS,'stgl')}[tb];
 let html;try{html=body()}catch(e){console.error(e);html=`<div class="banner">${esc(e.message)}</div>`}
 return `<div class="tg" style="margin-bottom:10px">${Object.keys(ST_GROUPS).map(g=>`<button data-pmset="tab.steam" data-v="${ST_GROUPS[g][0]}" aria-pressed="${g===grp}">${mkT(PM_GN[g])}</button>`).join('')}</div>
 <div class="tabs" role="tablist">${ST_GROUPS[grp].map(k=>`<button role="tab" aria-selected="${tb===k}" data-tab="steam:${k}">${t('t_'+k)}</button>`).join('')}</div>`+html;
}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-st]');if(!b)return;const s=stS(),id=b.dataset.id;
 switch(b.dataset.st){
  case 'title':if(s.titles[id])delete s.titles[id];else s.titles[id]=1;render();break;
  case 'price':s.price[id]=+b.dataset.v;render();break;
  case 'disc-add':{const rel=s.rel[id]||iso(new Date()),has=s.disc.some(d=>d.g===id&&d.kind==='launch');s.disc.push(has?{id:uid(),g:id,kind:'custom',start:addD(rel,40),end:addD(rel,46),pct:20}:{id:uid(),g:id,kind:'launch',start:rel,end:addD(rel,6),pct:10});render();break}
  case 'disc-del':s.disc=s.disc.filter(d=>d.id!==id);render();break;
  case 'wish-clear':confirmBox(t('del')+'?',()=>{delete s.wish[id];render()});break;
 }
});
document.addEventListener('change',e=>{
 const el=e.target,s=stS();
 if(el.dataset.stin){const[k,g]=el.dataset.stin.split('.');s[k]=s[k]||{};s[k][g]=el.dataset.num?(+el.value||0):el.value.slice(0,k==='desc'?600:400);pmRender();return}
 if(el.dataset.stchk){const[g,k]=el.dataset.stchk.split(':');s.chk[g]=s.chk[g]||{};if(el.checked)s.chk[g][k]=1;else delete s.chk[g][k];pmRender();return}
 if(el.dataset.stfest){if(el.checked)s.fest[el.dataset.stfest]=1;else delete s.fest[el.dataset.stfest];save();return}
 if(el.dataset.stdisc){const[id,k]=el.dataset.stdisc.split(':'),d=s.disc.find(x=>x.id===id);if(d)d[k]=k==='pct'?clamp(+el.value||0,0,95):el.value;pmRender();return}
 if(el.id==='st-wish-file'&&el.files[0]){const g=el.dataset.g;el.files[0].text().then(txt=>{try{s.wish[g]=stParseWish(txt);toast(tr(`${s.wish[g].length} days imported`,`تم استيراد ${s.wish[g].length} يوماً`,`${s.wish[g].length} Tage importiert`));render()}catch(err){toast(err.message)}})}
});

/* ================= SERVER MODE (Netlify + Firebase): login, team, workspace sync, live data ================= */
const CLOUD=!!window.KN_CLOUD;
const C={st:'boot',me:null,fb:null,msg:'',ok:'',fails:0,lockUntil:0,mfaHint:'',busy:false,email:'',team:null,teamBusy:false,totp:null,leaving:false,uid:null,showPw:false};
const SHARED=['games','campaigns','costs','cc','keywords','aso','tasks','releases','incidents','checks','tipsDone','audit','path','bp','fc','calc','rep','feeRate','mk','pm'];
const WS={on:false,first:false,last:{},pending:{},t:null,unsub:null,deferRender:false,err:''};
const canEdit=()=>!CLOUD||!!(C.me&&C.me.role!=='viewer');
const isOwner=()=>!!(C.me&&C.me.role==='owner');
const roleLabel=r=>({owner:tr('Owner','المالك','Inhaber'),editor:tr('Editor','محرر','Bearbeiter'),viewer:tr('Viewer','مشاهد','Betrachter')}[r]||r);

/** Calls the Netlify API with the signed-in user's Firebase token. */
async function api(method,path,body){
 let tok='';try{tok=CLOUD&&C.fb?await C.fb.token():''}catch(e){}
 let r;try{r=await fetch(path,{method,cache:'no-store',credentials:'same-origin',headers:{...(tok?{authorization:'Bearer '+tok}:{}),...(body!==undefined?{'content-type':'application/json'}:{})},body:body!==undefined?JSON.stringify(body):undefined})}
 catch(e){return {ok:false,s:0,j:{error:tr('Network error. Check your connection.','خطأ في الشبكة. تحقق من اتصالك.','Netzwerkfehler. Verbindung prüfen.')}}}
 let j={};try{j=await r.json()}catch(e){}
 if(r.status===401&&C.st==='app'&&/revoked|signed_out/.test(j.code||''))cloudSignOut('expired');
 return {ok:r.ok,s:r.status,j};
}
const hqFetch=async(url,opt={})=>{const tok=CLOUD&&C.fb?await C.fb.token():'';return fetch(url,{credentials:'same-origin',cache:'no-store',...opt,headers:{'content-type':'application/json',...(tok?{authorization:'Bearer '+tok}:{}),...(opt.headers||{})}})};

/* ---------- live data ---------- */
async function liveLoad(){
 if(!CLOUD||C.st!=='app')return;
 const r=await api('GET','/api/live?days=150');
 if(r.ok)applyLive(r.j);else S.live={err:r.j.error||('HTTP '+r.s)};
 render();
}
let LIVE_LAST=null;
function applyLive(L){
 LIVE_LAST=L;
 const withData=new Set(L.rows.map(r=>r.g));
 L.games.forEach(m=>{let g=gById(m.id);if(!g){g={id:m.id,name:{en:m.name||m.id,ar:m.name||m.id},genre:{en:'',ar:''},levels:0,status:'live',version:'',platform:'iOS',color:'#27e2ff',p:null,funnel:null};S.games.push(g)}
  if(withData.has(m.id)){if(!g.p)g.p={};if(L.funnels[m.id])g.funnel=L.funnels[m.id]}});
 if(withData.size){const base=S.sample?[]:S.daily.filter(r=>!withData.has(r.g));S.daily=base.concat(L.rows).sort((a,b)=>a.d.localeCompare(b.d));if(S.sample)S.games.forEach(g=>{if(!withData.has(g.id)){g.funnel=null;if(g.p&&g.p.inst)g.p=null}});S.sample=false}
 S.liveMed=L.mediation||[];S.live={at:L.status?.finishedAt||null,status:L.status,games:withData.size};
}
const SYNC={run:false,done:0,total:0,days:3};
async function liveSync(btn,days){
 if(SYNC.run)return;SYNC.run=true;SYNC.done=0;SYNC.total=0;SYNC.days=days||SYNC.days||3;render();
 try{
  for(let i=0;i<60;i++){
   const r=await api('POST','/api/sync',{days:SYNC.days});
   if(!r.ok)throw new Error(r.j.error||('HTTP '+r.s));
   if(r.j.busy){await new Promise(x=>setTimeout(x,2500));continue}
   SYNC.total=r.j.total||SYNC.total;SYNC.done=SYNC.total-(r.j.remaining||0);render();
   if(r.j.done||!r.j.remaining)break;
  }
  toast(t('synced'));
 }catch(e){toast(t('sync_err')+': '+(e.message||e))}
 SYNC.run=false;CONN=null;MKD.st='idle';await liveLoad();
}
const CONN_LAB={firebase_ga4:'Firebase / GA4',admob:'AdMob',app_store_connect:'App Store Connect',revenuecat:'RevenueCat',crashlytics:'Crashlytics',ratings:'App Store ratings'};
function liveCard(){
 if(!CLOUD)return '';
 const L=S.live||{},st=L.status||CONN?.sync?.status,C2=st?.connectors||{};
 const pct=SYNC.total?Math.round(SYNC.done/SYNC.total*100):0;
 return `<div class="card"><h3>${t('live_sources')}<span class="r row" style="gap:6px">${canEdit()?`<select class="inp" id="sync-days" style="width:auto;padding:6px 8px" aria-label="${tr('Days','الأيام','Tage')}">${[[3,tr('Last 3 days','آخر ٣ أيام','Letzte 3 Tage')],[30,tr('Last 30 days','آخر ٣٠ يوماً','Letzte 30 Tage')],[90,tr('Last 90 days (first time)','آخر ٩٠ يوماً (أول مرة)','Letzte 90 Tage (erstes Mal)')]].map(([v,l])=>`<option value="${v}" ${SYNC.days===v?'selected':''}>${l}</option>`).join('')}</select><button class="btn sm pri" data-act="live-sync" ${SYNC.run?'disabled':''}>${SYNC.run?tr('Syncing…','جارٍ المزامنة…','Synchronisiere…'):t('sync_now')}</button>`:''}</span></h3>
 ${SYNC.run?`<div class="sync-bar" role="progressbar" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><i style="width:${Math.max(4,pct)}%"></i></div><p class="muted small" dir="ltr" style="margin:6px 0 10px">${SYNC.done} / ${SYNC.total||'…'}</p>`:''}
 ${L.err?`<div class="banner" style="border-color:rgba(255,79,110,.4);color:#ffb3c1">${esc(L.err)}</div>`:''}
 <p class="muted small" style="margin:0 0 10px">${t('last_sync')}: <b class="mono">${st?.finishedAt?new Date(st.finishedAt).toLocaleString(LOC()):'—'}</b>${st?.window?` · <span dir="ltr">${esc(st.window.start)} → ${esc(st.window.end)}</span>`:''} · ${tr('Automatic every night at 06:00 Riyadh time.','تلقائياً كل ليلة الساعة ٦:٠٠ صباحاً بتوقيت الرياض.','Automatisch jede Nacht um 06:00 Uhr Riad-Zeit.')}</p>
 <div class="grid g3 ins">${Object.keys(CONN_LAB).map(k=>{const c=C2[k]||{state:'off'};const col=c.state==='ok'?'var(--good)':c.state==='error'?'var(--red)':'var(--ink3)';return `<div class="it"><span class="sv" style="background:${col}"></span><div style="min-width:0"><b>${esc(CONN_LAB[k])}</b><p>${c.state==='ok'?`✓ ${c.rows} ${t('rows')}`:c.state==='error'?esc(c.error):esc(c.note||t('not_set'))}</p></div></div>`}).join('')}</div>
 <div class="row" style="margin-top:12px"><button class="btn sm" data-ac="csv">${t('dl_csv')}</button></div></div>`;
}

/* ---------- connections: 3 steps + discover ---------- */
let CONN=null,CONN_BUSY=false,GEDIT=null,CONN_P8=null;const CONN_MSG={};
