let DISC=null,DISC_BUSY=false;const DISC_PICK=new Set(),DISC_NEW=new Set();
const DISC_FIELDS=[['ascAppleId','Apple ID'],['ga4PropertyId','GA4 property'],['ga4StreamId','GA4 stream'],['admobAppId','AdMob app'],['revenuecatProjectId','RevenueCat project'],['crashlyticsTable','Crashlytics table']];
const DISC_SRC=[['apple','App Store Connect'],['ga4','Firebase / GA4'],['admob','AdMob'],['firebase','Firebase · Crashlytics'],['revenuecat','RevenueCat']];
function discChanges(p){const cur=(GEDIT||[]).find(g=>g.id===p.id)||{};return DISC_FIELDS.filter(([k])=>k in p.values&&String(p.values[k]??'')!==String(cur[k]??'')&&!(k==='ga4StreamId'&&!p.values[k]&&!cur[k]))}
async function discRun(){
 if(!canEdit())return;DISC_BUSY=true;render();
 const r=await api('POST','/api/discover',{games:gamesForServer().map(g=>({id:g.id,name:g.name}))});
 if(r.ok){DISC=r.j;DISC_PICK.clear();DISC_NEW.clear();r.j.proposals.forEach(p=>{if(discChanges(p).length&&!Object.values(p.how).every(h=>h==='name'))DISC_PICK.add(p.id)})}
 else DISC={err:r.j.error||('HTTP '+r.s)};
 DISC_BUSY=false;render();
}
function discCard(){
 const ready=SVC.some(s=>CONN.services[s.id]?.connected);
 const head=`<div class="card disc"><h3>${icon('spark','style="width:16px;height:16px;color:var(--neon)"')} ${t('discover')}<span class="r">${canEdit()?`<button class="btn pri" data-discover="1" ${DISC_BUSY||!ready?'disabled':''}>${DISC_BUSY?t('discovering'):t('discover')}</button>`:''}</span></h3><p class="muted small" style="margin:-4px 0 12px;max-width:75ch">${t('discover_p')}</p>`;
 if(!DISC)return head+'</div>';
 if(DISC.err)return head+`<div class="banner" style="border-color:rgba(255,79,110,.4);color:#ffb3c1">${esc(DISC.err)}</div></div>`;
 const sm=DISC.summary||{};
 const chips=`<div class="chips" style="margin-bottom:12px">${DISC_SRC.map(([k,n])=>{const x=sm[k]||{};return `<span class="pill ${x.ok?'live':x.off?'paused':'bad'}" title="${esc(x.error||'')}">${x.ok?'✓':x.off?'–':'✕'} ${n}${x.ok?' · '+x.count:''}</span>`}).join('')}</div>${DISC_SRC.filter(([k])=>sm[k]&&!sm[k].ok&&!sm[k].off).map(([k,n])=>`<div class="small" style="color:var(--red);margin-bottom:6px">${n}: ${esc(sm[k].error)}</div>`).join('')}`;
 const via=h=>h==='bundle'?t('via_bundle'):h==='app-store-link'?t('via_link'):t('via_name');
 const rows=DISC.proposals.filter(p=>discChanges(p).length).map(p=>{const ch=discChanges(p);return `<tr><td><input type="checkbox" data-discpick="${esc(p.id)}" ${DISC_PICK.has(p.id)?'checked':''} aria-label="${esc(p.name)}"></td><td><b>${esc(p.name||p.id)}</b>${p.bundleId?`<div class="mono small muted">${esc(p.bundleId)}</div>`:''}</td><td>${ch.map(([k,l])=>`<div class="small"><span class="muted">${l}:</span> <span class="mono" style="color:var(--good)">${esc(p.values[k]||'—')}</span> <span class="pill ${p.how[k]==='name'?'soft':'paused'}" style="font-size:9.5px;padding:0 6px">${via(p.how[k]||'bundle')}</span></div>`).join('')}</td></tr>`}).join('');
 const none=DISC.proposals.filter(p=>!discChanges(p).length&&!Object.keys(p.values).length).map(p=>esc(p.name||p.id));
 const nw=(DISC.newApps||[]).length?`<h4 style="margin:16px 0 8px">${t('new_apps')}</h4><div class="chk">${DISC.newApps.map(a=>`<label><input type="checkbox" data-discnew="${esc(a.appleId)}" ${DISC_NEW.has(a.appleId)?'checked':''}><span>${esc(a.name)} <span class="mono small muted">${esc(a.bundleId)} · ${esc(a.appleId)}</span> — ${t('add_as_game')}</span></label>`).join('')}</div>`:'';
 const st=Object.entries(DISC.settings||{});
 return head+chips+(rows?`<div class="tbl-wrap"><table class="tbl"><tbody>${rows}</tbody></table></div>`:`<p class="small muted">${tr('Everything found is already saved.','كل ما وُجد محفوظ مسبقاً.','Alles Gefundene ist bereits gespeichert.')}</p>`)+(none.length?`<p class="small muted" style="margin-top:8px">${tr('Not found in your accounts yet','لم تُعثر عليها في حساباتك بعد','Noch nicht in Ihren Konten gefunden')}: ${none.join(' · ')}</p>`:'')+`${nw}${st.length?`<p class="small muted" style="margin-top:10px">${t('will_set')}: ${st.map(([k,v])=>`<span class="mono">${esc(CONN_LABEL[k]||k)} = ${esc(v)}</span>`).join(' · ')}</p>`:''}
 <div class="row" style="margin-top:12px"><button class="btn pri" data-discapply="1" ${DISC_PICK.size||DISC_NEW.size||st.length?'':'disabled'}>${t('apply_sel')}</button></div></div>`;
}
async function discApply(){
 const byId=Object.fromEntries(GEDIT.map(g=>[g.id,g]));
 DISC.proposals.forEach(p=>{if(!DISC_PICK.has(p.id)||!byId[p.id])return;const v={...p.values};if(v.ascAppleId)v.appStoreId=v.ascAppleId;Object.assign(byId[p.id],v)});
 const COLS2=['#27e2ff','#ff2bd6','#c4ff3d','#ffb22e','#9b7bff','#2effa8'];
 (DISC.newApps||[]).forEach((a,i)=>{if(!DISC_NEW.has(a.appleId))return;let id=(a.name||'game').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,30)||'game';while(GEDIT.some(g=>g.id===id)||gById(id))id+='-2';
  GEDIT.push({id,name:a.name,ascAppleId:a.appleId,appStoreId:a.appleId});
  S.games.push({id,name:{en:a.name,ar:a.name},genre:{en:'',ar:''},levels:0,status:'live',version:'',platform:'iOS',color:COLS2[i%COLS2.length],p:null,funnel:null})});
 const r=await api('PUT','/api/games',{games:GEDIT.filter(g=>g.id).map(g=>({...g,appStoreId:g.ascAppleId||g.appStoreId})),settings:DISC.settings||{}});
 if(!r.ok)return toast(r.j.error||'Error');
 DISC=null;toast(t('applied'));CONN=null;render();connLoad();
}

/* ---------- keep live games only: remove template games and everything tied to them ---------- */
function gameClass(){
 const data=new Set(S.sample?[]:S.daily.map(r=>r.g));
 const srv=new Map((CONN&&!CONN.err?CONN.games||[]:[]).map(g=>[g.id,g]));
 const linked=id=>{const g=srv.get(id);return !!g&&(DISC_FIELDS.some(([k])=>g[k])||!!g.appStoreId)};
 const ex=seedState(),sig=new Set([...ex.tasks.map(x=>'t|'+x.g+'|'+x.tt),...ex.releases.map(x=>'r|'+x.g+'|'+x.ver+'|'+x.notes)]);
 const mine=id=>S.tasks.some(x=>x.g===id&&!sig.has('t|'+x.g+'|'+x.tt))||S.releases.some(x=>x.g===id&&!sig.has('r|'+x.g+'|'+x.ver+'|'+x.notes));
 return S.games.map(g=>({g,data:data.has(g.id),linked:linked(g.id),own:mine(g.id)}));
}
async function cleanOpen(){
 if(!canEdit())return;
 if(CLOUD&&!CONN){toast(t('loading'));const r=await api('GET','/api/integrations');if(r.ok){CONN=r.j;GEDIT=gamesForServer()}}
 const L=gameClass(),pick=new Set(L.filter(x=>!x.data&&!x.linked&&!x.own).map(x=>x.g.id));
 const root=$('#modal-root');
 const badge=x=>'<span style="flex:none">'+(x.data?`<span class="pill live" style="font-size:10.5px">${tr('Live data','بيانات حية','Live-Daten')}</span>`:x.linked?`<span class="pill soft" style="font-size:10.5px">${tr('Linked, no data yet','مربوطة، بلا بيانات بعد','Verknüpft, noch keine Daten')}</span>`:`<span class="pill paused" style="font-size:10.5px">${tr('Template','نموذج','Vorlage')}</span>`)+'</span>';
 const draw=()=>{root.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="cl-h"><div class="box" style="width:min(560px,100%)">
  <h2 id="cl-h">${tr('Keep live games only','إبقاء الألعاب الحية فقط','Nur Live-Spiele behalten')}</h2>
  <p class="muted small" style="margin:0 0 12px">${tr('Ticked games are removed with their sample metrics, campaigns, keywords, tasks, releases and checklists. Games with live data, linked store/Firebase IDs or your own tasks are not ticked.','الألعاب المحددة تُحذف مع مؤشراتها التجريبية وحملاتها وكلماتها المفتاحية ومهامها وإصداراتها وقوائم التحقق. الألعاب ذات البيانات الحية أو المعرّفات المربوطة أو مهامك الخاصة لا تُحدد.','Markierte Spiele werden mit Beispielkennzahlen, Kampagnen, Keywords, Aufgaben, Releases und Checklisten entfernt. Spiele mit Live-Daten, verknüpften IDs oder eigenen Aufgaben sind nicht markiert.')}</p>
  ${!S.live?.games&&CLOUD?`<div class="banner" style="margin-bottom:10px">${tr('No live data has synced yet. Run Discover and Sync in Reports → Data first, so your real games are recognised.','لم تُزامن أي بيانات حية بعد. شغّل الاكتشاف والمزامنة في التقارير ← البيانات أولاً حتى تُعرف ألعابك الحقيقية.','Noch keine Live-Daten synchronisiert. Zuerst unter Berichte → Daten „Finden“ und „Sync“ ausführen.')}</div>`:''}
  <div class="row" style="gap:6px;margin-bottom:8px"><button class="btn sm" id="cl-tpl">${tr('Tick templates','حدد النماذج','Vorlagen markieren')}</button><button class="btn sm ghost" id="cl-none">${tr('Untick all','إلغاء التحديد','Alle abwählen')}</button></div>
  <div class="chk" style="max-height:46vh;overflow:auto;padding-inline-end:4px">${L.map(x=>`<label class="spread" style="gap:10px;padding:6px 0;border-bottom:1px solid var(--line);flex-wrap:nowrap"><span class="row" style="gap:10px;min-width:0"><input type="checkbox" data-clpick="${esc(x.g.id)}" ${pick.has(x.g.id)?'checked':''}><span style="min-width:0"><b>${esc(tx(x.g.name))}</b>${x.own?` <span class="muted small">· ${tr('has your tasks/releases','فيها مهامك/إصداراتك','hat Ihre Aufgaben/Releases')}</span>`:''}</span></span>${badge(x)}</label>`).join('')}</div>
  <label class="small" style="display:flex;align-items:flex-start;gap:8px;margin-top:12px"><input type="checkbox" id="cl-mkt" checked style="margin-top:3px;flex:none"><span>${tr('Also delete the example campaigns, keywords, tasks, releases and incidents of the games you keep. Anything you added yourself stays.','احذف أيضاً الحملات والكلمات المفتاحية والمهام والإصدارات والحوادث التجريبية للألعاب المتبقية. ما أضفته بنفسك يبقى.','Auch Beispielkampagnen, -Keywords, -Aufgaben, -Releases und -Vorfälle der behaltenen Spiele löschen. Eigene Einträge bleiben.')}</span></label>
  <div class="act"><button class="btn" data-mclose>${t('cancel')}</button><button class="btn pri" id="cl-go" ${pick.size?'':'disabled'} style="${pick.size?'background:var(--red);border-color:var(--red)':''}">${tr('Remove','احذف','Entfernen')} <span class="mono">${pick.size}</span> · ${tr('keep','أبقِ','behalten')} <span class="mono">${L.length-pick.size}</span></button></div></div></div>`;
  root.querySelectorAll('[data-clpick]').forEach(el=>el.onchange=()=>{el.checked?pick.add(el.dataset.clpick):pick.delete(el.dataset.clpick);draw()});
  $('#cl-tpl').onclick=()=>{pick.clear();L.filter(x=>!x.data&&!x.linked&&!x.own).forEach(x=>pick.add(x.g.id));draw()};
  $('#cl-none').onclick=()=>{pick.clear();draw()};
  root.querySelector('.modal').onclick=e=>{if(e.target.classList.contains('modal')||e.target.hasAttribute('data-mclose'))root.innerHTML=''};
  $('#cl-go').onclick=()=>{if(!pick.size)return;const mkt=$('#cl-mkt').checked;const ids=[...pick];
   confirmBox(tr(`Remove ${ids.length} games? This cannot be undone (save a backup first if unsure).`,`حذف ${ids.length} لعبة؟ لا يمكن التراجع (احفظ نسخة احتياطية أولاً إن لم تكن متأكداً).`,`${ids.length} Spiele entfernen? Nicht rückgängig zu machen.`),()=>removeGames(ids,mkt))};
 };
 draw();
}
async function removeGames(ids,mkt){
 const gone=new Set(ids);
 S.games=S.games.filter(g=>!gone.has(g.id));
 ['daily','campaigns','keywords','tasks','releases','incidents'].forEach(k=>{if(Array.isArray(S[k]))S[k]=S[k].filter(x=>!gone.has(x.g))});
 if(S.cc&&Array.isArray(S.cc.items))S.cc.items=S.cc.items.filter(x=>!gone.has(x.g));
 ['checks','audit'].forEach(k=>{if(S[k])gone.forEach(id=>delete S[k][id])});
 if(mkt){const ex=seedState(),SIG={campaigns:x=>[x.g,x.ch,x.budget,x.spend],keywords:x=>[x.g,x.k,x.loc],tasks:x=>[x.g,x.tt],releases:x=>[x.g,x.ver,x.notes],incidents:x=>[x.g,x.tt]};
  Object.entries(SIG).forEach(([k,f])=>{const seen=new Set((ex[k]||[]).map(x=>JSON.stringify(f(x))));if(Array.isArray(S[k]))S[k]=S[k].filter(x=>!seen.has(JSON.stringify(f(x))))});}
 if(S.sample&&!S.games.length)S.sample=false;
 if(S.rep&&Array.isArray(S.rep.games))S.rep.games=S.rep.games.filter(id=>!gone.has(id));
 if(gone.has(S.gf))S.gf='all';
 if(S.tab&&gone.has(S.tab.taskg))S.tab.taskg='all';
 if(String(S.view||'').startsWith('game:')&&gone.has(S.view.slice(5)))S.view='games';
 if(LIVE_LAST){LIVE_LAST.games=(LIVE_LAST.games||[]).filter(g=>!gone.has(g.id));LIVE_LAST.rows=(LIVE_LAST.rows||[]).filter(r=>!gone.has(r.g))}
 S.gamesV=REAL_GAMES_V;save();render();
 // Also drop them from the server's game list, otherwise the next live load would add them back.
 if(CLOUD&&CONN&&!CONN.err&&(CONN.games||[]).some(g=>gone.has(g.id))){
  const r=await api('PUT','/api/games',{games:(CONN.games||[]).filter(g=>!gone.has(g.id)).map(g=>({...g,appStoreId:g.ascAppleId||g.appStoreId}))});
  if(!r.ok)toast(r.j.error||'Error');CONN=null;GEDIT=null;
 }
 toast(tr(`${ids.length} games removed`,`حُذفت ${ids.length} لعبة`,`${ids.length} Spiele entfernt`));
}

/* ---------- workspace sync (shared with your team through Firestore) ---------- */
function wsStart(){
 if(WS.on||!C.fb)return;WS.on=true;WS.first=false;WS.last={};WS.pending={};
 WS.unsub=C.fb.ws.subscribe((docs,initial)=>wsApply(docs,initial),e=>{WS.err=String(e?.code||e?.message||e);toast(tr('Team sync paused','توقفت مزامنة الفريق','Team-Sync pausiert')+': '+WS.err)});
}
function wsStop(){try{WS.unsub&&WS.unsub()}catch(e){}WS.on=false;WS.first=false;clearTimeout(WS.t)}
function wsApply(docs,initial){
 let changed=false,liveRegames=false;const have=new Set();
 docs.forEach(d=>{have.add(d.id);if(!SHARED.includes(d.id)||typeof d.json!=='string')return;if(d.json===WS.last[d.id]||WS.pending[d.id]!==undefined)return;
  try{S[d.id]=wsClean(d.id,JSON.parse(d.json));WS.last[d.id]=d.json;changed=true;if(d.id==='games'&&LIVE_LAST)liveRegames=true}catch(e){}});
 if(liveRegames)applyLive(LIVE_LAST);
 if(initial&&!WS.first){WS.first=true;
  if(canEdit())SHARED.forEach(k=>{if(!have.has(k)&&S[k]!==undefined)WS.pending[k]=JSON.stringify(S[k])});
  if(changed)S.gamesV=REAL_GAMES_V;
  wsFlush();
 }
 if(changed){if(busyTyping())WS.deferRender=true;else render()}
}
/** Defence in depth for data written by teammates: ids and colours end up inside HTML attributes. */
function wsClean(key,v){
 const walk=o=>{if(Array.isArray(o))return o.map(walk);if(!o||typeof o!=='object')return o;const r={};
  for(const [k,x] of Object.entries(o)){
   if((k==='id'||k==='g')&&typeof x==='string')r[k]=x.replace(/[^\w:-]/g,'').slice(0,80);
   else if(k==='color'&&typeof x==='string')r[k]=/^#[0-9a-f]{3,8}$/i.test(x)?x:'#27e2ff';
   else r[k]=walk(x)}
  return r};
 const out=walk(v);
 if(key==='games'&&Array.isArray(out))return out.filter(g=>g&&/^[a-z0-9-]+$/.test(g.id||'')&&g.name);
 return out;
}
