function wsTrack(){
 if(!CLOUD||!WS.on||!WS.first||!canEdit())return;
 SHARED.forEach(k=>{if(S[k]===undefined)return;const j=JSON.stringify(S[k]);if(j!==WS.last[k]&&j!==WS.pending[k])WS.pending[k]=j});
 if(Object.keys(WS.pending).length){clearTimeout(WS.t);WS.t=setTimeout(wsFlush,1200)}
}
async function wsFlush(){
 clearTimeout(WS.t);const P=WS.pending;WS.pending={};
 for(const [k,j] of Object.entries(P)){
  if(j.length>890000){toast(tr('Too much data in','بيانات كثيرة جداً في','Zu viele Daten in')+' '+k);continue}
  const prev=WS.last[k];WS.last[k]=j;
  try{await C.fb.ws.write(k,j);WS.err=''}catch(e){WS.last[k]=prev;if(WS.pending[k]===undefined)WS.pending[k]=j;WS.err=String(e?.code||e?.message||e);toast(tr('Could not save to the team workspace','تعذّر الحفظ في مساحة الفريق','Speichern im Team-Bereich fehlgeschlagen')+': '+WS.err)}
 }
}

/* ---------- authentication screens ---------- */
const PW_COMMON=/password|passw0rd|qwerty|123456|111111|abc123|letmein|welcome|iloveyou|admin|kinzhal|nest|monkey|dragon/i;
function pwCheck(p,email){
 const name=String(email||'').split('@')[0].toLowerCase();
 const rules=[
  [p.length>=12,tr('At least 12 characters','١٢ حرفاً على الأقل','Mindestens 12 Zeichen')],
  [/[a-z]/.test(p)&&/[A-Z]/.test(p),tr('Upper- and lower-case letters','حروف كبيرة وصغيرة','Groß- und Kleinbuchstaben')],
  [/\d/.test(p),tr('A number','رقم','Eine Zahl')],
  [/[^A-Za-z0-9]/.test(p),tr('A symbol (!@#…)','رمز (!@#…)','Ein Sonderzeichen (!@#…)')],
  [!!p&&!(name.length>=3&&p.toLowerCase().includes(name))&&!PW_COMMON.test(p)&&!/(.)\1\1/.test(p),tr('Not your email name, a common word or repeats','ليست اسم بريدك أو كلمة شائعة أو تكراراً','Nicht Ihr E-Mail-Name, kein gängiges Wort, keine Wiederholungen')]];
 const pool=(/[a-z]/.test(p)?26:0)+(/[A-Z]/.test(p)?26:0)+(/\d/.test(p)?10:0)+(/[^A-Za-z0-9]/.test(p)?33:0);
 let bits=p.length*Math.log2(Math.max(pool,1));if(PW_COMMON.test(p))bits*=.5;if(/(.)\1\1/.test(p))bits*=.8;
 const ok=rules.every(r=>r[0]);const score=!p?0:bits<40?1:bits<60?2:bits<80||!ok?3:4;
 return {rules,ok,score,bits:Math.round(bits)};
}
async function pwPwned(p){
 try{const h=await crypto.subtle.digest('SHA-1',new TextEncoder().encode(p));const hex=[...new Uint8Array(h)].map(b=>b.toString(16).padStart(2,'0')).join('').toUpperCase();
  const r=await fetch('https://api.pwnedpasswords.com/range/'+hex.slice(0,5),{headers:{'Add-Padding':'true'}});if(!r.ok)return null;
  const line=(await r.text()).split('\n').find(l=>l.startsWith(hex.slice(5)));return line?+line.split(':')[1]||0:0}catch(e){return null}
}
function pwMeter(id,email){
 const p=$('#'+id)?.value||'',c=pwCheck(p,email),lab=[tr('Too weak','ضعيفة جداً','Zu schwach'),tr('Weak','ضعيفة','Schwach'),tr('Fair','مقبولة','Mittel'),tr('Good','جيدة','Gut'),tr('Strong','قوية','Stark')][c.score];
 const col=['var(--ink3)','var(--red)','var(--amber)','#ffd23e','var(--good)'][c.score];
 return `<div class="pwm" id="${id}-m"><div class="pwbar"><i style="width:${c.score*25}%;background:${col}"></i></div><div class="small" style="color:${col}">${p?lab:''}</div><ul class="pwrules">${c.rules.map(r=>`<li class="${r[0]?'ok':''}">${r[0]?'✓':'•'} ${r[1]}</li>`).join('')}</ul></div>`;
}
const authErr=e=>{const c=e?.code||'';
 if(/invalid-credential|wrong-password|user-not-found|invalid-email|invalid-login/.test(c))return tr('Email or password is wrong.','البريد أو كلمة المرور غير صحيحة.','E-Mail oder Passwort ist falsch.');
 if(/too-many-requests/.test(c))return tr('Too many attempts. Wait a few minutes or reset your password.','محاولات كثيرة. انتظر بضع دقائق أو أعد تعيين كلمة المرور.','Zu viele Versuche. Warten Sie einige Minuten oder setzen Sie das Passwort zurück.');
 if(/email-already-in-use/.test(c))return tr('An account with this email already exists. Sign in instead.','يوجد حساب بهذا البريد. سجّل الدخول بدلاً من ذلك.','Für diese E-Mail gibt es bereits ein Konto. Bitte anmelden.');
 if(/weak-password|password-does-not-meet-requirements/.test(c))return tr('This password does not meet the password rules.','كلمة المرور لا تحقق القواعد.','Das Passwort erfüllt die Regeln nicht.');
 if(/invalid-verification-code|invalid-otp|totp/.test(c))return tr('That code is not right. Check the time on your phone and try again.','الرمز غير صحيح. تحقق من وقت جوالك وحاول مجدداً.','Der Code stimmt nicht. Prüfen Sie die Uhrzeit Ihres Handys.');
 if(/configuration-not-found/.test(c))return tr('Sign-in is not switched on in Firebase yet: Firebase console → Authentication → Get started → Sign-in method → Email/Password → Enable.','تسجيل الدخول غير مفعّل في Firebase بعد: Firebase ← Authentication ← Get started ← Sign-in method ← Email/Password ← Enable.','Die Anmeldung ist in Firebase noch nicht aktiviert: Firebase-Konsole → Authentication → Get started → Sign-in method → E-Mail/Passwort → Aktivieren.');
 if(/operation-not-allowed|admin-restricted|unsupported/.test(c))return tr('This sign-in option is turned off in Firebase. See the setup guide.','هذا الخيار معطّل في Firebase. راجع دليل الإعداد.','Diese Option ist in Firebase deaktiviert. Siehe Einrichtungsanleitung.');
 if(/requires-recent-login/.test(c))return tr('For your safety, sign in again first.','لأمانك، سجّل الدخول مجدداً أولاً.','Bitte zur Sicherheit erneut anmelden.');
 if(/network/.test(c))return tr('Network error. Check your connection.','خطأ في الشبكة. تحقق من اتصالك.','Netzwerkfehler. Verbindung prüfen.');
 return e?.message||String(e)};
