let idleOn=false,lastAct=Date.now(),idleI=0;
function idleStart(){
 lastAct=Date.now();
 if(!idleOn){idleOn=true;['pointerdown','keydown','wheel','touchstart','scroll'].forEach(ev=>document.addEventListener(ev,()=>{lastAct=Date.now()},{passive:true,capture:true}))}
 clearInterval(idleI);idleI=setInterval(()=>{const lim=(C.me?.team?.idleMinutes||30)*60000;if(C.st==='app'&&Date.now()-lastAct>lim)cloudSignOut('idle')},20000);
}
async function authSubmit(id){
 C.msg='';C.ok='';const email=($('#a-email')?.value||'').trim().toLowerCase(),pw=$('#a-pw')?.value||'';if(email)C.email=email;
 const bad=m=>{C.msg=m;C.busy=false;renderAuth()};
 if(id==='f-signin'){
  if(C.lockUntil>Date.now())return;
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||!pw)return bad(tr('Enter your email and password.','أدخل بريدك وكلمة المرور.','E-Mail und Passwort eingeben.'));
  C.busy=true;renderAuth();
  try{const r=await C.fb.signIn(email,pw,!!$('#a-remember')?.checked);C.busy=false;C.fails=0;if(r.mfa){C.mfaHint=r.hint;C.st='mfa';renderAuth()}}
  catch(e){C.fails++;if(C.fails>=3)C.lockUntil=Date.now()+Math.min(300,15*2**(C.fails-3))*1000;bad(authErr(e))}
  return;
 }
 if(id==='f-signup'){
  const pw2=$('#a-pw2')?.value||'',c=pwCheck(pw,email);
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return bad(tr('Enter a valid email.','أدخل بريداً صحيحاً.','Gültige E-Mail eingeben.'));
  if(!c.ok)return bad(tr('Choose a stronger password (see the rules).','اختر كلمة مرور أقوى (راجع القواعد).','Wählen Sie ein stärkeres Passwort (siehe Regeln).'));
  if(pw!==pw2)return bad(tr('The passwords do not match.','كلمتا المرور غير متطابقتين.','Die Passwörter stimmen nicht überein.'));
  C.busy=true;renderAuth();
  const n=await pwPwned(pw);
  if(n>0)return bad(tr(`This password appeared in ${n.toLocaleString()} data breaches. Choose another one.`,`ظهرت كلمة المرور هذه في ${n.toLocaleString()} تسريباً. اختر غيرها.`,`Dieses Passwort kam in ${n.toLocaleString()} Datenlecks vor. Bitte ein anderes wählen.`));
  try{await C.fb.signUp(email,pw);C.busy=false;C.st='verify';renderAuth()}catch(e){bad(authErr(e))}
  return;
 }
 if(id==='f-forgot'){
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return bad(tr('Enter a valid email.','أدخل بريداً صحيحاً.','Gültige E-Mail eingeben.'));
  C.busy=true;renderAuth();try{await C.fb.reset(email)}catch(e){if(/too-many|network/.test(e?.code||''))return bad(authErr(e))}
  C.busy=false;C.st='signin';C.ok=tr('If an account exists for this email, a reset link is on its way.','إن وُجد حساب بهذا البريد فسيصله رابط إعادة التعيين.','Falls ein Konto existiert, ist ein Link unterwegs.');renderAuth();return;
 }
 if(id==='f-mfa'){
  const code=($('#a-code')?.value||'').replace(/\D/g,'');if(code.length!==6)return bad(tr('Enter the 6-digit code.','أدخل الرمز المكوّن من ٦ أرقام.','6-stelligen Code eingeben.'));
  C.busy=true;renderAuth();try{await C.fb.mfaSignIn(code);C.busy=false}catch(e){C.fails++;bad(authErr(e))}return;
 }
 if(id==='f-totp'){
  const code=($('#a-tcode')?.value||'').replace(/\D/g,'');if(code.length!==6)return bad(tr('Enter the 6-digit code.','أدخل الرمز المكوّن من ٦ أرقام.','6-stelligen Code eingeben.'));
  C.busy=true;C.st==='app'?render():renderAuth();
  try{await C.fb.totpFinish(code);C.totp=null;C.busy=false;cloudSignOut('mfa')}catch(e){C.busy=false;if(C.st==='app'){toast(authErr(e));render()}else bad(authErr(e))}
  return;
 }
}
