 C.busy=true;C.st==='app'?render():renderAuth();
 try{C.totp=await C.fb.totpStart()}catch(e){const m=authErr(e);if(C.st==='app')toast(m);else C.msg=m;if(/requires-recent-login/.test(e?.code||'')&&C.st==='app'){C.reauthFor='totp'}}
