 if(a==='verified'){C.busy=true;renderAuth();let ok=false;try{ok=await C.fb.reload()}catch(e){}C.busy=false;if(ok)return cloudUser(C.fb.user());C.msg=tr('Not confirmed yet. Open the link in the email first.','لم يتم التأكيد بعد. افتح الرابط في البريد أولاً.','Noch nicht bestätigt. Öffnen Sie zuerst den Link.');return renderAuth()}
 if(a==='resend'){if(Date.now()<(C.resendAt||0))return;C.busy=true;C.msg='';C.ok='';renderAuth();try{await C.fb.sendVerify();C.ok=tr('Sent. Check your inbox and spam folder — it can take a few minutes.','تم الإرسال. تحقق من البريد الوارد والمزعج — قد يستغرق بضع دقائق.','Gesendet. Posteingang und Spam prüfen — kann einige Minuten dauern.')}catch(e){C.msg=/too-many-requests/.test(e?.code||'')?tr('Firebase limits how often the email can be sent. The earlier email is still valid — check your inbox and spam folder, or try again in about an hour.','يحدّ Firebase من تكرار إرسال الرسالة. الرسالة السابقة ما زالت صالحة — تحقق من البريد الوارد والمزعج أو حاول بعد نحو ساعة.','Firebase begrenzt, wie oft die E-Mail gesendet wird. Die frühere E-Mail gilt weiter — Posteingang und Spam prüfen oder in etwa einer Stunde erneut versuchen.'):authErr(e)}C.busy=false;C.resendAt=Date.now()+60000;renderAuth();setTimeout(()=>{if(C.st==='verify')renderAuth()},60500);return}
 if(a==='signout')return cloudSignOut('out');
 if(a==='signout-all')return confirmBox(tr('Sign out on every device, including this one?','تسجيل الخروج من كل الأجهزة بما فيها هذا؟','Auf allen Geräten abmelden, auch auf diesem?'),()=>cloudSignOut('all',true));
 if(a==='totp-start')return totpStart();
 if(a==='mfa-remove')return confirmBox(tr('Turn off 2-step verification for your account?','إيقاف التحقق بخطوتين لحسابك؟','Zwei-Schritt-Bestätigung für Ihr Konto ausschalten?'),async()=>{try{await C.fb.mfaRemove(v);toast(tr('2-step verification removed','تم إيقاف التحقق بخطوتين','Zwei-Schritt-Bestätigung entfernt'));cloudSignOut('out')}catch(e){toast(authErr(e))}});
 if(a==='team-reload'){C.team=null;return teamLoad()}
 if(a==='inv-cancel'){const r=await api('DELETE','/api/team/invites/'+encodeURIComponent(v));if(!r.ok)toast(r.j.error);return teamLoad()}
 if(a==='m-remove')return confirmBox(tr('Remove this member? They are signed out at once.','إزالة هذا العضو؟ سيتم تسجيل خروجه فوراً.','Mitglied entfernen? Es wird sofort abgemeldet.'),async()=>{const r=await api('DELETE','/api/team/members/'+encodeURIComponent(v));if(!r.ok)toast(r.j.error);teamLoad()});
 if(a==='m-pause'){const r=await api('PATCH','/api/team/members/'+encodeURIComponent(v),{disabled:b.dataset.on==='1'});if(!r.ok)toast(r.j.error);return teamLoad()}
