/* ================= PDF EXPORT (any page, or the whole platform) ================= */
let PDF_RUN=null;
const PDF_LIBS=['https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js','https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js'];
const VIEW_TABS={marketing:['campaigns','calc','aso','cal','play','ex','ai'],profit:['strat','protips','sim','addesign','offers','ideas'],finance:['pnl','bp','cc','csamp','fc','unit'],ops:['pipe','rel','chk','inc'],reports:['builder'],product:PM_TABS,steam:ST_TABS,academy:['path','langs','db','deploy','apis','courses','stories','tools','gloss']};
function pageTitle(){const v=S.view.startsWith('game:')?'games':S.view;let n=S.view.startsWith('game:')?t('nav_games')+' · '+gName(S.view.slice(5)):t('nav_'+v);const tb=VIEW_TABS[v]&&tab(v,VIEW_TABS[v][0]);if(tb&&!S.view.startsWith('game:'))n+=' · '+t('t_'+tb);if(v==='academy'&&tb==='courses'){const c=COURSES.find(x=>x.id===S.tab.course)||COURSES[0];n+=' · '+tx(c.t)}return n}
function pdfUnits(wrap){
 const units=[...wrap.querySelectorAll('.card')].filter(c=>!c.parentElement.closest('.card'));
 [...wrap.children].forEach(ch=>{if(!ch.classList.contains('card')&&!ch.querySelector('.card'))units.push(ch)});
 return units;
}
/** Push cards (whole grid rows) that would be cut by a page edge onto the next page. */
function pdfPaginate(wrap,pageH){
 const touched=[],wt=()=>wrap.getBoundingClientRect().top,units=pdfUnits(wrap);
 const order=units.map(u=>[u,u.getBoundingClientRect().top]).sort((a,b)=>a[1]-b[1]).map(x=>x[0]);
 for(const u of order){
  const r=u.getBoundingClientRect(),top=r.top-wt(),h=r.height;if(h<2||h>pageH*0.92)continue;
  const end=(Math.floor(top/pageH)+1)*pageH;if(top+h<=end-2)continue;
  const delta=end-top+14;
  const mates=units.filter(m=>m.parentElement===u.parentElement&&Math.abs(m.getBoundingClientRect().top-r.top)<3);
  mates.forEach(m=>{touched.push([m,m.style.marginTop]);m.style.marginTop=(parseFloat(getComputedStyle(m).marginTop)||0)+delta+'px'});
 }
 return ()=>touched.reverse().forEach(([m,v])=>m.style.marginTop=v);
}
// A4 portrait, in points: content is laid out 900 px wide and scaled into the printable area.
const A4={w:595.28,h:841.89,mx:24,mt:24,mb:36};
const pdfScale=W=>(A4.w-2*A4.mx)/W;               // pt per px
const pdfPageH=W=>Math.floor((A4.h-A4.mt-A4.mb)/pdfScale(W)); // px of content per page
async function pdfCapture(title){
 const wrap=$('#main .wrap');
 const hd=document.createElement('div');hd.className='pdf-head';
 hd.innerHTML=`<div><div class="eyebrow">${esc(t('brand'))} · ${esc(t('brand2'))}</div><h1>${esc(title)}</h1></div><div class="muted small" dir="ltr">${esc(new Date().toLocaleString(LOC()))}</div>`;
 wrap.prepend(hd);
 drawCharts(wrap);await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
 const W=wrap.offsetWidth,pageH=pdfPageH(W);
 const undo=pdfPaginate(wrap,pageH);
 try{
  const H=wrap.scrollHeight,scale=Math.max(1,Math.min(2,1500/W,Math.sqrt(15e6/(W*Math.max(H,1)))));
  const canvas=await html2canvas(wrap,{scale,backgroundColor:'#07060c',useCORS:true,logging:false,windowWidth:Math.max(1280,document.documentElement.clientWidth),width:W,height:H});
  return {canvas,pageH,W};
 }finally{undo();hd.remove()}
}
function pdfAddPages(pdf,cap,first){
 const {canvas,pageH,W}=cap,k=canvas.width/W,slice=Math.round(pageH*k),sc=pdfScale(W),cw=A4.w-2*A4.mx;
 for(let y=0,i=0;y<canvas.height-2;y+=slice,i++){
  const h=Math.min(slice,canvas.height-y);if(h<6&&i>0)break;
  const c=document.createElement('canvas');c.width=canvas.width;c.height=h;const cx=c.getContext('2d');cx.fillStyle='#07060c';cx.fillRect(0,0,c.width,h);cx.drawImage(canvas,0,y,c.width,h,0,0,c.width,h);
  if(!(first&&i===0))pdf.addPage('a4','portrait');
  pdf.setFillColor('#07060c');pdf.rect(0,0,A4.w,A4.h,'F');
  pdf.addImage(c.toDataURL('image/jpeg',.9),'JPEG',A4.mx,A4.mt,cw,h/k*sc);
  pdf.setDrawColor('#2a2440');pdf.setLineWidth(.6);pdf.line(A4.mx,A4.h-A4.mb+10,A4.w-A4.mx,A4.h-A4.mb+10);
  pdf.setFontSize(8);pdf.setTextColor('#8a82ad');
  pdf.text('KINZHAL NEST',A4.mx,A4.h-A4.mb+22);pdf.text(String(pdf.getNumberOfPages()),A4.w-A4.mx,A4.h-A4.mb+22,{align:'right'});
 }
}
function pdfProgress(msg,i,n){let el=$('#pdfprog');if(!el){el=document.createElement('div');el.id='pdfprog';document.body.appendChild(el)}
 el.innerHTML=`<div class="box"><b>${esc(msg)}</b>${n?`<div class="meter" style="margin:10px 0"><i style="width:${i/n*100}%"></i></div><div class="small muted mono" dir="ltr">${i} / ${n}</div>`:''}${PDF_RUN&&PDF_RUN.all?`<button class="btn sm" data-act="pdf-cancel" style="margin-top:10px">${t('cancel')}</button>`:''}</div>`}
async function exportPagePDF(all){
 if(PDF_RUN)return;PDF_RUN={all,cancel:false};
 const keep={view:S.view,tab:{...S.tab},layout:S.layout},scroll=$('#main').scrollTop;
 try{
  pdfProgress(t('pdf_prep'));
  for(const u of PDF_LIBS)await loadScript(u);
  await document.fonts?.ready;
  document.body.classList.add('pdfmode');
  S.layout='desktop';render();
  let pdf=null;const {jsPDF}=window.jspdf;
  const plan=all?pdfPlan():[{view:S.view,tab:{...S.tab}}];
  for(let i=0;i<plan.length;i++){
   if(PDF_RUN.cancel)throw new Error('cancelled');
   pdfProgress(all?t('pdf_all_prog'):t('exporting'),i,plan.length);
   S.view=plan[i].view;S.tab=plan[i].tab;render();await new Promise(r=>setTimeout(r,120));
   const cap=await pdfCapture(pageTitle());
   if(!pdf)pdf=new jsPDF({unit:'pt',format:'a4',orientation:'portrait',compress:true});
   pdfAddPages(pdf,cap,i===0);
  }
  pdfProgress(t('exporting'),plan.length,plan.length);
  const name=all?`kinzhal-nest-full-${iso(new Date())}.pdf`:`kinzhal-nest-${(keep.view.replace(':','-'))}${VIEW_TABS[keep.view]?'-'+tab(keep.view,VIEW_TABS[keep.view][0]):''}-${iso(new Date())}.pdf`;
  const blob=pdf.output('blob');
  document.body.classList.remove('pdfmode');$('#pdfprog')?.remove();
  S.view=keep.view;S.tab=keep.tab;S.layout=keep.layout;render();$('#main').scrollTop=scroll;
  await offerFile(name,blob,null);
 }catch(e){
  document.body.classList.remove('pdfmode');$('#pdfprog')?.remove();
  S.view=keep.view;S.tab=keep.tab;S.layout=keep.layout;render();$('#main').scrollTop=scroll;
  if(String(e.message||e)!=='cancelled')toast(tr('Could not build the PDF: ','تعذر إنشاء PDF: ','PDF konnte nicht erstellt werden: ')+(e.message||e));
 }finally{PDF_RUN=null}
}
function pdfPlan(){
 const P=[{view:'overview',tab:{}},{view:'games',tab:{}}];
 S.games.forEach(g=>P.push({view:'game:'+g.id,tab:{}}));
 P.push({view:'guide',tab:{}});
 for(const v of ['marketing','profit','finance'])VIEW_TABS[v].filter(k=>k!=='ai').forEach(k=>P.push({view:v,tab:{[v]:k}}));
 P.push({view:'kpis',tab:{}});
 VIEW_TABS.ops.forEach(k=>P.push({view:'ops',tab:{ops:k}}));
 P.push({view:'reports',tab:{reports:'builder'}});
 VIEW_TABS.academy.filter(k=>k!=='courses').forEach(k=>P.push({view:'academy',tab:{academy:k}}));
 COURSES.forEach(c=>P.push({view:'academy',tab:{academy:'courses',course:c.id}}));
 return P;
}
