/** Any app pages, re-rendered as light A4 document pages. plan = [{view, tab}] */
function docPages(plan){
 const keep={view:S.view,tab:{...S.tab}};let html='';
 const VIEW_FN={account:vAccount,product:vProduct,steam:vSteam,overview:vOverview,games:vGames,guide:vGuide,profit:vProfit,academy:vAcademy,marketing:vMarketing,finance:vFinance,kpis:vKpis,ops:vOps,reports:vReports};
 try{
  for(const it of plan){S.view=it.view;S.tab={...it.tab};
   const body=S.view.startsWith('game:')?vGame(S.view.slice(5)):(VIEW_FN[S.view]||vOverview)();
   html+=`<div class="pg" dir="${S.lang==='ar'?'rtl':'ltr'}"><div class="pg-h"><h1>${esc(pageTitle())}</h1><small>${t('brand')} · ${new Date().toLocaleDateString(LOC())}</small></div><div class="wrap">${body}</div></div>`}
 }finally{S.view=keep.view;S.tab=keep.tab}
 return html;
}

let PRINT_PAL=null;
/** Shrink any table that is wider than its box until it fits: smaller text, then wrapping, then fixed columns. */
function fitTables(root){
 root.querySelectorAll('table').forEach(tb=>{
  tb.style.width='100%';
  const box=tb.closest('.tbl-wrap,figure,.card,.gp,.rp,section,.pg,.doc')||root;
  const room=()=>{const cs=getComputedStyle(box);return box.clientWidth-(parseFloat(cs.paddingLeft)||0)-(parseFloat(cs.paddingRight)||0)};
  for(const c of ['fit1','fit2','fit3']){if(tb.offsetWidth<=room()+1)break;tb.classList.add(c)}
 });
}
async function printDocument(html,title,{onBlocked}={}){
 let root=$('#print-root');if(root)root.remove();
 root=document.createElement('div');root.id='print-root';root.setAttribute('aria-hidden','true');root.innerHTML=html;document.body.appendChild(root);
 drawCharts(root);fitTables(root);
 await document.fonts?.ready;await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
 const oldTitle=document.title;document.title=title.replace(/[\\/:*?"<>|]+/g,'-');
 let started=false;const on=()=>{started=true};window.addEventListener('beforeprint',on,{once:true});
 const done=()=>{document.title=oldTitle;const r=$('#print-root');if(r)r.remove()};
 window.addEventListener('afterprint',()=>setTimeout(done,300),{once:true});
 try{window.print()}catch(e){}
 await new Promise(r=>setTimeout(r,400));
 window.removeEventListener('beforeprint',on);
 if(!started){document.title=oldTitle;onBlocked?onBlocked(root):printBlocked(root,title)}
}
/** Printing is blocked inside some embedded previews: offer the same document as a file that opens and prints by itself. */
