/* ================= exports ================= */
function loadScript(src){return new Promise((res,rej)=>{if($(`script[src="${src}"]`))return res();const s=document.createElement('script');s.src=src;s.onload=res;s.onerror=()=>rej(new Error((tr('Could not load library: ','تعذر تحميل مكتبة: ','Bibliothek konnte nicht geladen werden: '))+src.split('/').pop()));document.head.appendChild(s)})}
async function capUse(n){try{return window.claude?.use?await window.claude.use(n):null}catch(e){return null}}
const getDownloads=()=>capUse('downloads');
async function offerFile(filename,data,noteEl){
 if(window.HQ_STANDALONE||window.KN_CLOUD){const b=data instanceof Blob?data:new Blob([data]);const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=filename;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1500);toast(t('exported'));return}
 const dl=await getDownloads();if(!dl){if(noteEl)noteEl.textContent=t('dl_unavail');toast(t('dl_unavail'));return}
 try{await dl.save({filename,data});toast(t('exported'))}catch(e){const m=e?.code==='declined'?t('declined'):(e?.message||'Error');if(noteEl)noteEl.textContent=m;toast(m)}
}
async function exportPDF(){
 const btn=$('#pdf-btn'),note=$('#exp-note'),el=$('#report');if(!el)return;
 btn.disabled=true;note.textContent=t('exporting');
 try{
  await loadScript('https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js');
  await loadScript('https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js');
  await document.fonts?.ready;
  const pageH=Math.round(el.offsetWidth*297/210),blocks=$$('.rp-block',el),added=[];
  blocks.forEach(b=>{const top=b.offsetTop,h=b.offsetHeight,pEnd=Math.ceil((top+1)/pageH)*pageH;if(top+h>pEnd&&h<pageH-80){const sp=document.createElement('div');sp.style.height=(pEnd-top+28)+'px';b.before(sp);added.push(sp)}});
  const bg=S.rep.theme==='light'?'#ffffff':'#0b0914';
  const canvas=await html2canvas(el,{scale:2,backgroundColor:bg,useCORS:true,logging:false,windowWidth:el.scrollWidth});
  added.forEach(s=>s.remove());
  const {jsPDF}=window.jspdf;const pdf=new jsPDF({unit:'pt',format:'a4',compress:true});const pw=pdf.internal.pageSize.getWidth(),ph=pdf.internal.pageSize.getHeight();
  const pxPerPage=Math.round(canvas.width*ph/pw);
  for(let y=0,i=0;y<canvas.height;y+=pxPerPage,i++){const c=document.createElement('canvas');c.width=canvas.width;c.height=Math.min(pxPerPage,canvas.height-y);const cx=c.getContext('2d');cx.fillStyle=bg;cx.fillRect(0,0,c.width,c.height);cx.drawImage(canvas,0,y,c.width,c.height,0,0,c.width,c.height);
   if(i)pdf.addPage();pdf.setFillColor(bg);pdf.rect(0,0,pw,ph,'F');pdf.addImage(c.toDataURL('image/jpeg',.92),'JPEG',0,0,pw,c.height*pw/c.width)}
  const blob=pdf.output('blob');note.textContent='';
  await offerFile(`game-report-${iso(new Date())}.pdf`,blob,note);
 }catch(e){note.textContent=(tr('Could not build the PDF: ','تعذر إنشاء PDF: ','PDF konnte nicht erstellt werden: '))+(e?.message||e)}
 finally{btn.disabled=false}
}
const CSV_COLS=['date','game','installs','paid_installs','dau','sessions_per_dau','session_min','impressions','ad_revenue','iap_revenue','ua_spend','d1','d7','d30','crash_free','rating'];
const CSV_KEYS=['d','g','inst','paid','dau','ses','len','imp','ad','iap','ua','d1','d7','d30','crash','rating'];
function toCSV(rows){return CSV_COLS.join(',')+'\n'+rows.map(r=>CSV_KEYS.map(k=>r[k]).join(',')).join('\n')}
function parseCSV(txt){
 const lines=txt.trim().split(/\r?\n/);if(lines.length<2)return[];const hd=lines[0].split(',').map(h=>h.trim().toLowerCase());
 const idx=CSV_COLS.map(c=>hd.indexOf(c));if(idx[0]<0||idx[1]<0)return[];
 return lines.slice(1).map(l=>{const c=l.split(',');const o={};CSV_KEYS.forEach((k,i)=>{const v=idx[i]>=0?c[idx[i]]?.trim():'';o[k]=(k==='d'||k==='g')?v:(v===''||v==null?null:(+v||0))});return o}).filter(o=>/^\d{4}-\d{2}-\d{2}$/.test(o.d)&&o.g);
}
function importRows(rows){
 if(!rows.length)return 0;const key=r=>r.g+'|'+r.d;const nk=new Set(rows.map(key));
 rows.forEach(r=>{if(!gById(r.g))S.games.push({id:r.g,name:{en:r.g,ar:r.g},genre:{en:'Imported',ar:'مستوردة'},levels:0,status:'live',version:'1.0',platform:'iOS',color:'#27e2ff',p:{},funnel:null});else{const g=gById(r.g);if(!g.p)g.p={}}
  if(r.paid==null)r.paid=r.ua?r.inst:0});
 S.daily=S.daily.filter(r=>!nk.has(key(r))).concat(rows).sort((a,b)=>a.d.localeCompare(b.d));return rows.length;
}

/* ================= modal / toast ================= */
function toast(m){const el=$('#toast');el.textContent=m;el.hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>el.hidden=true,2600)}
function modal(title,fields,onSave,extra=''){
 const root=$('#modal-root');
 root.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><form class="box" id="mform"><h2>${esc(title)}</h2><div class="form">${fields.map(f=>`<div class="field ${f.full?'full':''}"><label for="mf-${f.k}">${esc(f.l)}</label>${f.type==='select'?`<select class="inp" id="mf-${f.k}" name="${f.k}">${f.opts.map(o=>`<option value="${esc(o[0])}" ${String(f.v)===String(o[0])?'selected':''}>${esc(o[1])}</option>`).join('')}</select>`:`<input class="inp" id="mf-${f.k}" name="${f.k}" type="${f.type||'text'}" value="${esc(f.v??'')}" ${f.req?'required':''} ${f.step?`step="${f.step}"`:''}>`}</div>`).join('')}</div>${extra}
 <div class="act"><button type="button" class="btn" data-mclose>${t('cancel')}</button><button class="btn pri" type="submit">${t('save')}</button></div></form></div>`;
 const fm=$('#mform');setTimeout(()=>fm.querySelector('input,select')?.focus(),30);
 fm.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(fm));onSave(d);root.innerHTML='';render()};
 root.querySelector('.modal').onclick=e=>{if(e.target.classList.contains('modal')||e.target.hasAttribute('data-mclose'))root.innerHTML=''};
}
function confirmBox(msg,fn){const root=$('#modal-root');root.innerHTML=`<div class="modal" role="alertdialog" aria-modal="true"><div class="box" style="width:min(420px,100%)"><h2>${esc(msg)}</h2><div class="act"><button class="btn" data-mclose>${t('cancel')}</button><button class="btn pri" id="cf-ok">${tr('Confirm','تأكيد','Bestätigen')}</button></div></div></div>`;
 $('#cf-ok').onclick=()=>{root.innerHTML='';fn()};root.querySelector('.modal').onclick=e=>{if(e.target.classList.contains('modal')||e.target.hasAttribute('data-mclose'))root.innerHTML=''}}
const gameOpts=(liveOnly)=>S.games.filter(g=>!liveOnly||g.p).map(g=>[g.id,tx(g.name)]);
